  },
  AvgVideoCaption_100284_Content_71 = {
    Text = "Saya... saya..."
  },
  AvgVideoCaption_100284_Content_72 = {
    Text = "Betul sekali, Anda pasti juga merasakannya, kan!"
  },
  AvgVideoCaption_100284_Content_73 = {
    Text = "Hasrat yang tersembunyi dalam diri, menggigit dan melahap!"
