  },
  AvgVideoCaption_100284_Content_77 = {
    Text = "Pergi...... Aku ingin pergi dari sini! Lepaskan aku, Pigman!"
  },
  AvgVideoCaption_100284_Content_78 = {
    Text = "Cicipi mereka, Tuan Matthew"
  },
  AvgVideoCaption_100284_Content_79 = {
    Text = "Sakit, Kegilaan, Mengingat, Kelaparan, Kerinduan, Salah arah…"
  },
  AvgVideoCaption_100284_Content_8 = {
