  AvgVideoCaption_100284_Content_9 = {
    Text = "Lukisan mayat hidup yang membanjiri"
  },
  AvgVideoCaption_100284_Content_90 = {
    Text = "Saya selalu sangat menghormati model, bagaimana mungkin tega menyakiti?"
