  AvgVideoCaption_100284_Content_96 = {
    Text = "Berteriak di ibukota…"
  },
  AvgVideoCaption_100284_Content_97 = {
    Text = "Begitu kegilaan… begitu… serakah…"
  },
  AvgVideoCaption_100284_Content_98 = {
    Text = "Hari ini adalah hari yang sangat indah!"
  },
  AvgVideoCaption_100284_Content_99 = {
    Text = "Saya mendapatkan seorang teman, dan Anda melihat seni yang sejati"
  },
  AvgVideoCaption_117618_Content_1 = {
    Text = "Melarikan diri, menolak penangkapan, membunuh penjaga lampu"
  },
  AvgVideoCaption_117618_Content_10 = {
    Text = "Pollux hanya ingin melihat dunia luar!"
  },
  AvgVideoCaption_117618_Content_100 = {
    Text = "Banyak sekali tulisan, apakah saya sudah menulis sebanyak ini?"
  },
  AvgVideoCaption_117618_Content_101 = {
    Text = "Ini adalah... apa?"
  },
  AvgVideoCaption_117618_Content_102 = {
    Text = "Siapa itu Kastor...?"
  },
  AvgVideoCaption_117618_Content_103 = {
    Text = "Tulisan-tulisan ini, kenapa tidak bisa terbaca..."
  },
  AvgVideoCaption_117618_Content_104 = {
    Text = "Sangat sedih, kenapa tiba-tiba ingin menangis…"
  },
  AvgVideoCaption_117618_Content_105 = {
    Text = "Bagus, Pollux"
  },
  AvgVideoCaption_117618_Content_106 = {
    Text = "Hari ini kau harus mengikuti aku untuk membaca dengan serius tindakan suci Pembawa Cahaya"
  },
  AvgVideoCaption_117618_Content_107 = {
    Text = "Rasakan cahaya dan kasih sayangnya dengan sepenuh hati"
  },
  AvgVideoCaption_117618_Content_108 = {
    Text = "Ya, Tuan Lampu"
  },
  AvgVideoCaption_117618_Content_109 = {
    Text = "\"Roh-Nya sejak itu kembali ke tanah suci yang tidak bersalah,\""
  },
  AvgVideoCaption_117618_Content_11 = {
    Text = "Dia hanya terlalu menderita dalam ritual pengubahan..."
  },
  AvgVideoCaption_117618_Content_110 = {
    Text = "\"Tetapi tatapannya tetap penuh kasih terhadap dunia ini.\""
  },
  AvgVideoCaption_117618_Content_111 = {
    Text = "\"Roh-Nya sejak itu kembali ke tanah suci yang tidak bersalah,\""
  },
  AvgVideoCaption_117618_Content_112 = {
    Text = "\"Tetapi tatapannya tetap penuh kasih terhadap dunia ini.\""
  },
  AvgVideoCaption_117618_Content_113 = {
    Text = "\"Dia memberikan darah, daging, dan tulang kepada umat manusia,\""
  },
  AvgVideoCaption_117618_Content_114 = {
    Text = "\"Untuk menerima dan mengarahkan jiwa yang tidak bersalah ke tanah suci,\""
  },
  AvgVideoCaption_117618_Content_115 = {
    Text = "\"Berbagilah bersama-Nya di kerajaan yang suci.\""
  },
  AvgVideoCaption_117618_Content_116 = {
    Text = "\"Dia memberikan darah, daging, dan tulang kepada umat manusia,\""
  },
  AvgVideoCaption_117618_Content_117 = {
    Text = "\"Untuk menerima dan mengarahkan jiwa yang tidak bersalah ke tanah suci,\""
  },
  AvgVideoCaption_117618_Content_118 = {
    Text = "\"Berbagilah bersama-Nya di kerajaan yang suci.\""
  },
  AvgVideoCaption_117618_Content_119 = {Text = "Khe..."},
  AvgVideoCaption_117618_Content_12 = {
    Text = "Jangan menunduk, saudaraku"
  },
  AvgVideoCaption_117618_Content_120 = {
    Text = "Hei, pendosa, saatnya makan"
  },
  AvgVideoCaption_117618_Content_121 = {
    Text = "Bolehkah saya bertanya... bagaimana kabar Putra Pollux hari ini?"
  },
  AvgVideoCaption_117618_Content_122 = {
    Text = "Putra Suci tentu baik, dia hari ini juga mengikuti Tuan Lentera berlatih dengan serius"
  },
  AvgVideoCaption_117618_Content_123 = {
    Text = "Namun, itu adalah hubungannya denganmu?"
  },
  AvgVideoCaption_117618_Content_124 = {
    Text = "Setiap hari bertanya, kau hanyalah..."
  },
  AvgVideoCaption_117618_Content_125 = {
    Text = "Siapa orangnya?"
  },
  AvgVideoCaption_117618_Content_126 = {
    Text = "Sudahlah, bisa berada di dalam pencemaran dosa, tentunya hanyalah seorang pendosa"
  },
  AvgVideoCaption_117618_Content_127 = {
    Text = "Lebih baik kamu tidak terlalu banyak menyelidiki tentang Sang Santo."
  },
  AvgVideoCaption_117618_Content_128 = {
    Text = "Mereka... Kenapa tidak mengingatku lagi?"
  },
  AvgVideoCaption_117618_Content_129 = {
    Text = "Apakah itu digantikan dengan sumbu lampu yang baru..."
  },
  AvgVideoCaption_117618_Content_13 = {
    Text = "Itu aku, aku yang menyerang Penjaga Lampu!"
  },
  AvgVideoCaption_117618_Content_130 = {
    Text = "Pollux... aku pasti akan menunggu..."
  },
  AvgVideoCaption_117618_Content_131 = {
    Text = "Apa pun lamanya, aku akan bertahan, aku akan menunggu hari kita bertemu kembali..."
  },
  AvgVideoCaption_117618_Content_14 = {
    Text = "Jika harus dihukum, silakan hukum aku! Tidak... tidak!"
  },
  AvgVideoCaption_117618_Content_15 = {
    Text = "Terus bertahan, demi kebebasa"
  },
  AvgVideoCaption_117618_Content_16 = {Text = "Aah——"},
  AvgVideoCaption_117618_Content_17 = {
    Text = "Pollux! Pff……"
  },
  AvgVideoCaption_117618_Content_18 = {
    Text = "Oh, hampir lupa bahwa anak suci Kastor baru saja terluka parah"
  },
  AvgVideoCaption_117618_Content_19 = {
    Text = "Sembuh? Tidak perlu, buang Castor ke \"Lumpur Dosa\" saja"
  },
  AvgVideoCaption_117618_Content_2 = {
    Text = "Ini adalah pengembalian putra suci kami kepada gereja?"
  },
  AvgVideoCaption_117618_Content_20 = {
    Text = "Darah Dewa akan membersihkan segala dosanya"
  },
  AvgVideoCaption_117618_Content_21 = {
    Text = "Tunggu sampai semua dosa mengering, barulah biarkan dia keluar"
  },
  AvgVideoCaption_117618_Content_22 = {
    Text = "Kak... Kak..."
  },
  AvgVideoCaption_117618_Content_23 = {
    Text = "Baiklah, sekarang, saatnya untuk Putra Suci kita"
  },
  AvgVideoCaption_117618_Content_24 = {
    Text = "Baiklah, mari kita pelajari ajaran Pembawa Lampu dengan baik"
  },
  AvgVideoCaption_117618_Content_25 = {
    Text = "Mulai hari ini, aku sebagai guru, akan membawamu memahami teks suci"
  },
  AvgVideoCaption_117618_Content_27 = {
    Text = "Saya sebenarnya sangat mengerti Anda, dan saya juga mengagumi keberanian Anda"
  },
  AvgVideoCaption_117618_Content_28 = {
    Text = "Pollux, kamu benar-benar anak yang cerdas"
  },
  AvgVideoCaption_117618_Content_29 = {
    Text = "Hanya saja, kecerdasan ini tidak digunakan pada tempat yang tepat"
  },
  AvgVideoCaption_117618_Content_3 = {
    Text = "Ceritakan, siapa yang merencanakan semua ini?"
  },
  AvgVideoCaption_117618_Content_30 = {
    Text = "Sebaliknya, itu membuatmu menghindar dari misi melayani pemegang lampu"
  },
  AvgVideoCaption_117618_Content_31 = {
    Text = "Memang, ritual transformasi itu menyakitkan, bukan?"
  },
  AvgVideoCaption_117618_Content_32 = {
    Text = "Pemegang lampu juga mengalami banyak penderitaan di jalan yang menyebarkan cahaya"
  },
  AvgVideoCaption_117618_Content_33 = {
    Text = "Ia bahkan mengorbankan tubuhnya sendiri untuk menebus dosa umat manusia"
  },
  AvgVideoCaption_117618_Content_34 = {
    Text = "Mungkin kamu belum bisa mencapai belas kasih-Nya, belum dapat memahami keinginan pengorbanan itu, hal ini sangat wajar."
  },
  AvgVideoCaption_117618_Content_35 = {
    Text = "Ketika orang biasa mencoba memahami tindakan dan perkataan dewa, mereka pasti akan penuh dengan kebingungan dan kelemahan."
  },
  AvgVideoCaption_117618_Content_36 = {
    Text = "Yang kamu butuhkan hanyalah lebih banyak belajar, dan memahami..."
  },
  AvgVideoCaption_117618_Content_37 = {
    Text = "Sigh, bagaimanapun juga, Kastor masih terluka parah dan dalam keadaan berbahaya"
  },
  AvgVideoCaption_117618_Content_38 = {
    Text = "Untuk segera membersihkan dosa dosamu"
  },
  AvgVideoCaption_117618_Content_39 = {
    Text = "Kamu juga harus segera mengambil tanggung jawab Sang Santo."
  },
  AvgVideoCaption_117618_Content_4 = {Text = "Iya..."},
  AvgVideoCaption_117618_Content_40 = {
    Text = "……Maaf, Tuan Lampu, saya akan belajar"
  },
  AvgVideoCaption_117618_Content_41 = {
    Text = "Bagus, maka ikuti saya dan bacalah dengan hati-hati tindakan kudus dari sang Pembawa Lampu"
  },
  AvgVideoCaption_117618_Content_42 = {
    Text = "Rasakan dengan hati ajaran yang Dia berika"
  },
  AvgVideoCaption_117618_Content_43 = {
    Text = "……Ya, Tuan Lampu"
  },
  AvgVideoCaption_117618_Content_44 = {
    Text = "\"Dia memegang api abadi, berjalan di atas bumi yang gelap.\""
  },
  AvgVideoCaption_117618_Content_45 = {
