  },
  AvgVideoCaption_117618_Content_5 = {Text = "Itu aku"},
  AvgVideoCaption_117618_Content_50 = {
    Text = "Ah! Kakak! Kenapa kau melukai lenganmu sendiri!"
  },
  AvgVideoCaption_117618_Content_51 = {
    Text = "Semua ini salahku, tidak bisa menggantikanmu untuk mengubah ritual"
  },
  AvgVideoCaption_117618_Content_52 = {
    Text = "Setidaknya, biarkan aku merasakan penderitaan yang sama sepertimu…"
  },
  AvgVideoCaption_117618_Content_53 = {Text = "Kakak!"},
  AvgVideoCaption_117618_Content_54 = {
    Text = "Hmm... jahat, kepalaku sakit sekali..."
  },
  AvgVideoCaption_117618_Content_55 = {
    Text = "Wanita itu pasti telah melakukan sesuatu padaku"
  },
  AvgVideoCaption_117618_Content_56 = {
    Text = "Wajah kakakku terbayang di benakku, mengapa menjadi sedikit kabur..."
  },
  AvgVideoCaption_117618_Content_57 = {
    Text = "Catat, harus dicatat... tidak, tidak boleh menggunakan kertas, nanti akan ketahuan..."
  },
  AvgVideoCaption_117618_Content_58 = {
    Text = "Ya, ukir itu, ukir di tempat yang tersembunyi..."
  },
  AvgVideoCaption_117618_Content_59 = {
    Text = "Tercetak di bawah ranjang! Mereka tidak akan menemukan tempat ini..."
  },
  AvgVideoCaption_117618_Content_6 = {
    Text = "Anda harus tahu bahwa orang kikuk seperti Castor tidak akan memiliki pikiran seperti itu"
  },
  AvgVideoCaption_117618_Content_60 = {
    Text = "Catat semua yang kita rencanakan sejak lahir, dan semua jalur eksplorasi sedikit demi sedikit, semuanya!"
  },
  AvgVideoCaption_117618_Content_61 = {
    Text = "Anda tidak akan berhasil mencuri kehendak saya!"
  },
  AvgVideoCaption_117618_Content_62 = {
    Text = "Tunggu aku, kakak, aku pasti akan menemukan kesempatan untuk membawamu melarikan diri lagi..."
  },
  AvgVideoCaption_117618_Content_63 = {
    Text = "Hari ini, kita akan melanjutkan membaca tindakan suci Pembawa Cahaya"
  },
  AvgVideoCaption_117618_Content_64 = {
    Text = "……Ya, Tuan Lampu"
  },
  AvgVideoCaption_117618_Content_65 = {
    Text = "\"Darah-Nya menghapuskan dosa, membebaskan jiwa semua orang di dunia ini dari dosa.\""
  },
  AvgVideoCaption_117618_Content_66 = {
    Text = "\"Darah-Nya menghapuskan dosa, membebaskan jiwa semua orang di dunia ini dari dosa.\""
  },
  AvgVideoCaption_117618_Content_67 = {
    Text = "\"Namun dunia tetap diselubungi kegelapan yang tanpa akhir,\""
  },
  AvgVideoCaption_117618_Content_68 = {
    Text = "\"Maka Dia dengan cahaya itu, menyalakan tubuhnya sendiri...\""
  },
  AvgVideoCaption_117618_Content_69 = {
    Text = "\"Namun dunia tetap diselubungi kegelapan yang tanpa akhir,\""
  },
  AvgVideoCaption_117618_Content_7 = {
    Text = "Baik, sangat baik, burung-burung yang merindukan langit, betapa mengharukannya cerita ini"
  },
  AvgVideoCaption_117618_Content_70 = {
    Text = "\"Maka Dia dengan cahaya itu, menyalakan tubuhnya sendiri...\""
  },
  AvgVideoCaption_117618_Content_71 = {
    Text = "Lilin? Dari mana kamu mendapatkannya?"
  },
  AvgVideoCaption_117618_Content_72 = {
    Text = "Hei hei, aku tentu yang paling hebat!"
  },
  AvgVideoCaption_117618_Content_73 = {
    Text = "Dengan cara ini kita bisa secara diam-diam melihat manuskrip ini di malam hari"
  },
  AvgVideoCaption_117618_Content_74 = {
    Text = "Kami bersembunyi agar tidak terdeteksi..."
  },
  AvgVideoCaption_117618_Content_75 = {
    Text = "Ha... cepat bangun, kita harus terus mengukir, mengukir ingatan kita..."
  },
  AvgVideoCaption_117618_Content_76 = {
    Text = "Sampai di mana kita, setelah kita pertama kali diam-diam belajar terbang"
  },
  AvgVideoCaption_117618_Content_77 = {
    Text = "Kemudian terbang pergi... kemudian terbang ke mana?"
  },
  AvgVideoCaption_117618_Content_78 = {
    Text = "Pollux! Otak yang tidak berguna, ingatlah, ingatlah cepat"
  },
  AvgVideoCaption_117618_Content_79 = {
    Text = "Kamu tidak bisa melupakan! Kamu sama sekali tidak bisa..."
  },
  AvgVideoCaption_117618_Content_8 = {
    Text = "Jika barang-barang yang tidak berguna ini begitu mengganggu, lebih baik kita cabut saja?"
  },
  AvgVideoCaption_117618_Content_80 = {
    Text = "Hari ini, kita akan melanjutkan membaca tindakan suci Pembawa Cahaya"
  },
  AvgVideoCaption_117618_Content_81 = {
    Text = "Ya... Tuan Lampu"
  },
  AvgVideoCaption_117618_Content_82 = {
    Text = "\"Cahaya megah memancar dari tubuh-Nya,\""
  },
  AvgVideoCaption_117618_Content_83 = {
    Text = "\"Daging dan tulangnya mengkristal menjadi perak murni di dalam api.\""
  },
  AvgVideoCaption_117618_Content_84 = {
    Text = "\"Cahaya megah memancar dari tubuh-Nya,\""
  },
  AvgVideoCaption_117618_Content_85 = {
    Text = "\"Daging dan tulangnya mengkristal menjadi perak murni di dalam api.\""
  },
  AvgVideoCaption_117618_Content_86 = {
    Text = "\"Dia mencopot daging dan tulang perak itu,\""
  },
  AvgVideoCaption_117618_Content_87 = {
    Text = "\"Anugerah bagi orang-orang benar di dunia ini, untuk membayar dosa mereka...\""
  },
  AvgVideoCaption_117618_Content_88 = {
    Text = "\"Dia mencopot daging dan tulang perak itu,\""
  },
  AvgVideoCaption_117618_Content_89 = {
    Text = "\"Anugerah bagi orang-orang benar di dunia ini, untuk membayar dosa mereka...\""
  },
  AvgVideoCaption_117618_Content_9 = {
    Text = "Apa... tunggu! Tuan Pembawa Cahaya! Tolong pertimbangkan lagi!"
  },
  AvgVideoCaption_117618_Content_90 = {
    Text = "Pollux! Kamu telah mengeluarkan banyak darah……"
  },
  AvgVideoCaption_117618_Content_91 = {
    Text = "Bagaimana jika kita kembali bersama mereka…"
  },
  AvgVideoCaption_117618_Content_92 = {
    Text = "Tidak... Cepat pergi, jangan berhenti! Jika kita kembali, kita hanya akan kehilangan lebih banyak hal..."
  },
  AvgVideoCaption_117618_Content_93 = {
    Text = "Pollux... Pollux..."
  },
  AvgVideoCaption_117618_Content_94 = {Text = "Ah……"},
  AvgVideoCaption_117618_Content_95 = {
    Text = "Apa yang ingin saya lakukan......?"
  },
  AvgVideoCaption_117618_Content_96 = {
    Text = "Ya, aku akan bangkit, aku akan mencatat beberapa hal..."
  },
  AvgVideoCaption_117618_Content_97 = {
    Text = "Sebenarnya, itu dicatat di mana?"
  },
  AvgVideoCaption_117618_Content_98 = {
    Text = "Bukan di sini, bukan di sini..."
  },
  AvgVideoCaption_117618_Content_99 = {
    Text = "Ya, ya, di bawah tempat tidur..."
  },
  AvgVideoCaption_117956_Content_1 = {
    Text = "Biarkan aku lihat"
  },
  AvgVideoCaption_117956_Content_10 = {
    Text = "Hei! Anak kecil, tunggu!"
  },
  AvgVideoCaption_117956_Content_100 = {
    Text = "Bukan angin, tetapi sangat ringan, sangat dekat, semakin dekat"
  },
  AvgVideoCaption_117956_Content_101 = {
    Text = "Seperti seseorang yang menyeret tubuhnya, perlahan merangkak menuju pintu Anda"
  },
  AvgVideoCaption_117956_Content_102 = {
    Text = "Duk, duk, duk. Seseorang mengetuk pintu kamarmu!"
  },
  AvgVideoCaption_117956_Content_103 = {
    Text = "Kamu ketakutan dan menyusut ke dalam selimut, seluruh tubuh bergetar, berpura-pura tidak ada."
  },
  AvgVideoCaption_117956_Content_104 = {
    Text = "Segera, suara ketukan berhenti"
  },
  AvgVideoCaption_117956_Content_105 = {
    Text = "Hanya ada kesunyian yang tersisa di dalam ruangan, sunyi yang membuat Anda cemas"
  },
  AvgVideoCaption_117956_Content_106 = {
    Text = "Kamu tidak bisa menahan diri untuk melihat dari celah selimut..."
  },
  AvgVideoCaption_117956_Content_107 = {
    Text = "Pintu, terbuka sedikit!"
  },
  AvgVideoCaption_117956_Content_108 = {
    Text = "Kamu menundukkan kepala, sebuah bayangan yang lebih gelap daripada kegelapan, ada di samping tempat tidurmu!"
  },
  AvgVideoCaption_117956_Content_109 = {
    Text = "Kamu ingin berteriak, tetapi sudah terlambat."
  },
  AvgVideoCaption_117956_Content_11 = {
    Text = "Eh, berikan sedikit permen labu yang baru saja kau ambil!"
  },
  AvgVideoCaption_117956_Content_110 = {
    Text = "Tangan Eddie yang dingin seperti paku es sudah menggenggam pergelangan kakimu"
  },
  AvgVideoCaption_117956_Content_111 = {
    Text = "Dia melompat ke arahmu, secepat kilat hitam!"
  },
  AvgVideoCaption_117956_Content_112 = {
    Text = "Kamu mencium! Bau debu itu, bau lembap."
  },
  AvgVideoCaption_117956_Content_113 = {
    Text = "Ada sedikit rasa permen yang manis hingga membuat enek, sampai membuat mual!"
  },
  AvgVideoCaption_117956_Content_114 = {
    Text = "Tangan Eddie tiba-tiba meluncur ke arah tempat kamu menyimpan permen!"
  },
  AvgVideoCaption_117956_Content_115 = {
    Text = "Di bawah bantal! Di dalam tas! Tidak peduli seberapa baik kau menyembunyikannya!"
  },
  AvgVideoCaption_117956_Content_116 = {
    Text = "Krek, krak, dia sedang makan! Makan dengan gila!"
  },
  AvgVideoCaption_117956_Content_117 = {
    Text = "Cokelatmu! Permen lunakmu! Permen stikmu!"
  },
  AvgVideoCaption_117956_Content_118 = {
    Text = "Tidak ada yang terlewatkan! Suara itu seperti menggerogoti tulang!"
  },
  AvgVideoCaption_117956_Content_119 = {
    Text = "Apa kamu pikir dia akan pergi setelah makan permen?"
  },
  AvgVideoCaption_117956_Content_12 = {
    Text = "Kenapa? Berdasarkan keagungan nyonya ini..."
  },
  AvgVideoCaption_117956_Content_120 = {
    Text = "Tidak, rasa lapar yang dia alami... baru saja terbangkit!"
  },
  AvgVideoCaption_117956_Content_121 = {
    Text = "\"Tidak cukup, tidak cukup... masih butuh yang lebih manis, yang termanis...\""
  },
  AvgVideoCaption_117956_Content_122 = {
    Text = "Tatapan rakus Eddie terpaku padamu"
  },
  AvgVideoCaption_117956_Content_123 = {
    Text = "Tangan dingin itu, lengket dengan sirup, menjulur ke arah wajahmu!"
  },
  AvgVideoCaption_117956_Content_124 = {
    Text = "Jarinya menyentuh kelopak matamu, plop!"
  },
  AvgVideoCaption_117956_Content_125 = {
    Text = "Dia mengambil sesuatu yang dia anggap paling mirip permen, bulat dan masih hangat..."
  },
  AvgVideoCaption_117956_Content_126 = {Text = "Matamu!"},
  AvgVideoCaption_117956_Content_127 = {
    Text = "Kemudian... buka!"
  },
  AvgVideoCaption_117956_Content_128 = {
    Text = "Dia menemukan \"gula\" yang dia anggap paling manis"
  },
  AvgVideoCaption_117956_Content_129 = {
    Text = "Tersembunyi di dalam tengkorakmu..."
  },
  AvgVideoCaption_117956_Content_13 = {
    Text = "Hei! Jangan pergi! Anak kecil yang tidak sopan!!!"
  },
  AvgVideoCaption_117956_Content_130 = {
    Text = "Di pagi hari berikutnya, orang-orang akan menemukanmu"
  },
  AvgVideoCaption_117956_Content_131 = {
    Text = "Di wajahmu yang dulunya ada mata, kini hanya tersisa dua lubang hitam kosong."
  },
  AvgVideoCaption_117956_Content_132 = {
    Text = "Di samping bantalmu, tergeletak kertas permen yang dijilati bersih hingga berkilau"
  },
  AvgVideoCaption_117956_Content_133 = {
    Text = "Dan semua permen yang kau sembunyikan di dalam kamarmu"
  },
  AvgVideoCaption_117956_Content_134 = {
    Text = "Semua telah lenyap, satu pun tidak tersisa."
  },
  AvgVideoCaption_117956_Content_135 = {
    Text = "Jadi, malam ini, ketika kalian memegang penuh toples perme"
  },
  AvgVideoCaption_117956_Content_136 = {
    Text = "Ketika berbaring di tempat tidur dengan puas"
  },
  AvgVideoCaption_117956_Content_137 = {
    Text = "Hati-hati, Eddie sudah mengawasi dirimu secara diam-diam…"
  },
  AvgVideoCaption_117956_Content_138 = {
    Text = "Menguncikan pintu? Tak ada gunanya"
  },
  AvgVideoCaption_117956_Content_139 = {
    Text = "Simpan baik-baik permen? Dia bisa mencium baunya!"
  },
  AvgVideoCaption_117956_Content_14 = {
    Text = "Jahat sekali, memukul anak kecil sepertinya bukan tindakan seorang perempuan terhormat, tetapi permen labu milikku..."
  },
  AvgVideoCaption_117956_Content_140 = {
    Text = "Bagaimana, takutkah kamu"
  },
  AvgVideoCaption_117956_Content_141 = {
    Text = "Serahkan semua permen kepada nona ini... ah, penyihir ini!"
  },
  AvgVideoCaption_117956_Content_142 = {
    Text = "Penyihir permen akan menjaga permen lezat ini untuk kalian!"
  },
  AvgVideoCaption_117956_Content_143 = {
    Text = "Apa itu penyihir permen?"
  },
  AvgVideoCaption_117956_Content_144 = {
    Text = "Apakah kamu tidak melihat topi penyihir di kepalaku?"
  },
  AvgVideoCaption_117956_Content_145 = {
    Text = "Ini bukan kostum pertunjukan"
  },
  AvgVideoCaption_117956_Content_146 = {
    Text = "Lihatlah, lihatlah, inilah sihir penyihir!"
  },
  AvgVideoCaption_117956_Content_147 = {
    Text = "Kalian tenang saja, pelukan penyihir permen adalah tempat terbaik untuk semua permen!"
  },
  AvgVideoCaption_117956_Content_148 = {
    Text = "Lalu aku harus bagaimana?"
  },
  AvgVideoCaption_117956_Content_149 = {
    Text = "Tentu saja saya tidak takut hantu, penyihir keadilan akan mengalahkannya dengan mudah..."
  },
  AvgVideoCaption_117956_Content_15 = {
    Text = "Sudah! Selama kita menakut-nakuti mereka, hehehe..."
  },
  AvgVideoCaption_117956_Content_150 = {
    Text = "Hm? Siapa di antara kalian yang terus-menerus menyentuh pergelangan kakiku, tidak tahu bahwa itu sangat tidak sopan?"
  },
  AvgVideoCaption_117956_Content_151 = {
    Text = "Tidak ada orang?"
  },
  AvgVideoCaption_117956_Content_152 = {
    Text = "Kenapa, saya baru saja jelas..."
  },
  AvgVideoCaption_117956_Content_153 = {
    Text = "Siapa yang bercanda, ini tidak lucu!"
  },
  AvgVideoCaption_117956_Content_154 = {
    Text = "Tunggu, apa yang kalian lihat?"
  },
  AvgVideoCaption_117956_Content_155 = {
    Text = "Ada bayangan di belakangku? Di mana? Tak ada orang?!"
  },
  AvgVideoCaption_117956_Content_156 = {
    Text = "Kenapa saya mencium bau debu dan pakaian tua..."
  },
  AvgVideoCaption_117956_Content_157 = {
    Text = "Tidak, ini tidak mungkin, ini jelas adalah yang aku buat..."
  },
  AvgVideoCaption_117956_Content_158 = {
    Text = "Kalian sedang tertawa tentang apa? Ada yang lucu? Ah!!!"
  },
  AvgVideoCaption_117956_Content_159 = {
    Text = "Kenapa saya tidak bisa melihat?! Mataku, siapa?!"
  },
  AvgVideoCaption_117956_Content_16 = {
    Text = "Tunggu, meskipun kalian serakah, pelit, dan kasar"
  },
  AvgVideoCaption_117956_Content_160 = {
    Text = "Lepaskan aku!! Tolong—"
  },
  AvgVideoCaption_117956_Content_161 = {
    Text = "Jenkins?! Tikus kecil?!"
  },
  AvgVideoCaption_117956_Content_162 = {
    Text = "Kapan kalian datang?"
  },
  AvgVideoCaption_117956_Content_163 = {
    Text = "Baiklah, tadi kalian yang mempermainkanku!"
  },
  AvgVideoCaption_117956_Content_164 = {
    Text = "Saya, saya sama sekali tidak takut hantu"
  },
  AvgVideoCaption_117956_Content_165 = {
    Text = "Diam! Jangan tertawa!!"
  },
  AvgVideoCaption_117956_Content_166 = {
    Text = "Aaargh! Bajingan tikus!!!"
  },
  AvgVideoCaption_117956_Content_167 = {
    Text = "Jangan lari, aku belum selesai dengan kalian!!!"
  },
  AvgVideoCaption_117956_Content_17 = {
    Text = "Apakah kalian tidak takut jika hantu permen mengejar kalian?"
  },
  AvgVideoCaption_117956_Content_18 = {
    Text = "Apa itu hantu permen?"
  },
  AvgVideoCaption_117956_Content_19 = {
    Text = "Hm, cium baik-baik"
  },
  AvgVideoCaption_117956_Content_2 = {
    Text = "Seperti yang tertulis di poster festival para suci, lokasi terakhir untuk pembagian permen..."
  },
  AvgVideoCaption_117956_Content_20 = {
    Text = "Di udara selain aroma toffee"
  },
  AvgVideoCaption_117956_Content_21 = {
    Text = "Apakah ada bau yang dipenuhi debu, pakaian lama, dan sedikit aroma lembab..."
  },
  AvgVideoCaption_117956_Content_22 = {
    Text = "Ya, begitulah, dekati sedikit"
  },
  AvgVideoCaption_117956_Content_23 = {
    Text = "Kalian harus mendengarkan dengan saksama."
  },
  AvgVideoCaption_117956_Content_24 = {
    Text = "Cerita tentang roh lapar ini......"
  },
  AvgVideoCaption_117956_Content_25 = {
    Text = "Bertahun-tahun yang lalu—"
  },
  AvgVideoCaption_117956_Content_26 = {
    Text = "Mungkin ketika kakek buyut kalian masih seorang bocah"
  },
  AvgVideoCaption_117956_Content_27 = {
    Text = "Di tanah Mythag ini, pernah ada seseorang bernama Eddie..."
  },
  AvgVideoCaption_117956_Content_28 = {
    Text = "Ya, siswa Eddie Hop"
  },
  AvgVideoCaption_117956_Content_29 = {
    Text = "Eddie yang malang adalah seorang anak lelaki yang kurus"
  },
  AvgVideoCaption_117956_Content_3 = {
    Text = "Inilah tempatnya!"
  },
  AvgVideoCaption_117956_Content_30 = {
    Text = "Seragam lama itu menggantung kosong di tubuhnya"
  },
  AvgVideoCaption_117956_Content_31 = {
    Text = "Seperti yang tergantung di ladang, dibuat dari ranting pohon kering yang membentuk orang-orangan sawah"
  },
  AvgVideoCaption_117956_Content_32 = {
    Text = "Mengapa dia begitu kurus?"
  },
  AvgVideoCaption_117956_Content_33 = {
    Text = "Eh, karena Eddie adalah seorang anak yatim"
  },
  AvgVideoCaption_117956_Content_34 = {
    Text = "Dan pada saat itu, Mythag pasti kecil dan miskin, wajar jika semua orang tidak bisa makan dengan baik!"
  },
  AvgVideoCaption_117956_Content_35 = {
    Text = "Semua itu tidak penting, yang jelas"
  },
  AvgVideoCaption_117956_Content_36 = {
    Text = "Eddie tidak suka berbicara, dia selalu sendirian, pergi melakukan tugas berbahaya sendirian"
  },
  AvgVideoCaption_117956_Content_37 = {
    Text = "Sayangnya, dia dengan cepat terjangkit penyakit mengerikan yang mengerikan"
  },
  AvgVideoCaption_117956_Content_38 = {
    Text = "Dagingnya perlahan-lahan terkorosi oleh lendir hitam, dan wajahnya pun muncul satu per satu lubang"
  },
  AvgVideoCaption_117956_Content_39 = {
    Text = "Kadang tanpa sengaja, plok"
  },
  AvgVideoCaption_117956_Content_4 = {
    Text = "Apa? Kenapa ada sekelompok anak lagi"
  },
  AvgVideoCaption_117956_Content_40 = {
    Text = "Sebuah wajah yang tampaknya langsung jatuh, bergoyang-goyang menggantung di wajahnya..."
  },
  AvgVideoCaption_117956_Content_41 = {
    Text = "Tidak hanya itu, dia menemukan bahwa dia juga perlahan-lahan diingat kembali oleh orang-orang di sekelilingnya"
  },
  AvgVideoCaption_117956_Content_42 = {
    Text = "Tidak ada yang mengingat asrama ini"
  },
  AvgVideoCaption_117956_Content_43 = {
    Text = "Ada satu lagi yang terbaring di tempat tidur, makhluk malang"
  },
  AvgVideoCaption_117956_Content_44 = {
    Text = "Akhirnya, Eddie menjadi tidak lagi memiliki tenaga untuk maka"
  },
  AvgVideoCaption_117956_Content_45 = {
    Text = "Air pun tidak memiliki tenaga untuk diminum"
  },
  AvgVideoCaption_117956_Content_46 = {
    Text = "Dia kelaparan hingga perutnya menempel di punggung, tenggorokannya kering seperti terbakar."
  },
  AvgVideoCaption_117956_Content_47 = {
    Text = "Tetapi hanya bisa mengerang kesakitan di tempat tidur"
  },
  AvgVideoCaption_117956_Content_48 = {
    Text = "Apa hubungan antara cerita ini dan hantu permen?"
  },
  AvgVideoCaption_117956_Content_49 = {
    Text = "Jangan terburu-buru, dengarkan dengan baik dan kau akan tahu"
  },
  AvgVideoCaption_117956_Content_5 = {
    Text = "Apakah biasanya ada begitu banyak keluarga di sekolah Mythag?"
  },
  AvgVideoCaption_117956_Content_50 = {
    Text = "Pada malam hari perayaan semua santo."
  },
  AvgVideoCaption_117956_Content_51 = {
    Text = "Tiba-tiba dia mendengar suara tawa samar dari bawah"
  },
  AvgVideoCaption_117956_Content_52 = {
    Text = "Anak-anak berteriak, \"Permen atau aku akan mengacau!\""
  },
  AvgVideoCaption_117956_Content_53 = {
    Text = "Satu demi satu berlari melewati jendelanya"
  },
  AvgVideoCaption_117956_Content_54 = {
    Text = "Suara tawa yang ceria, aroma toffee yang samar"
  },
  AvgVideoCaption_117956_Content_55 = {
    Text = "Seperti cakar jahat yang mencengkeram dan menggaruk dadanya"
  },
  AvgVideoCaption_117956_Content_56 = {
    Text = "Mengapa, mengapa diriku dilupakan?"
  },
  AvgVideoCaption_117956_Content_57 = {
    Text = "Mengapa tidak ada yang datang untuk merawat diri sendiri?"
  },
  AvgVideoCaption_117956_Content_58 = {
    Text = "Ketakutan yang terlupakan dan rasa sakit karena sakit terus menyiksanya"
  },
  AvgVideoCaption_117956_Content_59 = {
    Text = "Tiba-tiba, keinginan yang besar menimpa dirinya sepenuhnya"
  },
  AvgVideoCaption_117956_Content_6 = {
    Text = "Cepat, cepat..."
  },
  AvgVideoCaption_117956_Content_60 = {
    Text = "Dia telah membuat sebuah keputusan, sebuah keputusan yang gila, sebuah keputusan yang putus asa"
  },
  AvgVideoCaption_117956_Content_61 = {
    Text = "Dia ingin mencari permen untuk dimakan! Hanya satu saja!"
  },
  AvgVideoCaption_117956_Content_62 = {
    Text = "Jika malam ini dia akan mati, maka dia pasti ingin mati dalam rasa manis kenangan"
  },
  AvgVideoCaption_117956_Content_63 = {
    Text = "Eddie mengerahkan seluruh tenaga untuk bangkit dari tempat tidur, dia meletakkan kedua tangan di lantai"
  },
  AvgVideoCaption_117956_Content_64 = {
    Text = "Sekecil, sedikit bergerak ke depan..."
  },
  AvgVideoCaption_117956_Content_65 = {
    Text = "Dia membuka pintu yang tipis itu"
  },
  AvgVideoCaption_117956_Content_66 = {
    Text = "Pelan-pelan menuruni tangga yang gelap dan dingin seperti bayangan."
  },
  AvgVideoCaption_117956_Content_67 = {
    Text = "Dia merangkak, merangkak"
  },
  AvgVideoCaption_117956_Content_68 = {
    Text = "Tetapi dia terlalu lemah, terlalu dingin."
  },
  AvgVideoCaption_117956_Content_69 = {
    Text = "Saat ia merangkak sampai ke pintu asrama, dia tidak lagi punya tenaga untuk membuka pintu besar itu"
  },
  AvgVideoCaption_117956_Content_7 = {
    Text = "Ah!! Keranjang permen ternyata kosong"
  },
  AvgVideoCaption_117956_Content_70 = {
    Text = "\"Siapa yang datang... bantu aku... siapa yang datang... berikan aku permen...\""
  },
  AvgVideoCaption_117956_Content_71 = {
    Text = "Tidak ada yang mendengar suaranya, tidak ada yang melihat sosoknya"
  },
  AvgVideoCaption_117956_Content_72 = {
    Text = "Dengan suara kresek, para siswa bahagia membuka pintu besar asrama"
  },
  AvgVideoCaption_117956_Content_73 = {
    Text = "Dan kemudian tak terhitung sepatu menginjak tubuhnya"
  },
  AvgVideoCaption_117956_Content_74 = {
    Text = "Krek, itu suara tulang Eddie yang patah"
  },
  AvgVideoCaption_117956_Content_75 = {
    Text = "Puh, itu suara daging Eddie yang diinjak hancur..."
  },
  AvgVideoCaption_117956_Content_76 = {
    Text = "Suara jeritan putus asa tertutupi oleh suara tawa bahagia"
  },
  AvgVideoCaption_117956_Content_77 = {
    Text = "Sampai ia berubah menjadi noda samar, tangan yang penuh hasrat itu masih terulur ke arah pintu besar..."
  },
  AvgVideoCaption_117956_Content_78 = {
    Text = "Dia sekarat... tidak pernah merasakan permen dalam mimpinya"
  },
  AvgVideoCaption_117956_Content_79 = {
    Text = "Eddie sudah mati"
  },
  AvgVideoCaption_117956_Content_8 = {
    Text = "Sekelompok belalang kecil yang menyebalkan!"
  },
  AvgVideoCaption_117956_Content_80 = {
    Text = "Tetapi rasa laparnya... keinginan yang sangat mendalam untuk permen belum mati."
  },
  AvgVideoCaption_117956_Content_81 = {
    Text = "Ia tertinggal, seperti sirup yang kental, seperti angin dingin di musim dingin yang menyengat"
  },
  AvgVideoCaption_117956_Content_82 = {
    Text = "Setiap tahun, ketika lampion labu menyala, dan aroma permen memenuhi udara, Eddie..."
  },
  AvgVideoCaption_117956_Content_83 = {
    Text = "Atau, rasa haus yang ditinggalkan Eddie akan terbangu"
  },
  AvgVideoCaption_117956_Content_84 = {
    Text = "Dia tidak lagi menjadi anak malang itu"
  },
  AvgVideoCaption_117956_Content_85 = {
    Text = "Dia telah berubah menjadi sesuatu yang lain, yang lebih menakutkan"
  },
  AvgVideoCaption_117956_Content_86 = {
    Text = "Berjalan-jalan di bayangan kampus ini"
  },
  AvgVideoCaption_117956_Content_87 = {
    Text = "Dia bisa mencium bau permen!"
  },
  AvgVideoCaption_117956_Content_88 = {
    Text = "Terutama harta yang kalian simpan dalam keranjang, disembunyikan di ruang ransel, atau dibungkus di saku yang hangat!"
  },
  AvgVideoCaption_117956_Content_89 = {
    Text = "Di malam Pesta Para Kudus, jika kamu membawa banyak permen, saat pulang ke rumah"
  },
  AvgVideoCaption_117956_Content_9 = {
    Text = "Tidak bisa, permen labu rasa aneh ini belum aku cicipi"
  },
  AvgVideoCaption_117956_Content_90 = {
    Text = "Kamu akan merasakan dingin di bagian belakang lehermu, heh... seperti ada seseorang yang membisikkan napas dingin."
  },
  AvgVideoCaption_117956_Content_91 = {
    Text = "Saat kamu menoleh ke belakang, kamu akan melihat tidak ada apa-apa"
  },
  AvgVideoCaption_117956_Content_92 = {
    Text = "Hanya angin, dan bayangan yang aneh..."
  },
  AvgVideoCaption_117956_Content_93 = {
    Text = "Tidak, itu Eddie yang mengikutimu!"
  },
  AvgVideoCaption_117956_Content_94 = {
    Text = "Dia akan mengikuti aroma permen, terus tenang mengikutimu"
  },
  AvgVideoCaption_117956_Content_95 = {
    Text = "Kamu hanya bisa mencium bau lembap yang samar, campuran debu dan pakaian tua."
  },
  AvgVideoCaption_117956_Content_96 = {
    Text = "Sampai tengah malam tiba! Ketika lonceng menara berdentang dua belas kali"
  },
  AvgVideoCaption_117956_Content_97 = {
    Text = "Sekolah sangat sunyi, bahkan burung hantu pun menutup mulut"
  },
  AvgVideoCaption_117956_Content_98 = {
    Text = "Saat ini... kamu akan mendengar suara aneh dari depan pintu kamarmu"
  },
  AvgVideoCaption_117956_Content_99 = {
    Text = "Swoosh... swoosh..."
  },
  AvgVideoCaption_122450_Content_1 = {
    Text = "Keluar, keluar ada di sana…"
  },
  AvgVideoCaption_122450_Content_10 = {
    Text = "Sekarang, biarkan tulang daging yang terbalik terjalin menjadi takdir"
  },
  AvgVideoCaption_122450_Content_11 = {
    Text = "Dengan Tali Pusar Palsu"
  },
  AvgVideoCaption_122450_Content_12 = {
    Text = "Lewati pintu saya yang rapuh ini…"
  },
  AvgVideoCaption_122450_Content_13 = {
    Text = "Kedatangan ke dunia ini!"
  },
  AvgVideoCaption_122450_Content_14 = {
    Text = "Lihat, Dia sudah membuka matanya!"
  },
  AvgVideoCaption_122450_Content_15 = {
    Text = "Peluk aku, sayangku"
  },
  AvgVideoCaption_122450_Content_16 = {
    Text = "Milik saya.."
  },
  AvgVideoCaption_122450_Content_17 = {Text = "Ayahku."},
  AvgVideoCaption_122450_Content_18 = {Text = "Ayahku."},
  AvgVideoCaption_122450_Content_19 = {Text = "Nasib saya"},
  AvgVideoCaption_122450_Content_2 = {
    Text = "Mengapa harus pergi?"
  },
  AvgVideoCaption_122450_Content_3 = {
    Text = "Tidak perlu khawatir, di sini sangat aman"
  },
  AvgVideoCaption_122450_Content_4 = {
    Text = "Jangan... aku tidak ingin menjadi Dewi."
  },
  AvgVideoCaption_122450_Content_5 = {
    Text = "Aku adalah putri dari dewa"
  },
  AvgVideoCaption_122450_Content_6 = {
    Text = "Tidak ada yang bisa menentang kehendakku"
  },
  AvgVideoCaption_122450_Content_7 = {
    Text = "Saya merasakannya"
  },
  AvgVideoCaption_122450_Content_8 = {
    Text = "Sakit yang sempurna"
  },
  AvgVideoCaption_122450_Content_9 = {
    Text = "Dan pematangan yang sempurna"
  },
  AvgVideoCaption_122705_Content_1 = {
    Text = "Itu adalah cerita tujuh hari setelah kelahiran Dewa"
  },
  AvgVideoCaption_122705_Content_10 = {
    Text = "Namun, semua orang di wajah mereka dipenuhi dengan kegembiraan yang penuh semangat"
  },
  AvgVideoCaption_122705_Content_100 = {
    Text = "TerBerbaring di dadaku"
  },
  AvgVideoCaption_122705_Content_101 = {
    Text = "Hanya patung yang hipokrit"
  },
  AvgVideoCaption_122705_Content_102 = {
    Text = "Sebongkah daging mati yang salah disebut sebagai \"Dewa\""
  },
  AvgVideoCaption_122705_Content_103 = {Text = "Kenapa?"},
  AvgVideoCaption_122705_Content_104 = {
    Text = "Mengapa takdir yang terbalik dan tidak adil ini tidak mau melepaskanku?"
  },
  AvgVideoCaption_122705_Content_105 = {
    Text = "Tuhan, mengapa Engkau selalu menghukumku?"
  },
  AvgVideoCaption_122705_Content_106 = {Text = "Dewa...?"},
  AvgVideoCaption_122705_Content_107 = {
    Text = "Hahaha, hahaha, saya mengerti!"
  },
  AvgVideoCaption_122705_Content_108 = {
    Text = "Saya seharusnya sudah menyadarinya!"
  },
  AvgVideoCaption_122705_Content_109 = {
    Text = "Kamu sama sekali bukan dewa, kan?"
  },
  AvgVideoCaption_122705_Content_11 = {
    Text = "Haruskah aku merasa gembira?"
  },
  AvgVideoCaption_122705_Content_110 = {
    Text = "Dewa yang sejati, bagaimana mungkin membiarkan para penganutnya terjatuh menjadi gila seperti itu?"
  },
  AvgVideoCaption_122705_Content_111 = {
    Text = "Dewa yang sejati, bagaimana mungkin bisa menjadi seonggok daging busuk yang kotor?"
  },
  AvgVideoCaption_122705_Content_112 = {
    Text = "Semua menipuku. Miryam, yang disebut dewa..."
  },
  AvgVideoCaption_122705_Content_113 = {
    Text = "Semua penipu, semuanya adalah kebohongan"
  },
  AvgVideoCaption_122705_Content_114 = {
    Text = "Hah, aku ternyata telah hidup dalam kebohongan selama ini"
  },
  AvgVideoCaption_122705_Content_115 = {
    Text = "Untuk daging busuk ini, aku sudah membayar begitu banyak harga..."
  },
  AvgVideoCaption_122705_Content_116 = {
    Text = "Takdir, nasib, semuanya hanyalah kehampaan..."
  },
  AvgVideoCaption_122705_Content_117 = {
    Text = "Monster ini... Kenapa kamu yang memutuskan masa depanku?"
  },
  AvgVideoCaption_122705_Content_118 = {
    Text = "Aku mengorbankan segalanya ini, bukan untukmu!"
  },
  AvgVideoCaption_122705_Content_119 = {
    Text = "Tentu saja tidak pernah!"
  },
  AvgVideoCaption_122705_Content_12 = {
    Text = "Haruskah aku bersorak untuk ini?"
  },
  AvgVideoCaption_122705_Content_120 = {
    Text = "Pergi mati, monster yang menjijikkan!"
  },
  AvgVideoCaption_122705_Content_121 = {
    Text = "Di mana ini?"
  },
  AvgVideoCaption_122705_Content_122 = {
    Text = "Aku kembali ke... hari kelahiran embrio suci?"
  },
  AvgVideoCaption_122705_Content_123 = {
    Text = "Anak baik, kamu telah melakukan pengorbanan yang mulia..."
  },
  AvgVideoCaption_122705_Content_124 = {
    Text = "Haha, haha, saya sudah kembali, saya sudah kembali!"
  },
  AvgVideoCaption_122705_Content_125 = {
    Text = "Aku tidak bisa melarikan diri, aku tidak bisa melarikan diri!"
  },
  AvgVideoCaption_122705_Content_126 = {
    Text = "Lintasan bintang telah terukir di atas kubah langit"
  },
  AvgVideoCaption_122705_Content_127 = {
    Text = "Setiap jalan bercabang menuju jurang yang sama..."
  },
  AvgVideoCaption_122705_Content_128 = {
    Text = "Apa yang disebut pilihan, hanyalah..."
  },
  AvgVideoCaption_122705_Content_129 = {
    Text = "Namun, itu hanyalah naskah yang telah ditulis oleh takdir"
  },
  AvgVideoCaption_122705_Content_13 = {
    Text = "Saya juga tidak yakin"
  },
  AvgVideoCaption_122705_Content_130 = {
    Text = "Hanya sebuah pertunjukan improvisasi yang penuh penipuan diri!"
  },
  AvgVideoCaption_122705_Content_131 = {
    Text = "Tuhan, jika kau bersikeras untuk tidak mengubah naskah yang konyol ini..."
  },
  AvgVideoCaption_122705_Content_132 = {
    Text = "Maka aku hanya bisa membiarkanmu menyaksikan sendiri"
  },
  AvgVideoCaption_122705_Content_133 = {
    Text = "Segala sesuatu yang kamu atur"
  },
  AvgVideoCaption_122705_Content_134 = {
    Text = "Bagaimana bisa menjadi tangga untuk menikmati kehormatan saya!"
  },
  AvgVideoCaption_122705_Content_14 = {
    Text = "Hari Kedua Kelahiran Dewa"
  },
  AvgVideoCaption_122705_Content_15 = {
    Text = "Doa Ibu Dewi untuk membaptis Janin Suci"
  },
  AvgVideoCaption_122705_Content_16 = {
    Text = "Semoga Tuhanku memaafkan ketidaksopanan dan kelalaiannya"
  },
  AvgVideoCaption_122705_Content_17 = {
    Text = "Kalian para pelayan yang kotor, mundurlah!"
  },
  AvgVideoCaption_122705_Content_18 = {
    Text = "Hanya saya yang berhak untuk melihat wujud-Nya yang sebenarnya"
  },
  AvgVideoCaption_122705_Content_19 = {
    Text = "Aku tidak berani membiarkan siapa pun melihat \"dewa\" yang aku lahirkan"
  },
  AvgVideoCaption_122705_Content_2 = {
    Text = "Hari pertama Kelahiran Dewa"
  },
  AvgVideoCaption_122705_Content_20 = {
    Text = "\"Janin\" yang dibaptis itu adalah seonggok daging dan darah yang kacau, kekurangan akal budi spiritual"
  },
  AvgVideoCaption_122705_Content_21 = {
    Text = "Pasti karena aku masih belum sepenuhnya..."
  },
  AvgVideoCaption_122705_Content_22 = {
    Text = "Tidak boleh membiarkan orang lain mengetahui hal ini"
  },
  AvgVideoCaption_122705_Content_23 = {
    Text = "Jika waktu berlalu, ketika Tuhan menjawab panggilanku, segalanya akan baik-baik saja"
  },
  AvgVideoCaption_122705_Content_24 = {
    Text = "Hari Ketiga Kelahiran Dewa"
  },
  AvgVideoCaption_122705_Content_25 = {
    Text = "Kandungan suci belum membuka mata"
  },
  AvgVideoCaption_122705_Content_26 = {
    Text = "Dewa, kapan kamu akan membuka matamu?"
  },
  AvgVideoCaption_122705_Content_27 = {
    Text = "Kamu tidak berjanji kepada Miryam"
  },
  AvgVideoCaption_122705_Content_28 = {
    Text = "Akan membawa Ranah dewa yang membangkitkannya?"
  },
  AvgVideoCaption_122705_Content_29 = {
    Text = "Hari Keempat Kelahiran Dewa"
  },
  AvgVideoCaption_122705_Content_3 = {
    Text = "Embrio dewa dilahirkan dari tubuh yang menjadi abu"
  },
  AvgVideoCaption_122705_Content_30 = {
    Text = "Upacara percakapan dengan dewa akan diadakan hari ini di gereja"
  },
  AvgVideoCaption_122705_Content_31 = {
    Text = "Tolong berikan kemuliaan ini kepada kami"
  },
  AvgVideoCaption_122705_Content_32 = {
    Text = "Menunjukkan koordinat tempat munculnya Kerajaan Ilahi bagi Pelaut"
  },
  AvgVideoCaption_122705_Content_33 = {
    Text = "Kami akan menyambut kebangkitan dan kedatangan Anda dengan hormat"
  },
  AvgVideoCaption_122705_Content_34 = {
    Text = "Saya menanyakan masa depan ranah dewa"
  },
  AvgVideoCaption_122705_Content_35 = {
    Text = "Tanyakan kepada-Nya tentang hubungan saya dengan-Nya"
  },
  AvgVideoCaption_122705_Content_36 = {
    Text = "Tanya saya segala sesuatu yang ingin saya ketahui"
  },
  AvgVideoCaption_122705_Content_37 = {
    Text = "Dan segala sesuatu yang dicoba ditanyakan oleh Miryam"
  },
  AvgVideoCaption_122705_Content_38 = {
    Text = "Dewa terdiam"
  },
  AvgVideoCaption_122705_Content_39 = {
    Text = "Hari Kelima Kelahiran Dewa"
  },
  AvgVideoCaption_122705_Content_4 = {
    Text = "Selaras akan tiba, Selaras telah tiba!"
  },
  AvgVideoCaption_122705_Content_40 = {
    Text = "Miryam bertanya tentang hasil pertemuanku dengan Tuhan"
  },
  AvgVideoCaption_122705_Content_41 = {Text = "Bagaimana?"},
  AvgVideoCaption_122705_Content_42 = {
    Text = "Sudah dua hari penuh……"
  },
  AvgVideoCaption_122705_Content_43 = {Text = "Tuhanku..."},
  AvgVideoCaption_122705_Content_44 = {
    Text = "Apakah kamu mendengar suaranya?"
  },
  AvgVideoCaption_122705_Content_45 = {
    Text = "Tentu, tentu saja saya mendengarnya!"
  },
  AvgVideoCaption_122705_Content_46 = {
    Text = "Keraguan seperti ini adalah penghinaan terhadap Ibu Dewa!"
  },
  AvgVideoCaption_122705_Content_47 = {
    Text = "Murphy, Murphy, Murphy yang baik"
  },
  AvgVideoCaption_122705_Content_48 = {
    Text = "Wahyu apa yang diberikan oleh Tuan-ku?"
  },
  AvgVideoCaption_122705_Content_49 = {
    Text = "Dia, Dia berkata, \"Ranah dewa segera akan muncul\""
  },
  AvgVideoCaption_122705_Content_5 = {
    Text = "Kelahiran Dewa"
  },
  AvgVideoCaption_122705_Content_50 = {
    Text = "Ternyata, ternyata!"
  },
  AvgVideoCaption_122705_Content_51 = {
    Text = "Tidak sia-sia aku menunggu ribuan saat bintang-bintang berada dalam posisi selaras"
  },
  AvgVideoCaption_122705_Content_52 = {
    Text = "Tuan-ku, Tuan akhirnya datang untuk menepati janjinya!"
  },
  AvgVideoCaption_122705_Content_53 = {
    Text = "Jadi, kapan tepatnya?"
  },
  AvgVideoCaption_122705_Content_54 = {
    Text = "Singkatnya, Ranah dewa pasti akan datang"
  },
  AvgVideoCaption_122705_Content_55 = {
    Text = "Pada saat apa, apakah itu begitu penting?"
  },
  AvgVideoCaption_122705_Content_56 = {
    Text = "Tidak, tidak, tidak, aku dan semua sukuku pasti akan mandi dengan dupa"
  },
  AvgVideoCaption_122705_Content_57 = {
    Text = "Menuju tempat munculnya Ranah Dewa dan menunggu kedatangan Tuhanku."
  },
  AvgVideoCaption_122705_Content_58 = {
    Text = "……\"Saat Bintang Selaras\""
  },
  AvgVideoCaption_122705_Content_59 = {
    Text = "Saat Bintang Berjajar?"
  },
  AvgVideoCaption_122705_Content_6 = {
    Text = "Anda mendengarku, Anda menanggapiku!"
  },
  AvgVideoCaption_122705_Content_60 = {
    Text = "Momen bintang Selaras yang mana?"
  },
  AvgVideoCaption_122705_Content_61 = {
    Text = "Berikutnya? Atau yang berikut-besarnya?"
  },
  AvgVideoCaption_122705_Content_62 = {
    Text = "Berisik sekali, sudah bilang itu adalah saat bintang-bintang berada dalam posisi selaras"
  },
  AvgVideoCaption_122705_Content_63 = {
    Text = "Saya tahu kapan saat bintang-bintang berada dalam posisi selaras?!"
  },
  AvgVideoCaption_122705_Content_64 = {
    Text = "Juga benar, juga benar"
  },
  AvgVideoCaption_122705_Content_65 = {
    Text = "Tuan baru saja terbangun dari mimpi panjang"
  },
  AvgVideoCaption_122705_Content_66 = {
    Text = "Kesadaran masih berada dalam kekacauan"
  },
  AvgVideoCaption_122705_Content_67 = {
    Text = "Pasti saat ini juga sangat kabur"
  },
  AvgVideoCaption_122705_Content_68 = {
    Text = "Selama Tuhanku akan datang pada akhirnya……"
  },
  AvgVideoCaption_122705_Content_69 = {
    Text = "Ini sama sekali tidak penting..."
  },
  AvgVideoCaption_122705_Content_7 = {
    Text = "Perintah Anda akan segera dilaksanakan di bumi"
  },
  AvgVideoCaption_122705_Content_70 = {
    Text = "Miryam sangat gembira"
  },
  AvgVideoCaption_122705_Content_71 = {
    Text = "Itu adalah ekspresi kegembiraan yang belum pernah saya lihat sebelumnya"
  },
  AvgVideoCaption_122705_Content_72 = {
    Text = "Aku tidak memberinya ukiran kayu"
  },
  AvgVideoCaption_122705_Content_73 = {
    Text = "Aku juga tidak ada ketika mengandung embrio suci"
  },
  AvgVideoCaption_122705_Content_74 = {
    Text = "Hari Keenam Kelahiran Dewa"
  },
  AvgVideoCaption_122705_Content_75 = {
    Text = "Aura terang di dalam hati saya tertutupi oleh lapisan kabut"
  },
  AvgVideoCaption_122705_Content_76 = {
    Text = "Bisakah kamu bertanya kepada Tuhanku, di mana ranah dewa akan tiba?"
  },
  AvgVideoCaption_122705_Content_77 = {
    Text = "Saya akan mengirimkan Pelaut untuk membangun altar penyambutan Ranah Dewa di dekat sini"
  },
  AvgVideoCaption_122705_Content_78 = {
    Text = "Dia bilang dia belum memikirkannya! Intinya, itu muncul dari bawah permukaan laut!"
  },
  AvgVideoCaption_122705_Content_79 = {
    Text = "Ini... Benarkah seperti itu?"
  },
  AvgVideoCaption_122705_Content_8 = {
    Text = "Lemuria akan abadi selamanya di bawah bimbingan Anda!"
  },
  AvgVideoCaption_122705_Content_80 = {
    Text = "Eh... itu, itu alami!"
  },
  AvgVideoCaption_122705_Content_81 = {
    Text = "Apa yang dikatakan Ibu Dewa, tidak mungkin bohong?"
  },
  AvgVideoCaption_122705_Content_82 = {
    Text = "Maaf, aku terlalu terburu-buru"
  },
  AvgVideoCaption_122705_Content_83 = {
    Text = "Aku tidak seharusnya mempertanyakan Ibu Dewa"
  },
  AvgVideoCaption_122705_Content_84 = {
    Text = "Lemuria, raja pada waktu itu"
  },
  AvgVideoCaption_122705_Content_85 = {
    Text = "Juga dengan sikap yang malas seperti ini..."
  },
  AvgVideoCaption_122705_Content_86 = {
    Text = "Silakan izinkan saya mencium punggung tangan Anda"
  },
  AvgVideoCaption_122705_Content_87 = {
    Text = "Saya meminta maaf atas ketidak sopanan saya"
  },
  AvgVideoCaption_122705_Content_88 = {
    Text = "...Akhirnya berhasil mengelak"
  },
  AvgVideoCaption_122705_Content_89 = {
    Text = "Tapi, besok harus bagaimana?"
  },
  AvgVideoCaption_122705_Content_9 = {
    Text = "Saya sangat lelah karena energi spiritual saya telah terkuras habis"
  },
  AvgVideoCaption_122705_Content_90 = {
    Text = "Mengapa Tuhan tidak merespons persembahan dan doa kami?"
  },
  AvgVideoCaption_122705_Content_91 = {
    Text = "Miriam sama sekali tidak percaya padaku"
  },
  AvgVideoCaption_122705_Content_92 = {
    Text = "Saya bisa melihat dari tatapan matanya"
  },
  AvgVideoCaption_122705_Content_93 = {
    Text = "Dia pernah melihat Dewa yang belum mati"
  },
  AvgVideoCaption_122705_Content_94 = {
    Text = "Kebohonganku belum tentu berhasil"
  },
  AvgVideoCaption_122705_Content_95 = {
    Text = "Tuhan, tolong selamatkan saya"
  },
  AvgVideoCaption_122705_Content_96 = {
    Text = "Sekalipun hanya satu kalimat, tolong kabulkan doaku"
  },
  AvgVideoCaption_122705_Content_97 = {
    Text = "Hari Ketujuh Kelahiran Dewa"
  },
  AvgVideoCaption_122705_Content_98 = {
    Text = "Tuhan sudah mati"
  },
  AvgVideoCaption_122705_Content_99 = {
    Text = "Dewa tidak pernah dilahirkan"
  },
  AvgVideoCaption_124223_Content_1 = {
    Text = "Apa yang pernah dikatakan oleh penyelidik"
  },
  AvgVideoCaption_124223_Content_10 = {
    Text = "Ah, omong-omong, di dalam bencana kabut, meskipun tiba-tiba kehilangan kemampuan untuk melihat \"artefak kuno\""
  },
  AvgVideoCaption_124223_Content_100 = {
    Text = "Sebuah kecelakaan? Kesalahan? Atau sesuatu yang lain?"
  },
  AvgVideoCaption_124223_Content_101 = {
    Text = "Katakanlah, beri tahu aku, mengapa aku ada di sini!"
  },
  AvgVideoCaption_124223_Content_102 = {
    Text = "Siapa yang membawaku ke sini dan untuk tujuan apa!"
  },
  AvgVideoCaption_124223_Content_103 = {
    Text = "Tidak mengatakan, kan? Tidak apa-apa, tidak apa-apa, kalian tidak punya mulut, aku mengerti"
  },
  AvgVideoCaption_124223_Content_104 = {
    Text = "Saya perlu mencari orang yang memiliki mulut"
  },
  AvgVideoCaption_124223_Content_105 = {
    Text = "Benar, itu adalah manusia, bukan monster yang terbuat dari kabut tebal"
  },
  AvgVideoCaption_124223_Content_106 = {
    Text = "Aku harus kembali, harus kembali"
  },
  AvgVideoCaption_124223_Content_107 = {
    Text = "Tempat sialan ini... Jika terus tinggal di sini, aku akan menjadi gila..."
  },
  AvgVideoCaption_124223_Content_108 = {
    Text = "Hari Kedua Puluh Delapan, aku menemukan manusia"
  },
  AvgVideoCaption_124223_Content_109 = {
    Text = "Akhirnya juga mengerti alasan di balik \"melintasi\"-ku"
  },
  AvgVideoCaption_124223_Content_11 = {
    Text = "Tetapi tetap akrab seperti pulang ke rumah"
  },
  AvgVideoCaption_124223_Content_110 = {
    Text = "Sekelompok penyembah sesat"
  },
  AvgVideoCaption_124223_Content_111 = {
    Text = "Pengikut sesat yang aku lihat saat aku \"melintasi\" datang, telah memanggilku"
  },
  AvgVideoCaption_124223_Content_112 = {
    Text = "Sekelompok orang gila ingin meninggalkan tempat ini, mencari apa yang sialan disebut \"dunia baru\""
  },
  AvgVideoCaption_124223_Content_113 = {
    Text = "Tapi malah mengirimku dari \"dunia baru\""
  },
  AvgVideoCaption_124223_Content_114 = {
    Text = "Ha, sungguh humor hitam"
  },
  AvgVideoCaption_124223_Content_115 = {
    Text = "Penyelidik, saya sebenarnya ingin membawa catatan penyelidikan ini kembali untuk kamu lihat"
  },
  AvgVideoCaption_124223_Content_116 = {
    Text = "Tapi sekarang tidak perlu lagi"
  },
  AvgVideoCaption_124223_Content_117 = {
    Text = "Saya memiliki rencana baru"
  },
  AvgVideoCaption_124223_Content_118 = {
    Text = "Mereka bukan suka menangkap orang hewan, kan?"
  },
  AvgVideoCaption_124223_Content_119 = {
    Text = "Di sini ada satu"
  },
  AvgVideoCaption_124223_Content_12 = {
    Text = "Jadi, aku sama sekali tidak menyadari bahwa aku telah \"melintasi\""
  },
  AvgVideoCaption_124223_Content_120 = {
    Text = "Biarkan aku berpikir bagaimana seharusnya aku tampil…"
  },
  AvgVideoCaption_124223_Content_121 = {
    Text = "Tolong Aku!"
  },
  AvgVideoCaption_124223_Content_122 = {
    Text = "Tidak, rasanya belum cukup, harus lebih menakutkan, lebih putus asa..."
  },
  AvgVideoCaption_124223_Content_123 = {Text = "Betul"},
  AvgVideoCaption_124223_Content_124 = {
    Text = "Seperti jeritan kesedihan para penyintas sebelum mereka mati"
  },
  AvgVideoCaption_124223_Content_125 = {
    Text = "Sekarang, \"Catatan Penyelidikan Dunia Lain Moxia\" telah berakhir"
  },
  AvgVideoCaption_124223_Content_126 = {
    Text = "Pertunjukan yang dimulai adalah \"Korban Tak Bersalah Menghancurkan Sarang Sekte Jahat\""
  },
  AvgVideoCaption_124223_Content_127 = {
    Text = "Petugas penyelidik, saya akan berusaha untuk pulang ke rumah"
  },
  AvgVideoCaption_124223_Content_128 = {
    Text = "Tapi jika rencananya gagal, jangan khawatir, karena bagaimanapun juga"
  },
  AvgVideoCaption_124223_Content_129 = {
    Text = "Hidupku akan memiliki akhir yang megah"
  },
  AvgVideoCaption_124223_Content_13 = {
    Text = "Aku hanya melihat beberapa orang berpakaian jubah hitam tiba-tiba muncul di depanku"
  },
  AvgVideoCaption_124223_Content_130 = {
    Text = "Jeritan para pengikut sesat itu akan menjadi tepuk tangan terbaik"
  },
  AvgVideoCaption_124223_Content_14 = {
    Text = "Mengejar manusia yang mereka sebut sebagai korban dengan belati perak"
  },
  AvgVideoCaption_124223_Content_15 = {
    Text = "Dan orang-orang itu, berteriak, meratap, membuat kepalaku hampir meledak"
  },
  AvgVideoCaption_124223_Content_16 = {
    Text = "Bising sekali, diamlah!"
  },
  AvgVideoCaption_124223_Content_17 = {
    Text = "Tidak ada yang menghiraukan saya sama sekali"
  },
  AvgVideoCaption_124223_Content_18 = {
    Text = "Jika tidak menghitung belati yang tertancap di bahuku"
  },
  AvgVideoCaption_124223_Content_19 = {
    Text = "Sepertinya kalian lebih suka menyapa dengan senjata?"
  },
  AvgVideoCaption_124223_Content_2 = {
    Text = "Menulis diary membantu merapikan memori dan menjaga kewarasan"
  },
  AvgVideoCaption_124223_Content_20 = {
    Text = "Kebetulan, saya juga"
  },
  AvgVideoCaption_124223_Content_21 = {
    Text = "Ayo sapa kapak cintaku—"
  },
  AvgVideoCaption_124223_Content_22 = {
    Text = "Berkilau☆Puting Beliung!"
  },
  AvgVideoCaption_124223_Content_23 = {
    Text = "Satu demi satu... Dalam kabut tebal yang tak ada yang tahu, aku meluapkan semuanya dengan bebas♪"
  },
  AvgVideoCaption_124223_Content_24 = {
    Text = "Pukul kepala kamu, masuki otakmu, mari kita habiskan waktu sambil mengejar♪"
  },
  AvgVideoCaption_124223_Content_25 = {
    Text = "Akhirnya, dunia ini telah bersih"
  },
  AvgVideoCaption_124223_Content_26 = {
    Text = "Aku menunggu penyelidik datang untuk membereskan kekacauan ini"
  },
  AvgVideoCaption_124223_Content_27 = {
    Text = "Saya juga tidak tahu berapa banyak kata yang harus ditulis dalam laporan evaluasi tentang \"bertindak impulsif\" kali ini"
  },
  AvgVideoCaption_124223_Content_28 = {
    Text = "Namun, pada hari kedua, hari ketiga, dan hari keempat, tidak ada yang datang mencariku"
  },
  AvgVideoCaption_124223_Content_29 = {
    Text = "Hanya monster misterius di dalam kabut tebal yang terus-menerus menggangguku"
  },
  AvgVideoCaption_124223_Content_3 = {
    Text = "Hah, rasionalitas?"
  },
  AvgVideoCaption_124223_Content_30 = {
    Text = "Sial, tidak bisakah orang-orang ini memberi saya waktu untuk makan?"
  },
  AvgVideoCaption_124223_Content_31 = {
    Text = "Saya juga ingin tidur, oke!"
  },
  AvgVideoCaption_124223_Content_32 = {
    Text = "Dan bencana kabut ini, berapa lama lagi kita bisa keluar!"
  },
  AvgVideoCaption_124223_Content_33 = {
    Text = "Petugas penyelidik, Moyasha kamu akan mati kelaparan, akan mati kehausan"
  },
  AvgVideoCaption_124223_Content_34 = {
    Text = "Akan mati kelelahan di bencana kabut yang hanya dipenuhi monster kabut ini"
  },
  AvgVideoCaption_124223_Content_35 = {
    Text = "Kamu sebenarnya di mana sih!"
  },
  AvgVideoCaption_124223_Content_36 = {
    Text = "Sangat lapar, sangat haus, sangat lelah…"
  },
  AvgVideoCaption_124223_Content_37 = {
    Text = "Kematian seperti ini terlalu sembarangan"
  },
  AvgVideoCaption_124223_Content_38 = {
    Text = "Aku masih berpikir bahwa hidupku akan memiliki akhir yang keren..."
  },
  AvgVideoCaption_124223_Content_39 = {
    Text = "Yang terpenting adalah"
  },
  AvgVideoCaption_124223_Content_4 = {
    Text = "Sejak tiba-tiba melintasi ke dunia ini, saya sudah tidak bisa menjaga akal sehat lagi"
  },
  AvgVideoCaption_124223_Content_40 = {
    Text = "Aku tidak ingin... sendirian..."
  },
  AvgVideoCaption_124223_Content_41 = {
    Text = "Hmm, sudah sampai hari ke berapa?"
  },
  AvgVideoCaption_124223_Content_42 = {
    Text = "Oh, Hari Kelima"
  },
  AvgVideoCaption_124223_Content_43 = {
    Text = "Aku Moyasha, masih hidup di dunia membosankan ini"
  },
  AvgVideoCaption_124223_Content_44 = {
    Text = "\"Para penyintas lokal\" di dalam bencana kabut menyelamatkan saya"
  },
  AvgVideoCaption_124223_Content_45 = {
    Text = "Setelah perbincangan yang penuh kebingungan"
  },
  AvgVideoCaption_124223_Content_46 = {
    Text = "Akhirnya saya mengerti bahwa saya telah \"melintasi\""
  },
  AvgVideoCaption_124223_Content_47 = {
    Text = "Sejak itu tidak ada teh hazelnut yang panas, tidak ada ikan rebus Rivenrog yang harum"
  },
  AvgVideoCaption_124223_Content_48 = {
    Text = "Hanya ada roti hitam yang keras dan air keruh yang dicampur pasir"
  },
  AvgVideoCaption_124223_Content_49 = {
    Text = "Tapi aku juga tidak bisa mengeluh tentang apa pun"
  },
  AvgVideoCaption_124223_Content_5 = {
    Text = "Namun, karena tidak bisa kembali untuk sementara waktu, harus mencari hiburan untuk mengisi waktu..."
  },
  AvgVideoCaption_124223_Content_50 = {
    Text = "Lagipula, kota ini telah terputus dari dunia luar"
  },
  AvgVideoCaption_124223_Content_51 = {
    Text = "Bencana kabut kembali menjerat semua orang, setiap orang terlihat kurus kering karena kelaparan"
  },
  AvgVideoCaption_124223_Content_52 = {
    Text = "Roh juga perlahan-lahan runtuh dalam penyiksaan yang berulang hari demi hari"
  },
  AvgVideoCaption_124223_Content_53 = {
    Text = "Saya rasa hidup sekarang ini cukup menarik kecuali untuk \"kehilangan kebebasan\" itu"
  },
  AvgVideoCaption_124223_Content_54 = {
    Text = "Saat merasa bosan, saya keluar untuk membunuh monster"
  },
  AvgVideoCaption_124223_Content_55 = {
    Text = "Bisa juga membawa pulang persediaan baru, satu batu dua burung"
  },
  AvgVideoCaption_124223_Content_56 = {
    Text = "Bisa dibilang, tempat ini seperti taman bermain"
  },
  AvgVideoCaption_124223_Content_57 = {
    Text = "Ada barang antik yang bisa mengurangi stres, ada dongeng tidur dari dunia lain yang bisa didengarkan"
  },
  AvgVideoCaption_124223_Content_58 = {
    Text = "Ada bisikan saat semua orang hampir hancur, lagu pengantar tidur"
  },
  AvgVideoCaption_124223_Content_59 = {
    Text = "Kadang-kadang aku bisa melihat orang lain bertarung sampai berdarah dan terluka, sungguh mengasyikkan"
  },
  AvgVideoCaption_124223_Content_6 = {
    Text = "Tidak disangka aku juga akan menulis hal-hal membosankan seperti ini…"
  },
  AvgVideoCaption_124223_Content_60 = {
    Text = "Saya tidak tahu siapa yang minum lebih banyak air, siapa yang makan lebih banyak roti hingga ada yang perlu berkelahi"
  },
  AvgVideoCaption_124223_Content_61 = {
    Text = "Mungkin semua ini sudah tidak penting lagi"
  },
  AvgVideoCaption_124223_Content_62 = {
    Text = "Mereka hanya ingin alasan untuk melepaskan kepanikan di dalam hati mereka"
  },
  AvgVideoCaption_124223_Content_63 = {
    Text = "Sungguh kasihan dan menyedihkan"
  },
  AvgVideoCaption_124223_Content_64 = {
    Text = "Ini adalah pertama kalinya aku menulis buku harian setelah \"kejadian itu\" terjadi"
  },
  AvgVideoCaption_124223_Content_65 = {
    Text = "Alex sudah mati, di depanku——"
  },
  AvgVideoCaption_124223_Content_66 = {
    Text = "Dia tergerus oleh bencana kabut, seperti tetesan air yang mencair di lautan, sepenuhnya menghilang dalam kabut tebal"
  },
  AvgVideoCaption_124223_Content_67 = {
    Text = "Ini adalah insiden kedua bencana kabut yang harus diwaspadai dengan serius"
  },
  AvgVideoCaption_124223_Content_68 = {
    Text = "Saya harus mengumpulkan lebih banyak inventaris dan membawa sisa penyintas keluar dari jangkauan bencana kabut"
  },
  AvgVideoCaption_124223_Content_69 = {
    Text = "Hari kesebelas, saya menemukan beberapa daging rusa yang dijemur, kentang yang mulai berkecambah, dan bacon"
  },
  AvgVideoCaption_124223_Content_7 = {
    Text = "Baiklah, anggap saja ini sebagai laporan penyelidikan yang ditulis sebelumnya"
  },
  AvgVideoCaption_124223_Content_70 = {
    Text = "Bacon enak, tetapi tidak sebanding dengan ikan rebus Rivenrog"
  },
  AvgVideoCaption_124223_Content_71 = {
    Text = "Jika ada segelas teh hazelnut yang panas lagi, pasti lebih baik, sayang sekali"
  },
  AvgVideoCaption_124223_Content_72 = {
    Text = "Hari Ketiga Belas"
  },
  AvgVideoCaption_124223_Content_73 = {
    Text = "Aku menemukan beberapa roti, daging rusa yang dikeringkan, tetapi tidak ada air"
  },
  AvgVideoCaption_124223_Content_74 = {
    Text = "Semua air sumur terkontaminasi oleh kabut tebal"
  },
  AvgVideoCaption_124223_Content_75 = {
    Text = "Setelah itu"
  },
  AvgVideoCaption_124223_Content_76 = {
    Text = "Anna sudah meninggal"
  },
  AvgVideoCaption_124223_Content_77 = {
    Text = "Dihancurkan oleh bencana kabut, menghilang di depan semua orang"
  },
  AvgVideoCaption_124223_Content_78 = {
    Text = "Hari keenam belas, masih daging rusa yang dikeringkan, ditambah dengan satu kantong kecil bubur oatmeal"
  },
  AvgVideoCaption_124223_Content_79 = {
    Text = "Betsy kecil dan Susan kecil menghilang"
  },
  AvgVideoCaption_124223_Content_8 = {
    Text = "Maka, \"Catatan Penyelidikan Dunia Lain Moyasha\" secara resmi didaftarkan——"
  },
  AvgVideoCaption_124223_Content_80 = {
    Text = "Mulai sekarang, tidak ada cerita sebelum tidur"
  },
  AvgVideoCaption_124223_Content_81 = {
    Text = "Anak-anak yang perlu mendengarkan ini sudah tidak ada"
  },
  AvgVideoCaption_124223_Content_82 = {
    Text = "Hari ketujuh belas, tidak mendapatkan apa-apa"
  },
  AvgVideoCaption_124223_Content_83 = {
    Text = "Keterpurukan Mental Charles"
  },
  AvgVideoCaption_124223_Content_84 = {Text = "Bunuh diri"},
  AvgVideoCaption_124223_Content_85 = {
    Text = "Hari kedelapan belas, tidak memperoleh apa pun"
  },
  AvgVideoCaption_124223_Content_86 = {
    Text = "Hari kedua puluh satu, daging rusa yang dikeringkan, kentang yang bertunas……"
  },
  AvgVideoCaption_124223_Content_87 = {
    Text = "Apa sebenarnya yang saya lakukan? Moyasha, apakah kamu sudah melupakan tujuanmu? Tujuanmu adalah pulang ke rumah"
  },
  AvgVideoCaption_124223_Content_88 = {
    Text = "Bukan menjadi preman di sini, mengumpulkan daging rusa kering dan kentang yang mulai bertunas"
  },
  AvgVideoCaption_124223_Content_89 = {
    Text = "Biarlah*Suara mati*daging rusa kering dan kentang yang bertunas pergi ke neraka!"
  },
  AvgVideoCaption_124223_Content_9 = {
    Text = "Biarkan aku berpikir tentang hari pertama \"Melintasi\"..."
  },
  AvgVideoCaption_124223_Content_90 = {
    Text = "Tidak, tenang sebentar, tenang"
  },
  AvgVideoCaption_124223_Content_91 = {
    Text = "Masih ada tiga penyintas"
  },
  AvgVideoCaption_124223_Content_92 = {
    Text = "Bawa mereka keluar dari area bencana kabut, baru pikirkan tentang pulang"
  },
  AvgVideoCaption_124223_Content_93 = {
    Text = "Begitulah, jangan bertindak aneh, jangan gila sebelum bencana kabut"
  },
  AvgVideoCaption_124223_Content_94 = {
    Text = "Aah aah aah aah——kau keluarkan itu, keluarkan mereka!"
  },
  AvgVideoCaption_124223_Content_95 = {
    Text = "Kamu pikir aku tidak bisa membunuhmu, tidak, aku tidak takut pada apa pun, apa pun bisa dikalahkan"
  },
  AvgVideoCaption_124223_Content_96 = {
    Text = "Jadi kembalikan mereka, aku memerintahkanmu untuk mengembalikan mereka!"
  },
  AvgVideoCaption_124223_Content_97 = {
    Text = "Tidak bisa diselamatkan... Mengapa tidak ada satu pun yang bisa diselamatkan..."
  },
  AvgVideoCaption_124223_Content_98 = {
    Text = "Semua yang saya lakukan sama sekali tidak ada artinya!"
  },
  AvgVideoCaption_124223_Content_99 = {
    Text = "Jadi, mengapa saya muncul di sini?"
  },
  AvgVideoCaption_126905_Content_1 = {
    Text = "Mengapa kamu gemetar?"
  },
  AvgVideoCaption_126905_Content_10 = {
    Text = "Apa yang kamu sukai, itulah yang nyata"
  },
  AvgVideoCaption_126905_Content_100 = {
    Text = "Saya Ibu, atau Tuan Xu?"
  },
  AvgVideoCaption_126905_Content_101 = {
    Text = "Nak, kamu mengerti cerita itu"
  },
  AvgVideoCaption_126905_Content_102 = {
    Text = "Kita masih punya satu hal terakhir yang harus dilakukan"
  },
  AvgVideoCaption_126905_Content_103 = {
    Text = "Ayah ingin menghentikan kita bersama"
  },
  AvgVideoCaption_126905_Content_104 = {
    Text = "Sama seperti dia membawaku pergi dari sisimu pada waktu itu"
  },
  AvgVideoCaption_126905_Content_105 = {
    Text = "Dia memotongku menjadi kecil, mengorbankanku, untuk mendapatkan benda itu"
  },
  AvgVideoCaption_126905_Content_106 = {
    Text = "Mengubah rusa menjadi kuda, benda palsu menjadi yang nyata"
  },
  AvgVideoCaption_126905_Content_107 = {
    Text = "Tapi kami hanya akan memberikan barang ini kepadamu"
  },
  AvgVideoCaption_126905_Content_108 = {
    Text = "Buang dari mana"
  },
  AvgVideoCaption_126905_Content_109 = {
    Text = "Buang mimpi-mimpi itu"
  },
  AvgVideoCaption_126905_Content_11 = {
    Text = "Kamu tidak suka sesuatu, maka sesuatu itu bisa dianggap tidak nyata"
  },
  AvgVideoCaption_126905_Content_110 = {
    Text = [[
Sempurna, sempurna, datanglah ke sisiku
Sempurna, sempurna, datanglah ke Ibu]]
  },
  AvgVideoCaption_126905_Content_111 = {
    Text = "Kemudian, hamba akan memastikan hadiah manis ini, selamanya milikmu"
  },
  AvgVideoCaption_126905_Content_112 = {
    Text = "Kami akan selamanya"
  },
  AvgVideoCaption_126905_Content_113 = {Text = "Bersamamu"},
  AvgVideoCaption_126905_Content_12 = {Text = "Kenapa?"},
  AvgVideoCaption_126905_Content_13 = {
    Text = "Kamu terlihat hampir tertidur, bunga melati kecil"
  },
  AvgVideoCaption_126905_Content_14 = {
    Text = "Apa yang akan dilakukan ibu manusia pada saat ini..."
  },
  AvgVideoCaption_126905_Content_15 = {
    Text = "Aku akan menceritakan sebuah dongeng tidur untukmu"
  },
  AvgVideoCaption_126905_Content_16 = {
    Text = "Sudah lama sekali"
  },
  AvgVideoCaption_126905_Content_17 = {
    Text = "Di negeri yang paling makmur di Timur"
  },
  AvgVideoCaption_126905_Content_18 = {
    Text = "Ada seorang raja kecil, duduk di atas takhtanya"
  },
  AvgVideoCaption_126905_Content_19 = {
    Text = "Di bawah Takhtanya"
  },
  AvgVideoCaption_126905_Content_2 = {
    Text = "Sungguh kasihan"
  },
  AvgVideoCaption_126905_Content_20 = {
    Text = "Ada satu orang pejabat yang berada di bawah satu orang, di atas sepuluh ribu orang"
  },
  AvgVideoCaption_126905_Content_21 = {
    Text = "Mengincar kekuasaannya"
  },
  AvgVideoCaption_126905_Content_22 = {
    Text = "Di negara ini, setiap orang mengetahui hal ini"
  },
  AvgVideoCaption_126905_Content_23 = {
    Text = "Tapi semua orang sedang menunggu, mereka belum memutuskan apakah akan berdiri di samping raja atau di samping pejabat tinggi"
  },
  AvgVideoCaption_126905_Content_24 = {
    Text = "Lagi satu kenapa?"
  },
  AvgVideoCaption_126905_Content_25 = {
    Text = "Ah... manusia kecil yang merepotkan"
  },
  AvgVideoCaption_126905_Content_26 = {
    Text = "Karena mereka ingin mencari tahu, di mana tempat yang lebih banyak orang"
  },
  AvgVideoCaption_126905_Content_27 = {
    Text = "Kekuasaan adalah sesuatu yang membuat yang kuat semakin kuat, dan yang lemah semakin lemah"
  },
  AvgVideoCaption_126905_Content_28 = {
    Text = "Kepala mulai terasa sakit lagi"
  },
  AvgVideoCaption_126905_Content_29 = {
    Text = "Segera... segera penyakitmu akan sembuh"
  },
  AvgVideoCaption_126905_Content_3 = {
    Text = "Apakah ini akan lebih baik, bunga melati kecil?"
  },
  AvgVideoCaption_126905_Content_30 = {
    Text = "Ayo, hamba tahu bagaimana caranya membuat sayangku yang baik menjadi lebih baik"
  },
  AvgVideoCaption_126905_Content_31 = {
    Text = "Kamu hanya perlu relaks……"
  },
  AvgVideoCaption_126905_Content_32 = {
    Text = "Ya, seperti ini"
  },
  AvgVideoCaption_126905_Content_33 = {
    Text = "Selanjutnya……"
  },
  AvgVideoCaption_126905_Content_34 = {
    Text = "Kita tadi berbicara sampai di mana."
  },
  AvgVideoCaption_126905_Content_35 = {
    Text = "Semua orang akan segera menunggu saat untuk membuat pilihan"
  },
  AvgVideoCaption_126905_Content_36 = {Text = "Hari ini"},
  AvgVideoCaption_126905_Content_37 = {
    Text = "Pedagang asing membawa barang-barang segar"
  },
  AvgVideoCaption_126905_Content_38 = {
    Text = "Ia memiliki empat kuku yang lincah"
  },
  AvgVideoCaption_126905_Content_39 = {
    Text = "Pada saat yang sama, ada sepasang tanduk panjang dan bulu indah yang dipenuhi dengan bintik-bintik"
  },
  AvgVideoCaption_126905_Content_4 = {
    Text = "Mendekatlah"
  },
  AvgVideoCaption_126905_Content_40 = {
    Text = "Penguasa yang berpengaruh berkata"
  },
  AvgVideoCaption_126905_Content_41 = {
    Text = "\"Yang Mulia, saya telah membawa seekor kuda yang bisa menempuh seribu mil untuk Anda.\""
  },
  AvgVideoCaption_126905_Content_42 = {
    Text = "Hmm, tentu saja bukan kuda"
  },
  AvgVideoCaption_126905_Content_43 = {
    Text = "Raja juga berkata demikian"
  },
  AvgVideoCaption_126905_Content_44 = {
    Text = "\"Cinta, kamu bercanda, ini jelas adalah seekor rusa.\""
  },
  AvgVideoCaption_126905_Content_45 = {
    Text = "Orang-orang di bawah juga ramai membicarakan"
  },
  AvgVideoCaption_126905_Content_46 = {
    Text = "Tetapi pejabat tinggi hanya menatap raja dengan tenang dan berkata"
  },
  AvgVideoCaption_126905_Content_47 = {
    Text = "\"Yang Mulia, ini adalah kuda.\""
  },
  AvgVideoCaption_126905_Content_48 = {
    Text = "Mereka yang berdiri di pihak para pejabat berkuasa juga ikut bersuara"
  },
  AvgVideoCaption_126905_Content_49 = {
    Text = "\"Betul, ini adalah kuda.\""
  },
  AvgVideoCaption_126905_Content_5 = {
    Text = "Hamba akan menangkap sebuah awan, agar kamu bisa bersandar di dalamnya……"
  },
  AvgVideoCaption_126905_Content_50 = {
    Text = "\"Mǎ Míngmíng dan ini persis sama.\""
  },
  AvgVideoCaption_126905_Content_51 = {
    Text = "\"Betapa hebatnya seekor kuda yang luar biasa, selamat Yang Mulia, mendapatkan kuda yang baik ini.\""
  },
  AvgVideoCaption_126905_Content_52 = {
    Text = "Mungkin karena ketakutan terhadap kekuasaan para pejabat, atau mungkin karena suara dukungan terlalu merajalela"
  },
  AvgVideoCaption_126905_Content_53 = {
    Text = "Hanya beberapa orang yang mengatakan bahwa itu adalah suara rusa, dan suara itu segera tenggelam dalam gelombang suara"
  },
  AvgVideoCaption_126905_Content_54 = {
    Text = "Di tengah gelombang suara, di depan semua orang, rusa mulai berubah"
  },
  AvgVideoCaption_126905_Content_55 = {
    Text = "Bunga plum mengelupas sedikit demi sedikit dari tubuhnya, sudutnya lembut, layu, kemudian rontok"
  },
  AvgVideoCaption_126905_Content_56 = {
    Text = "Tulangnya mengeluarkan suara berderak saat meregang"
  },
  AvgVideoCaption_126905_Content_57 = {
    Text = "Plasma darah yang merembes dari tubuh yang terkoyak menempel di sela-sela jari kaki, membentuk kuda kakinya"
  },
  AvgVideoCaption_126905_Content_58 = {
    Text = "Monster yang berlumuran darah ini berdiri di atas altar"
  },
  AvgVideoCaption_126905_Content_59 = {
    Text = "Mengeluarkan suara mendesis yang konyol dan tidak pada tempatnya"
  },
  AvgVideoCaption_126905_Content_6 = {
    Text = "Ya, di Tidak Mimpi Kampung, ini bukanlah hal yang aneh"
  },
  AvgVideoCaption_126905_Content_60 = {
    Text = "Menteri yang berkuasa dengan tenang mengelusnya"
  },
  AvgVideoCaption_126905_Content_61 = {
    Text = "Raja terdiam di tempat karena ketakutan"
  },
  AvgVideoCaption_126905_Content_62 = {
    Text = "Orang-orang menyadari di pihak mana mereka seharusnya berdiri"
  },
  AvgVideoCaption_126905_Content_63 = {Text = "Sejak itu"},
  AvgVideoCaption_126905_Content_64 = {
    Text = "Bayangan aneh yang diubah dari rusa menjadi kuda terus mengikuti raja"
  },
  AvgVideoCaption_126905_Content_65 = {
    Text = "Tidak ada yang peduli lagi dengan kewibawaannya"
  },
  AvgVideoCaption_126905_Content_66 = {
    Text = "Tidak ada yang peduli dengan pemikirannya lagi"
  },
  AvgVideoCaption_126905_Content_67 = {
    Text = "Tidak ada yang menghiraukan teriakan yang keluar dari tenggorokannya saat disiksa oleh monster"
  },
  AvgVideoCaption_126905_Content_68 = {
    Text = "Karena baik berasal dari keinginan, ketakutan, pertimbangan, atau apa pun yang lain"
  },
  AvgVideoCaption_126905_Content_69 = {
    Text = "Orang-orang berdiri di sisi pejabat berkuasa"
  },
  AvgVideoCaption_126905_Content_7 = {
    Text = "Ia memiliki aroma, lembut, dan dingin"
  },
  AvgVideoCaption_126905_Content_70 = {
    Text = "Dia bilang itu kuda, itu adalah kuda, rusa juga kuda"
  },
  AvgVideoCaption_126905_Content_71 = {
    Text = "Jadi, raja tetaplah raja"
  },
  AvgVideoCaption_126905_Content_72 = {
    Text = "Hanya karena dia tidak berbicara, mengatakan bahwa raja bukanlah raja"
  },
  AvgVideoCaption_126905_Content_73 = {
    Text = "Bunga Melati Kecil, apa yang kamu rasakan dalam cerita itu?"
  },
  AvgVideoCaption_126905_Content_74 = {
    Text = "Hoho... Hahahahaha!"
  },
  AvgVideoCaption_126905_Content_75 = {Text = "Sayangku"},
  AvgVideoCaption_126905_Content_76 = {
    Text = "Sayangku yang paling aku cintai"
  },
  AvgVideoCaption_126905_Content_77 = {
    Text = "Iya, itu manis"
  },
  AvgVideoCaption_126905_Content_78 = {
    Text = "Asalkan orang terbanyak berdiri di sisimu"
  },
  AvgVideoCaption_126905_Content_79 = {
    Text = "Asalkan kekuasaan ada di tangan sendiri"
  },
  AvgVideoCaption_126905_Content_8 = {
    Text = "Benar, sayangku, Dia tentu saja adalah awan"
  },
  AvgVideoCaption_126905_Content_80 = {
    Text = "Nyata, kepalsuan, benar, atau salah, semua hanya bergantung pada pikiranmu"
  },
  AvgVideoCaption_126905_Content_81 = {
    Text = "Kehendak raja dan orang-orang bodoh, menghadapi ketakutan"
  },
  AvgVideoCaption_126905_Content_82 = {
    Text = "Tidak penting"
  },
  AvgVideoCaption_126905_Content_83 = {
    Text = "Hai Cheng akan menjadi mainanmu"
  },
  AvgVideoCaption_126905_Content_84 = {
    Text = "Dunia... juga akan menjadi mainanmu"
  },
  AvgVideoCaption_126905_Content_85 = {
    Text = "Kamu sudah terlalu lelah"
  },
  AvgVideoCaption_126905_Content_86 = {
    Text = "Kamu ingin menangkap sesuatu yang pasti, apa salahnya?"
  },
  AvgVideoCaption_126905_Content_87 = {
    Text = "Kekuasaan adalah aman, kekuasaan adalah manis, bunga melati kecil"
  },
  AvgVideoCaption_126905_Content_88 = {
    Text = "Kamu percaya Dia adalah awan, Dia adalah awan"
  },
  AvgVideoCaption_126905_Content_89 = {
    Text = "Siapa yang kamu harapkan ada di sisimu, dia akan selamanya, selamanya, ada di sisimu"
  },
  AvgVideoCaption_126905_Content_9 = {Text = "Ssst——"},
  AvgVideoCaption_126905_Content_90 = {Text = "Hm?"},
  AvgVideoCaption_126905_Content_91 = {
    Text = "Aduh... Apakah ini terlalu rumit?"
