  AvgVideoCaption_126905_Content_94 = {
    Text = "Hanya untuk tidak kesepian"
  },
  AvgVideoCaption_126905_Content_95 = {
    Text = "Aku bersedia melakukan apa pun"
  },
  AvgVideoCaption_126905_Content_96 = {
    Text = "Kemarilah, datanglah ke pelukanku"
  },
  AvgVideoCaption_126905_Content_97 = {
    Text = "Orang yang tidak bermimpi di kampung tidak perlu bermimpi"
  },
  AvgVideoCaption_126905_Content_98 = {
    Text = "Kamu akan mendapatkan segala sesuatu yang nyata"
  },
  AvgVideoCaption_126905_Content_99 = {
    Text = "Apa yang kamu percayai, bunga melati kecil?"
