    Text = "O-1841 Awakener"
  },
  AvgVideoCaption_131662_Content_119 = {
    Text = "Bisakah kamu mendengar suaraku?"
  },
  AvgVideoCaption_131662_Content_12 = {
    Text = "Perguruan tinggi Mythag Awaken mulai mencoba untuk berinteraksi dengan mereka"
  },
  AvgVideoCaption_131662_Content_120 = {
    Text = "Meskipun tidak dapat merasakan"
  },
  AvgVideoCaption_131662_Content_121 = {
    Text = "Namun, setelah penelitian deteksi alat @4, ditemukan bahwa kekuatanmu akan mendistorsi semua hal di sekitar tanpa disadari"
  },
  AvgVideoCaption_131662_Content_122 = {
    Text = "Terima kasih telah mencoba mengingatkan kami"
