  },
  AvgVideoCaption_131662_Content_143 = {Text = "Tetapi"},
  AvgVideoCaption_131662_Content_144 = {
    Text = "Dengan kata-kata seperti itu, kamu akan menanggung penderitaan yang tidak manusiawi..."
