  AvgVideoCaption_131662_Content_15 = {
    Text = "Saya tidak akan menyakitimu"
  },
  AvgVideoCaption_131662_Content_16 = {
    Text = "Kamu bisa mengerti apa yang saya katakan, kan?"
  },
  AvgVideoCaption_131662_Content_17 = {
    Text = "Kamu tenang, di sini sangat aman"
  },
  AvgVideoCaption_131662_Content_18 = {
    Text = "Kami berasal dari Perguruan tinggi Mythag, saya adalah peneliti sistem Awakener, Erin Caldwell"
  },
  AvgVideoCaption_131662_Content_19 = {
    Text = "Apa yang kamu alami di dalam pusaran itu?"
