  AvgVideoCaption_131662_Content_2 = {
    Text = "Suara, suara, sangat sunyi…"
  },
  AvgVideoCaption_131662_Content_20 = {
    Text = "Kami sangat membutuhkan informasi kamu untuk memulihkan situasi kasus"
  },
  AvgVideoCaption_131662_Content_21 = {
    Text = "Selanjutnya, silakan bicaralah ke mikrofon penguat Perak ini"
  },
  AvgVideoCaption_131662_Content_22 = {
