  AvgVideoCaption_131662_Content_27 = {
    Text = "Fouetté…"
  },
  AvgVideoCaption_131662_Content_28 = {
    Text = "Jatuh, tidak akan pernah jatuh, tidak ada atas, tidak ada bawah, kiri kanan... tidak ada lagi"
