  AvgVideoCaption_131662_Content_31 = {
    Text = "Bagus sekali…"
  },
  AvgVideoCaption_131662_Content_32 = {
    Text = "Tapi, tapi... di telinga, suara itu masih ada..."
  },
  AvgVideoCaption_131662_Content_33 = {Text = "Kenapa?"},
  AvgVideoCaption_131662_Content_34 = {
