  },
  AvgVideoCaption_131662_Content_35 = {
    Text = "Tapi, di telinga Mosk, ada suara, suara yang sangat besar"
  },
  AvgVideoCaption_131662_Content_36 = {
    Text = "Mosk... Mosk berharap... bukan suara di dalam kepala Mosk..."
  },
  AvgVideoCaption_131662_Content_37 = {
    Text = "Aneh sekali, tapi, kenapa? Bola arang kecil, kamu tahu tidak?"
  },
  AvgVideoCaption_131662_Content_38 = {
    Text = "Ah…… ah…… Benar"
  },
  AvgVideoCaption_131662_Content_39 = {
    Text = "Aku sudah..."
  },
  AvgVideoCaption_131662_Content_4 = {
    Text = "Di mana ini, di mana saya, suara… suhu… berikan saya…"
  },
  AvgVideoCaption_131662_Content_40 = {
    Text = "Tidak ada di sana lagi"
  },
  AvgVideoCaption_131662_Content_41 = {
    Text = "Tidak, Bola arang kecil sudah tidak ada"
  },
  AvgVideoCaption_131662_Content_42 = {
    Text = "Air, air, namun air..."
  },
  AvgVideoCaption_131662_Content_43 = {
    Text = "Telinga, air, telinga…"
  },
  AvgVideoCaption_131662_Content_44 = {
    Text = "Saya ada di Mi, Mythag"
  },
  AvgVideoCaption_131662_Content_45 = {
    Text = "Tapi matahari, matahari, menyilaukan……"
  },
  AvgVideoCaption_131662_Content_46 = {
    Text = "Matahari kembali, semakin terang"
  },
  AvgVideoCaption_131662_Content_47 = {
    Text = "Ayah dan Ibu berkata, matahari terang, bayangan, arah"
  },
  AvgVideoCaption_131662_Content_48 = {
    Text = "Fouetté, Fouetté, bayangan, Fouetté"
  },
  AvgVideoCaption_131662_Content_49 = {
    Text = "Tidak, tidak! Tidak!! Bayangan tidak bergerak!!"
  },
  AvgVideoCaption_131662_Content_5 = {
    Text = "Bola arang kecil……Nautila……"
  },
  AvgVideoCaption_131662_Content_50 = {
    Text = "Di atas! Di bawah! Semuanya berputar! Semuanya berputar!!!"
  },
  AvgVideoCaption_131662_Content_51 = {
    Text = "Tidak! Tidak!! Kenapa! Kenapa!!"
  },
  AvgVideoCaption_131662_Content_52 = {
    Text = "Aku sudah melarikan diri! Aku sudah melarikan diri"
  },
  AvgVideoCaption_131662_Content_53 = {
    Text = "Saya... melarikan diri..."
  },
  AvgVideoCaption_131662_Content_54 = {Text = "Mythag…"},
  AvgVideoCaption_131662_Content_55 = {Text = "Kamar…"},
  AvgVideoCaption_131662_Content_56 = {
    Text = "Matahari terang…"
  },
  AvgVideoCaption_131662_Content_57 = {
    Text = "Tiga Belas kali……"
  },
  AvgVideoCaption_131662_Content_58 = {
    Text = "Tidak, tidak, di dalam kamar, tidak ada jendela"
  },
  AvgVideoCaption_131662_Content_59 = {
    Text = "Bola api besar……"
  },
  AvgVideoCaption_131662_Content_6 = {
    Text = "O-1841 Awakener"
  },
  AvgVideoCaption_131662_Content_60 = {
    Text = "Tidak akan menyala! Tidak akan menyala"
  },
  AvgVideoCaption_131662_Content_61 = {
    Text = "Aaaaaaaaaah——————————"
  },
  AvgVideoCaption_131662_Content_62 = {
    Text = "Pusaran! Pusaran! Air! Air"
  },
  AvgVideoCaption_131662_Content_63 = {
    Text = "Di dalam tubuh! Air! Dia! Air"
  },
  AvgVideoCaption_131662_Content_64 = {
    Text = "Masih ada! Masih ada! Mosk tahu"
  },
  AvgVideoCaption_131662_Content_65 = {
    Text = "Mosk tahu Dia masih ada"
  },
  AvgVideoCaption_131662_Content_66 = {
    Text = "Tolong aku, tolong Mosk..."
  },
  AvgVideoCaption_131662_Content_67 = {
    Text = "Tidak, Mosk sudah tidak bisa diselamatkan…"
  },
  AvgVideoCaption_131662_Content_68 = {
    Text = "Aku... tidak ada harapan lagi..."
  },
  AvgVideoCaption_131662_Content_69 = {Text = "Ah"},
  AvgVideoCaption_131662_Content_7 = {
    Text = "Inti Peraknya ditemukan di D-rongga di bawah Vortex M-Merskes"
  },
  AvgVideoCaption_131662_Content_70 = {
    Text = "Ah, aaaahhh!!!!!!!"
  },
  AvgVideoCaption_131662_Content_71 = {
    Text = "Hah, hah..."
  },
  AvgVideoCaption_131662_Content_72 = {
    Text = "Keluar, lari..."
  },
  AvgVideoCaption_131662_Content_73 = {
    Text = "Lepaskan kembali... buang aku... buang..."
  },
  AvgVideoCaption_131662_Content_74 = {
    Text = "Mosk… tidak ingin menyakiti orang…"
  },
  AvgVideoCaption_131662_Content_75 = {
    Text = "Mosk takut… sendirian…"
  },
  AvgVideoCaption_131662_Content_76 = {
    Text = "Namun... semua orang mati..."
  },
  AvgVideoCaption_131662_Content_77 = {
    Text = "Tawa, makan, akan berikan aku…"
  },
  AvgVideoCaption_131662_Content_78 = {
    Text = "Tidak bisa diambil"
  },
  AvgVideoCaption_131662_Content_79 = {
    Text = "Keluar, harus pergi! Kalau tidak"
  },
  AvgVideoCaption_131662_Content_8 = {
    Text = "Pada tahap awal Bangun, sebagian besar Pembangun O-1841 kehilangan kesadaran sepenuhnya dan menunjukkan kecenderungan untuk menghancurkan yang kuat"
  },
  AvgVideoCaption_131662_Content_80 = {
    Text = "Tenggelam……"
  },
  AvgVideoCaption_131662_Content_81 = {
    Text = "Bola arang kecil, ingin bertemu"
  },
  AvgVideoCaption_131662_Content_82 = {
    Text = "Teman, ingin bertemu……"
  },
  AvgVideoCaption_131662_Content_83 = {
    Text = "Bola arang kecil, tidak ada..."
  },
  AvgVideoCaption_131662_Content_84 = {
    Text = "Teman... tidak..."
  },
  AvgVideoCaption_131662_Content_85 = {
    Text = "Jangan... jangan..."
  },
  AvgVideoCaption_131662_Content_86 = {
    Text = "Tolong tetap tenang, Mosk"
  },
  AvgVideoCaption_131662_Content_87 = {
    Text = "Kamu sekarang berada di Pusat Penelitian Pembangun Mythag"
  },
  AvgVideoCaption_131662_Content_88 = {
    Text = "Di sini sangat aman"
  },
  AvgVideoCaption_131662_Content_89 = {
    Text = "Kami telah melakukan analisis awal terhadap bahasamu"
  },
  AvgVideoCaption_131662_Content_9 = {
    Text = "Hanya sedikit waktu akan berbicara sendiri dalam @2 dan terjebak dalam keadaan delusi yang parah"
  },
  AvgVideoCaption_131662_Content_90 = {
    Text = "Namun masih terdapat banyak kosakata yang sulit dipahami"
  },
  AvgVideoCaption_131662_Content_91 = {
    Text = "Oleh karena itu, kita perlu……"
  },
  AvgVideoCaption_131662_Content_92 = {
    Text = "Tidak... tidak, wajah, wajah"
  },
  AvgVideoCaption_131662_Content_93 = {
    Text = "Tidak punya wajah! Tidak terlihat"
  },
  AvgVideoCaption_131662_Content_94 = {
    Text = "Air menutupi, distorsi! Tidak bisa melihat"
  },
  AvgVideoCaption_131662_Content_95 = {
    Text = "Monster! Monster! Jangan!!!!!!"
  },
  AvgVideoCaption_131662_Content_96 = {
    Text = "Kalian, orang baik…"
  },
  AvgVideoCaption_131662_Content_97 = {
    Text = "Monster... monster..."
  },
  AvgVideoCaption_131662_Content_98 = {
    Text = "Normal, wajah……"
  },
  AvgVideoCaption_131662_Content_99 = {
    Text = "Distorsi… Pusaran…"
  },
  AvgVideoCaption_134291_Content_1 = {Text = "nasib"},
  AvgVideoCaption_134291_Content_10 = {
    Text = "Semuanya, kurajut dengan tanganku sendiri"
  },
  AvgVideoCaption_134291_Content_11 = {
    Text = "Semuanya..."
  },
  AvgVideoCaption_134291_Content_12 = {Text = "Hehehe..."},
  AvgVideoCaption_134291_Content_13 = {
    Text = "Tak seorang pun bisa menentang takdir, kakakku tersayang"
  },
  AvgVideoCaption_134291_Content_14 = {
    Text = "Kita pada akhirnya akan hancur menjadi sehelai benang berikutnya"
  },
  AvgVideoCaption_134291_Content_15 = {
    Text = "Segala jalan takdir, telah ditentukan"
  },
  AvgVideoCaption_134291_Content_16 = {
    Text = "Sang Pengadil"
  },
  AvgVideoCaption_134291_Content_17 = {
    Text = "Sang Penebus"
  },
  AvgVideoCaption_134291_Content_18 = {Text = "Sang Tuan"},
  AvgVideoCaption_134291_Content_19 = {
    Text = "Sang Tahanan..."
  },
  AvgVideoCaption_134291_Content_2 = {
    Text = "Dewa yang kecil dan rapuh"
  },
  AvgVideoCaption_134291_Content_20 = {
    Text = "Peran yang menjadi milikku"
  },
  AvgVideoCaption_134291_Content_21 = {
    Text = "Sudah lama tak bisa dipilih"
  },
  AvgVideoCaption_134291_Content_22 = {
    Text = "Tapi kau pun tak bisa memilih..."
  },
  AvgVideoCaption_134291_Content_23 = {
    Text = "Takdir tersayang"
  },
  AvgVideoCaption_134291_Content_24 = {
    Text = "Naiklah bersamaku ke atas"
  },
  AvgVideoCaption_134291_Content_25 = {
    Text = "Panggung yang telah ditakdirkan bagi kita"
  },
  AvgVideoCaption_134291_Content_3 = {
    Text = "Dia menjatuhkan benang-benang tak terhitung"
  },
  AvgVideoCaption_134291_Content_4 = {
    Text = "Menciptakan lintasan yang telah ditentukan bagi dunia"
  },
  AvgVideoCaption_134291_Content_5 = {
    Text = "Bagi anak-anak, merajut buaian yang paling lembut"
  },
  AvgVideoCaption_134291_Content_6 = {Text = "Puisi"},
  AvgVideoCaption_134291_Content_7 = {Text = "Tarian"},
  AvgVideoCaption_134291_Content_8 = {
    Text = "Peperangan..."
  },
  AvgVideoCaption_134291_Content_9 = {
    Text = "Hari-hari biasa"
  },
  AvgVideoCaption_134292_Content_1 = {
    Text = "Datanglah ke sisiku, Nefraea."
  },
  AvgVideoCaption_134292_Content_10 = {
    Text = "Karakter di atas panggung ini sungguh malang..."
  },
  AvgVideoCaption_134292_Content_100 = {
    Text = "Meskipun itu……"
  },
  AvgVideoCaption_134292_Content_101 = {
    Text = "Bayaran yang teramat berat."
  },
  AvgVideoCaption_134292_Content_102 = {
    Text = "Jadi, kamu lebih rela menjaga alat tenun untuk selamanya,"
  },
  AvgVideoCaption_134292_Content_103 = {
    Text = "Hanya agar dunia tidak jatuh ke dalam kegelapan……"
  },
  AvgVideoCaption_134292_Content_104 = {
    Text = "Terkadang aku berpikir……"
  },
  AvgVideoCaption_134292_Content_105 = {
    Text = "Apakah menurutmu, aku terlalu keras kepala?"
  },
  AvgVideoCaption_134292_Content_106 = {
    Text = "Aku bisa memahaminmu, Kakak……"
  },
  AvgVideoCaption_134292_Content_107 = {
    Text = "Aku hanya, tidak ingin kamu menanggung beban seberat ini."
  },
  AvgVideoCaption_134292_Content_108 = {
    Text = "Semua ini, seharusnya tidak kau tanggung sendirian……"
  },
  AvgVideoCaption_134292_Content_109 = {Text = "Kakak,"},
  AvgVideoCaption_134292_Content_11 = {
    Text = "Apakah dia ditinggalkan oleh orang yang dicintainya?"
  },
  AvgVideoCaption_134292_Content_110 = {
    Text = "kau mengajakku menonton opera ini hari ini,"
  },
  AvgVideoCaption_134292_Content_111 = {
    Text = "apakah untuk memberitahuku semua ini?"
  },
  AvgVideoCaption_134292_Content_112 = {
    Text = "Nasib adalah sangkar panjangku, Nefraea."
  },
  AvgVideoCaption_134292_Content_113 = {
    Text = "Aku hanya berharap pada akhirnya, kau bisa melihat kesepianku,"
  },
  AvgVideoCaption_134292_Content_114 = {
    Text = "sebagai satu-satunya orang yang kupercaya."
  },
  AvgVideoCaption_134292_Content_115 = {
    Text = "Kepercayaan?"
  },
  AvgVideoCaption_134292_Content_116 = {
    Text = "Tapi… sepertinya aku selalu mengacaukan benang-benangmu."
  },
  AvgVideoCaption_134292_Content_117 = {
    Text = "Aku tidak sengaja……"
  },
  AvgVideoCaption_134292_Content_118 = {
    Text = "Tapi setiap kali mendekat, aku selalu memengaruhimu……"
  },
  AvgVideoCaption_134292_Content_119 = {
    Text = "Benang-benang yang rapi dan berkilau itu,"
  },
  AvgVideoCaption_134292_Content_12 = {
    Text = "Penderitaan manusia,"
  },
  AvgVideoCaption_134292_Content_120 = {
    Text = "semuanya menjadi kacau karena kehadiranku……"
  },
  AvgVideoCaption_134292_Content_121 = {
    Text = "Maaf, Kakak,"
  },
  AvgVideoCaption_134292_Content_122 = {
    Text = "aku juga tidak tahu mengapa……"
  },
  AvgVideoCaption_134292_Content_123 = {
    Text = "Karena kamu indah, Nefraea."
  },
  AvgVideoCaption_134292_Content_124 = {
    Text = "Dan sangkar takdir ini, iri terhadap segala hal yang indah."
  },
  AvgVideoCaption_134292_Content_125 = {
    Text = "Keindahan bukanlah kesalahanmu,"
  },
  AvgVideoCaption_134292_Content_126 = {
    Text = "adikku tersayang."
  },
  AvgVideoCaption_134292_Content_127 = {
    Text = "Cinta dan kasih sayangku padamu, tak pernah berkurang karena perbedaan."
  },
  AvgVideoCaption_134292_Content_128 = {
    Text = "Aku sangat mencintai semua kehidupan yang kupandangi,"
  },
  AvgVideoCaption_134292_Content_129 = {
    Text = "seperti aku sangat mencintaimu, satu-satunya yang bisa memahamiku……"
  },
  AvgVideoCaption_134292_Content_13 = {
    Text = "bukan hanya karena cinta dan pengabaian,"
  },
  AvgVideoCaption_134292_Content_130 = {
    Text = "Terima kasih, Kakak……"
  },
  AvgVideoCaption_134292_Content_131 = {
    Text = "……Tidurlah dalam kematian, adikku."
  },
  AvgVideoCaption_134292_Content_132 = {
    Text = "Kak……Kakak?"
  },
  AvgVideoCaption_134292_Content_133 = {
    Text = "Ke……napa?"
  },
  AvgVideoCaption_134292_Content_134 = {
    Text = "Maaf, Nefraea..."
  },
  AvgVideoCaption_134292_Content_135 = {
    Text = "Demi menjaga keutuhan jaring takdir,"
  },
  AvgVideoCaption_134292_Content_136 = {
    Text = "aku harus memangkas arah yang salah."
  },
  AvgVideoCaption_134292_Content_137 = {
    Text = "Sebuah harga yang menyakitkan…… Maka……"
  },
  AvgVideoCaption_134292_Content_138 = {
    Text = "Akulah harga yang harus kau bayar, benar kan?"
  },
  AvgVideoCaption_134292_Content_139 = {
    Text = "Heh…… heheheh……"
  },
  AvgVideoCaption_134292_Content_14 = {
    Text = "Kekasih Nefraea."
  },
  AvgVideoCaption_134292_Content_140 = {
    Text = "Memilih yang menuju keagungan,"
  },
  AvgVideoCaption_134292_Content_141 = {
    Text = "membuang yang kecil dan kotor,"
  },
  AvgVideoCaption_134292_Content_142 = {
    Text = "itulah dirimu…… itulah pilihan abadimu……"
  },
  AvgVideoCaption_134292_Content_143 = {
    Text = "Kemunafikan, pengkhianatan……"
  },
  AvgVideoCaption_134292_Content_144 = {
    Text = "Kau mengkhianatiku……"
  },
  AvgVideoCaption_134292_Content_145 = {
    Text = "Kau mengkhianati dirimu sendiri, Kakak……"
  },
  AvgVideoCaption_134292_Content_146 = {
    Text = "Bencilah aku,"
  },
  AvgVideoCaption_134292_Content_147 = {
    Text = "tinggalkanlah aku."
  },
  AvgVideoCaption_134292_Content_148 = {
    Text = "Pergilah ke tempat di mana kau tak perlu menderita demi keteguhan,"
  },
  AvgVideoCaption_134292_Content_149 = {Text = "Nefraea..."},
  AvgVideoCaption_134292_Content_15 = {Text = "Dia..."},
  AvgVideoCaption_134292_Content_150 = {
    Text = "Semua ini, adalah takdir yang tak bisa kuhindarkan."
  },
  AvgVideoCaption_134292_Content_151 = {
    Text = "Kemunafikan, pengkhianatan……"
  },
  AvgVideoCaption_134292_Content_152 = {
    Text = "Kau mengkhianatiku……"
  },
  AvgVideoCaption_134292_Content_153 = {
    Text = "Kau mengkhianati dirimu sendiri!"
  },
  AvgVideoCaption_134292_Content_154 = {
    Text = "Suatu hari nanti, kau akan menghancurkan semua yang kau hargai……"
  },
  AvgVideoCaption_134292_Content_155 = {
    Text = "Bersama takdir penuh kepura-puraan ini…… Kakak……"
  },
  AvgVideoCaption_134292_Content_156 = {
    Text = "Bencilah aku, Nefraea."
  },
  AvgVideoCaption_134292_Content_157 = {
    Text = "Namun segala kebaikan,"
  },
  AvgVideoCaption_134292_Content_158 = {
    Text = "akan dibalas dengan takdir yang kejam."
  },
  AvgVideoCaption_134292_Content_159 = {
    Text = "Roda takdir tak kenal belas kasihan, berputar tanpa henti."
  },
  AvgVideoCaption_134292_Content_16 = {
    Text = "Ia meratapi ketidakberdayaannya sendiri saat menghadapi takdir."
  },
  AvgVideoCaption_134292_Content_160 = {
    Text = "Aku terpaksa meninggalkanmu,"
  },
  AvgVideoCaption_134292_Content_161 = {
    Text = "berulang kali. Namun selama aku masih ingat untuk apa aku menenun..."
  },
  AvgVideoCaption_134292_Content_162 = {
    Text = "Meskipun tak dapat memperoleh pengertianmu,"
  },
  AvgVideoCaption_134292_Content_163 = {
    Text = "meskipun harus merelakan segalanya,"
  },
  AvgVideoCaption_134292_Content_164 = {
    Text = "aku tetap akan melakukannya."
  },
  AvgVideoCaption_134292_Content_165 = {
    Text = "Ini adalah tanggung jawabku sebagai Sang Penenun."
  },
  AvgVideoCaption_134292_Content_166 = {
    Text = "Ini adalah kesendirian yang harus kulalui."
  },
  AvgVideoCaption_134292_Content_167 = {
    Text = "Biarlah takdir..."
  },
  AvgVideoCaption_134292_Content_168 = {
    Text = "membelenggu kita berdua sepenuhnya."
  },
  AvgVideoCaption_134292_Content_17 = {
    Text = "Karakter ini sama sekali tidak pintar."
  },
  AvgVideoCaption_134292_Content_18 = {
    Text = "Dia cukup berdoa kepada seseorang seperti Kakak yang bisa mengubah takdir,"
  },
  AvgVideoCaption_134292_Content_19 = {Text = "Benar kan?"},
  AvgVideoCaption_134292_Content_2 = {
    Text = "Kak, ini pertama kalinya kamu mengajakku ke teatermu!"
  },
  AvgVideoCaption_134292_Content_20 = {
    Text = "Takdir memberiku kuasa untuk menenun,"
  },
  AvgVideoCaption_134292_Content_21 = {
    Text = "Tapi aku tidak mampu memberikan kedamaian kepada setiap orang..."
  },
  AvgVideoCaption_134292_Content_22 = {
    Text = "Di dunia ini memang ada takdir yang indah,"
  },
  AvgVideoCaption_134292_Content_23 = {
    Text = "Tapi selalu ada seseorang yang harus menanggung kegilaan dan kehancuran yang seharusnya menimpa mereka."
  },
  AvgVideoCaption_134292_Content_24 = {
    Text = "Aku menjaga jaring takdir ini,"
  },
  AvgVideoCaption_134292_Content_25 = {
    Text = "merajut suka dan duka jutaan orang dengan untaian benang."
  },
  AvgVideoCaption_134292_Content_26 = {
    Text = "Tapi pada akhirnya..."
  },
  AvgVideoCaption_134292_Content_27 = {
    Text = "aku hanyalah seorang aktor canggung dalam naskahku sendiri."
  },
  AvgVideoCaption_134292_Content_28 = {
    Text = "Mana mungkin,"
  },
  AvgVideoCaption_134292_Content_29 = {
    Text = "Kakak kan orang yang bisa mengendalikan takdir!"
  },
  AvgVideoCaption_134292_Content_3 = {
    Text = "Kita akan menonton apa? Drama? Pertunjukan tari?"
  },
  AvgVideoCaption_134292_Content_30 = {
    Text = "Di ujung benang, terhubung dengan kehampaan yang kacau."
  },
  AvgVideoCaption_134292_Content_31 = {
    Text = "Sang penguasa takdir,"
  },
  AvgVideoCaption_134292_Content_32 = {
    Text = "pada akhirnya juga hanyalah hamba takdir..."
  },
  AvgVideoCaption_134292_Content_33 = {Text = "Nefraea"},
  AvgVideoCaption_134292_Content_34 = {
    Text = "Adikku satu-satunya."
  },
  AvgVideoCaption_134292_Content_35 = {Text = "Mungkin..."},
  AvgVideoCaption_134292_Content_36 = {
    Text = "hanya kamu yang benar-benar bisa memahami kesendirian ini."
  },
  AvgVideoCaption_134292_Content_37 = {
    Text = "Ternyata... Kakak juga bukan serba bisa ya..."
  },
  AvgVideoCaption_134292_Content_38 = {
    Text = "Aku kurang mengerti..."
  },
  AvgVideoCaption_134292_Content_39 = {
    Text = "Tapi bagaimanapun juga,"
  },
  AvgVideoCaption_134292_Content_4 = {
    Text = "Cepat beritahu aku!"
  },
  AvgVideoCaption_134292_Content_40 = {
    Text = "aku akan selalu menemani Kakak selamanya!"
  },
  AvgVideoCaption_134292_Content_41 = {
    Text = "Sepertinya aku mulai sedikit memahaminya,"
  },
  AvgVideoCaption_134292_Content_42 = {Text = "Kakak..."},
  AvgVideoCaption_134292_Content_43 = {
    Text = "Sang penyanyi ini,"
  },
  AvgVideoCaption_134292_Content_44 = {
    Text = "sehelai daun kering yang melayang tak berdaya,"
  },
  AvgVideoCaption_134292_Content_45 = {
    Text = "hanya bisa pasrah didera oleh takdir..."
  },
  AvgVideoCaption_134292_Content_46 = {
    Text = "Betapa malangnya orang itu..."
  },
  AvgVideoCaption_134292_Content_47 = {Text = "Nefraea"},
  AvgVideoCaption_134292_Content_48 = {
    Text = "Jika kaulah yang menulisnya,"
  },
  AvgVideoCaption_134292_Content_49 = {
    Text = "takdir seperti apa yang akan kauberikan padanya?"
  },
  AvgVideoCaption_134292_Content_5 = {
    Text = "Sst, pertunjukannya akan segera dimulai."
  },
  AvgVideoCaption_134292_Content_50 = {
    Text = "Hmm, kurasa aku akan menuliskan tragedi paling megah untuknya!"
  },
  AvgVideoCaption_134292_Content_51 = {
    Text = "Seseorang yang dibuang,"
  },
  AvgVideoCaption_134292_Content_52 = {
    Text = "seseorang yang ditakdirkan menjadi figuran belaka..."
  },
  AvgVideoCaption_134292_Content_53 = {
    Text = "Jika aku yang menulis ulang, aku akan menyalakan api,"
  },
  AvgVideoCaption_134292_Content_54 = {
    Text = "membakar semua yang mengganggunya, yang membelenggunya,"
  },
  AvgVideoCaption_134292_Content_55 = {
    Text = "membakar segala ketidakadilan hingga menjadi abu!"
  },
  AvgVideoCaption_134292_Content_56 = {
    Text = "Penuh duka, penuh nestapa, dipenuhi hiruk-pikuk dan kehancuran..."
  },
  AvgVideoCaption_134292_Content_57 = {
    Text = "Keindahan yang membakar segalanya,"
  },
  AvgVideoCaption_134292_Content_58 = {
    Text = "itulah yang paling cocok untuknya!"
  },
  AvgVideoCaption_134292_Content_59 = {
    Text = "Iya, Nefraea."
  },
  AvgVideoCaption_134292_Content_6 = {
    Text = "Malam ini... adalah sebuah opera."
  },
  AvgVideoCaption_134292_Content_60 = {
    Text = "Kau tetap percaya,"
  },
  AvgVideoCaption_134292_Content_61 = {
    Text = "bahwa takdir seharusnya berakhir dengan kehancuran."
  },
  AvgVideoCaption_134292_Content_62 = {
    Text = "Demi memenuhi imajinasi tragis dalam hati,"
  },
  AvgVideoCaption_134292_Content_63 = {
    Text = "demi menjaga kesempurnaan,"
  },
  AvgVideoCaption_134292_Content_64 = {
    Text = "kau rela membiarkan orang-orang berakhir dengan takdir yang menyedihkan..."
  },
  AvgVideoCaption_134292_Content_65 = {
    Text = "A-apa? Tentu saja bukan!"
  },
  AvgVideoCaption_134292_Content_66 = {
    Text = "Aku hanya menyukai kepahitan setelah gairah terkuras habis,"
  },
  AvgVideoCaption_134292_Content_67 = {
    Text = "sama seperti kau yang menyukai akhir cerita yang sempurna!"
  },
  AvgVideoCaption_134292_Content_68 = {
    Text = "Tapi Kakak,"
  },
  AvgVideoCaption_134292_Content_69 = {
    Text = "jika takdir sudah ditakdirkan menuju kehancuran, mengapa tidak melepaskannya saja?"
  },
  AvgVideoCaption_134292_Content_7 = {
    Text = "Seorang wanita yang terbelenggu oleh takdir,"
  },
  AvgVideoCaption_134292_Content_70 = {
    Text = "Membiarkan mereka menuju kehancuran yang sudah ditakdirkan, bukankah itu indah?"
  },
  AvgVideoCaption_134292_Content_71 = {
    Text = "Roda takdir berputar tanpa ampun,"
  },
  AvgVideoCaption_134292_Content_72 = {
    Text = "bahkan kau pun tak mampu mengubah akhirnya."
  },
  AvgVideoCaption_134292_Content_73 = {
    Text = "Mengapa tetap menjaga jaring takdir, bertahan dalam kerja paksa yang sia-sia ini?"
  },
  AvgVideoCaption_134292_Content_74 = {
    Text = "Roda takdir memang tanpa ampun."
  },
  AvgVideoCaption_134292_Content_75 = {
    Text = "Namun makna dari putarannya bukanlah untuk menghancurkan segalanya,"
  },
  AvgVideoCaption_134292_Content_76 = {
    Text = "melainkan agar kehidupan terus berlanjut dalam keteraturan."
  },
  AvgVideoCaption_134292_Content_77 = {
    Text = "Lihatlah karakter di atas panggung itu."
  },
  AvgVideoCaption_134292_Content_78 = {
    Text = "Dia dibuang oleh takdir,"
  },
  AvgVideoCaption_134292_Content_79 = {
    Text = "menanggung penderitaan yang tak terhitung,"
  },
  AvgVideoCaption_134292_Content_8 = {
    Text = "sedang menunggu penebusannya."
  },
  AvgVideoCaption_134292_Content_80 = {
    Text = "dia menangisi ketidakberdayaan dan kesengsaraannya..."
  },
  AvgVideoCaption_134292_Content_81 = {
    Text = "Meskipun dia tak pernah percaya pada akhir yang indah,"
  },
  AvgVideoCaption_134292_Content_82 = {
    Text = "dia juga tak pernah menyerah."
  },
  AvgVideoCaption_134292_Content_83 = {
    Text = "Jika dia menyerah,"
  },
  AvgVideoCaption_134292_Content_84 = {
    Text = "semua takdir ini tak akan memiliki makna lagi."
  },
  AvgVideoCaption_134292_Content_85 = {
    Text = "Di tengah segala kekosongan,"
  },
  AvgVideoCaption_134292_Content_86 = {
    Text = "selalu dibutuhkan seseorang untuk menjaga harapan,"
  },
  AvgVideoCaption_134292_Content_87 = {
    Text = "adikku tersayang."
  },
  AvgVideoCaption_134292_Content_88 = {
    Text = "Aku mengerti, Kakak……"
  },
  AvgVideoCaption_134292_Content_89 = {
    Text = "Orang yang meratap di atas panggung itu, adalah kamu, kan?"
  },
  AvgVideoCaption_134292_Content_9 = {
    Text = "\"Takdir yang kejam\"..."
  },
  AvgVideoCaption_134292_Content_90 = {
    Text = "Aku pernah menyaksikan umat manusia digilas oleh penderitaan,"
  },
  AvgVideoCaption_134292_Content_91 = {
    Text = "Berjalan menuju akhir dalam tarikan yang berulang dan sunyi, hari demi hari."
  },
  AvgVideoCaption_134292_Content_92 = {
    Text = "Kegelapan tanpa akhir, kesendirian tanpa batas……"
  },
  AvgVideoCaption_134292_Content_93 = {
    Text = "Jika masa depan seperti itu yang menjadi balasan,"
  },
  AvgVideoCaption_134292_Content_94 = {
    Text = "Tak diragukan lagi, itu adalah pengkhianatan terhadap kehidupan."
  },
  AvgVideoCaption_134292_Content_95 = {
    Text = "Justru karena aku menghargai setiap detak jantung,"
  },
  AvgVideoCaption_134292_Content_96 = {
    Text = "Setiap tetes air mata……"
  },
  AvgVideoCaption_134292_Content_97 = {
    Text = "Aku tak tega membiarkan dunia tergelincir ke dalam jurang kekosongan."
  },
  AvgVideoCaption_134292_Content_98 = {
    Text = "Ini adalah pilihanku,"
  },
  AvgVideoCaption_134292_Content_99 = {
    Text = "Dan aku juga harus membayar harganya."
  },
  AvgVideoCaption_139854_Content_1 = {
    Text = "Surat Pertama"
  },
  AvgVideoCaption_139854_Content_10 = {
    Text = "Itulah yang disebut \"Cinta\" rupanya"
  },
  AvgVideoCaption_139854_Content_11 = {
    Text = "Setiap masa memiliki saat Akhirnya."
  },
  AvgVideoCaption_139854_Content_12 = {
    Text = "Sebuah kisah tidaklah abadi."
  },
  AvgVideoCaption_139854_Content_13 = {
    Text = "Aku sekarang, sepertinya berada, di sini dan saat ini."
  },
  AvgVideoCaption_139854_Content_14 = {
    Text = "Aku merasakannya secara mendalam, berulang kali,"
  },
  AvgVideoCaption_139854_Content_15 = {
    Text = "Ini adalah alam semesta tanpa @3"
  },
  AvgVideoCaption_139854_Content_16 = {
    Text = "Surat Ketiga"
  },
  AvgVideoCaption_139854_Content_17 = {
    Text = "Hal-hal tentang \"Saya\" perlahan-lahan mulai teringat kembali."
  },
  AvgVideoCaption_139854_Content_18 = {
    Text = "Rasanya aku juga semakin memahami hal-hal yang terjadi sekarang."
  },
  AvgVideoCaption_139854_Content_19 = {
    Text = "Peradaban di sini, rasanya cukup terbelakang ya."
  },
  AvgVideoCaption_139854_Content_2 = {
    Text = "Saat ini, kesadaranku ada di sini."
  },
  AvgVideoCaption_139854_Content_20 = {
    Text = "Namun, hal seperti itu pun memiliki keunikannya sendiri. Meskipun tidak membuatku benci juga."
  },
  AvgVideoCaption_139854_Content_21 = {
    Text = "Kukira teknologi dan hal-hal semacam itu akan lebih maju…"
  },
  AvgVideoCaption_139854_Content_22 = {
    Text = "Dibanding hal-hal itu, selalu merasa ada sesuatu yang lebih penting, tapi apa itu sebenarnya."
  },
  AvgVideoCaption_139854_Content_23 = {
    Text = "Hal yang sangat penting. Orang yang sangat berharga."
  },
  AvgVideoCaption_139854_Content_24 = {
    Text = "Saat tidak mengerti akan merasa Gelisah, tapi tetap ingin tahu lebih banyak."
  },
  AvgVideoCaption_139854_Content_25 = {
    Text = "Ingin cepat tahu. Ingin cepat bertemu. Itu apa ya?"
  },
  AvgVideoCaption_139854_Content_26 = {
    Text = "Hanya dengan memikirkannya saja sudah sangat menyenangkan."
  },
  AvgVideoCaption_139854_Content_27 = {
    Text = "Alangkah baiknya jika bisa menemukanku…"
  },
  AvgVideoCaption_139854_Content_28 = {
    Text = "Surat Keempat"
  },
  AvgVideoCaption_139854_Content_29 = {
    Text = "Berbagai macam kenangan mengalir masuk."
  },
  AvgVideoCaption_139854_Content_3 = {
    Text = "Tempat ini terasa asing, dan sangat lengang."
  },
  AvgVideoCaption_139854_Content_30 = {
    Text = "Seperti diserang oleh Kekuatan yang dahsyat"
  },
  AvgVideoCaption_139854_Content_31 = {
    Text = "Sangat dingin, seperti tubuh akan Mencabik-cabik"
  },
  AvgVideoCaption_139854_Content_32 = {
    Text = "Sangat bahagia, seperti seluruh tubuh menjadi membara"
  },
  AvgVideoCaption_139854_Content_33 = {
    Text = "Kenangan horor, kenangan menyenangkan, kenangan penuh kegembiraan, kenangan penuh kesedihan"
  },
  AvgVideoCaption_139854_Content_34 = {
    Text = "Namun, kenangan yang paling penting hanya satu."
  },
  AvgVideoCaption_139854_Content_35 = {
    Text = "Kenangan yang dilewati bersama dirimu yang berharga."
  },
  AvgVideoCaption_139854_Content_36 = {
    Text = "Di mana kenangan itu berada…"
  },
  AvgVideoCaption_139854_Content_37 = {
    Text = "Surat Kelima"
  },
  AvgVideoCaption_139854_Content_38 = {
    Text = "Sebuah tempat yang luas seperti padang pasir."
  },
  AvgVideoCaption_139854_Content_39 = {
    Text = "Di sekitarnya tidak ada satu pun rumput atau pohon."
  },
  AvgVideoCaption_139854_Content_4 = {
    Text = "Apakah kamu juga berada di suatu tempat di planet ini?"
  },
  AvgVideoCaption_139854_Content_40 = {
    Text = "Jika sebutir biji dandelion jatuh di padang pasir seperti itu."
  },
  AvgVideoCaption_139854_Content_41 = {
    Text = "Dibawa angin, jauh sekali meninggalkan kampung halaman,"
  },
  AvgVideoCaption_139854_Content_42 = {
    Text = "apa yang dipikirkan oleh biji kecil itu?"
  },
  AvgVideoCaption_139854_Content_43 = {
    Text = "Jika, di padang pasir itu— bahkan hanya satu orang"
  },
  AvgVideoCaption_139854_Content_44 = {
    Text = "jika ada seseorang yang tahu bahwa ada yang mencintai bunga,"
  },
  AvgVideoCaption_139854_Content_45 = {
    Text = "bunga dandelion sungguh indah, sambil berkata begitu,"
  },
  AvgVideoCaption_139854_Content_46 = {
    Text = "jika bisa selalu menemani di sisi,"
  },
  AvgVideoCaption_139854_Content_47 = {
    Text = "selamanya, di sisi ku,"
  },
  AvgVideoCaption_139854_Content_48 = {
    Text = "jika kamu ada di sini……"
  },
  AvgVideoCaption_139854_Content_49 = {
    Text = "Terima kasih……"
  },
  AvgVideoCaption_139854_Content_5 = {
    Text = "Surat Kedua"
  },
  AvgVideoCaption_139854_Content_50 = {
    Text = "tidak akan terlupakan……"
  },
  AvgVideoCaption_139854_Content_6 = {
    Text = "Aku ingat saat bertemu dengan seseorang yang penting."
  },
  AvgVideoCaption_139854_Content_7 = {
    Text = "Dalam tatapan itu, hanya ada sedikit rasa terkejut…"
  },
  AvgVideoCaption_139854_Content_8 = {
    Text = "Tanpa Ketakutan, tanpa Keserakahan"
  },
  AvgVideoCaption_139854_Content_9 = {
    Text = "Selalu memperlakukanku dengan begitu lembut"
  },
  AvgVideoCaption_139855_Content_1 = {
    Text = "Masih ingat aku?"
  },
  AvgVideoCaption_139855_Content_2 = {
    Text = "Ketika cinta tumbuh menjadi Caro"
  },
  AvgVideoCaption_139855_Content_3 = {
    Text = "Itulah milik kita"
  },
  AvgVideoCaption_139855_Content_4 = {Text = "Indah"},
  AvgVideoCaption_139855_Content_5 = {
    Text = "Namun dunia yang kejam"
  },
  AvgVideoCaption_139855_Content_6 = {
    Text = "Hehe, hehehehe"
  },
  AvgVideoCaption_139855_Content_7 = {Text = "Dan juga"},
  AvgVideoCaption_139855_Content_8 = {
    Text = "Yang bernama pertemuan"
  },
  AvgVideoCaption_139855_Content_9 = {
    Text = "Keajaiban kecil"
  },
  AvgVideoCaption_143591_Content_1 = {
    Text = "Tidak perlu menunjukkan Ekspresi seperti itu"
  },
  AvgVideoCaption_143591_Content_10 = {
    Text = "Mungkin benar-benar akan mendapat kepuasan dari diriku yang masih dalam keadaan marah"
  },
  AvgVideoCaption_143591_Content_11 = {
    Text = "Percayalah padaku, aku sudah mencoba kegelapan, rasa sakit, Pemisahan keluarga sedarah"
  },
  AvgVideoCaption_143591_Content_12 = {
    Text = "Juga mencoba membiarkan Sanga tumbuh bersama tulang-tulang kalian"
  },
  AvgVideoCaption_143591_Content_13 = {
    Text = "Membiarkan air laut mengkorosi kulit kalian"
  },
  AvgVideoCaption_143591_Content_14 = {
    Text = "Teritip menggerogoti Caro kalian"
  },
  AvgVideoCaption_143591_Content_15 = {
    Text = "Aku pikir semakin banyak penderitaan kalian"
  },
  AvgVideoCaption_143591_Content_16 = {
    Text = "Penderitaanku akan sedikit berkurang"
  },
  AvgVideoCaption_143591_Content_17 = {
    Text = "Namun ternyata tidak"
  },
  AvgVideoCaption_143591_Content_18 = {
    Text = "Aku telah membuat sebuah kesalahan"
  },
  AvgVideoCaption_143591_Content_19 = {
    Text = "Kesalahanku"
  },
  AvgVideoCaption_143591_Content_2 = {
    Text = "Aku tahu pikiran-pikiran konyol dan menyedihkan kalian"
  },
  AvgVideoCaption_143591_Content_20 = {
    Text = "Berasal dari kebodohan dan kepercayaan buta kalian yang menyebarkan bencana horor yang sulit dipahami"
  },
  AvgVideoCaption_143591_Content_21 = {
    Text = "yang membuat segalanya menjadi seperti ini"
  },
  AvgVideoCaption_143591_Content_22 = {
    Text = "aku masih memandang kalian sebagai manusia"
  },
  AvgVideoCaption_143591_Content_23 = {
    Text = "semakin kotor penderitaannya"
  },
  AvgVideoCaption_143591_Content_24 = {
    Text = "semakin besar hadiah bagi kalian, makhluk-makhluk menjijikkan ini"
  },
  AvgVideoCaption_143591_Content_25 = {
    Text = "baik itu rasa sakit fisik"
  },
  AvgVideoCaption_143591_Content_26 = {
    Text = "maupun siksaan batin"
  },
  AvgVideoCaption_143591_Content_27 = {
    Text = "semuanya membuat kalian percaya bahwa Pengorbanan kalian sungguh mulia"
  },
  AvgVideoCaption_143591_Content_28 = {
    Text = "bahwa setelah mati, dewa kalian yang menjijikkan dan hina itu akan membawa kalian ke apa yang disebut dunia baru"
  },
  AvgVideoCaption_143591_Content_29 = {Text = "Jadi..."},
  AvgVideoCaption_143591_Content_3 = {
    Text = "Aku mengerti"
  },
  AvgVideoCaption_143591_Content_30 = {
    Text = "ah, seperti yang kamu lihat"
  },
  AvgVideoCaption_143591_Content_31 = {
    Text = "Servini, Tristan, Cyril, Nash… setiap satu dari mereka"
  },
  AvgVideoCaption_143591_Content_32 = {
    Text = "orang-orang yang kamu kira telah mati bersamamu demi keyakinan mulia kalian"
  },
  AvgVideoCaption_143591_Content_33 = {
    Text = "mereka semua ada di sini"
  },
  AvgVideoCaption_143591_Content_34 = {
    Text = "Servini yang lebih Setia dan penuh Kegilaan darimu, yang mati pada tempatnya"
  },
  AvgVideoCaption_143591_Content_35 = {
    Text = "Cyril yang pemalu, yang teguh, yang bahkan melelehkan ususnya sendiri…"
  },
  AvgVideoCaption_143591_Content_36 = {
    Text = "kalian tidak tahu apa-apa tentang jurang"
  },
  AvgVideoCaption_143591_Content_37 = {
    Text = "ayo, tarik napas dalam-dalam"
  },
  AvgVideoCaption_143591_Content_38 = {Text = "Relaksasi"},
  AvgVideoCaption_143591_Content_39 = {
    Text = "Selamat datang kembali"
  },
  AvgVideoCaption_143591_Content_4 = {
    Text = "Kalian menginginkan rasa sakit"
  },
  AvgVideoCaption_143591_Content_40 = {
    Text = "sekarang, apakah kamu mengerti, mangsa"
  },
  AvgVideoCaption_143591_Content_41 = {
    Text = "jurang… tidak akan membawa pembantaian yang brutal"
  },
  AvgVideoCaption_143591_Content_42 = {
    Text = "tidak ada Darah dan api yang menyenangkan seperti yang kamu bayangkan"
  },
  AvgVideoCaption_143591_Content_43 = {
    Text = "Hanya miliaran ton air laut"
  },
  AvgVideoCaption_143591_Content_44 = {
    Text = "Zat kuno yang bangkit bersama planet ini"
  },
  AvgVideoCaption_143591_Content_45 = {
    Text = "Akan menekan kalian selamanya"
  },
  AvgVideoCaption_143591_Content_46 = {
    Text = "Menyelimuti kalian"
  },
  AvgVideoCaption_143591_Content_47 = {
    Text = "Dalam kegelapan biru tak bertepi"
  },
  AvgVideoCaption_143591_Content_48 = {Text = "Selain aku"},
  AvgVideoCaption_143591_Content_49 = {
    Text = "Tidak ada dewa mana pun yang bisa menyelamatkan kalian ke mana pun"
  },
  AvgVideoCaption_143591_Content_5 = {
    Text = "Sebuah hukuman yang membuat kalian bergairah"
  },
  AvgVideoCaption_143591_Content_50 = {
    Text = "Kalian tidak akan punya cara apa pun untuk melarikan diri"
  },
  AvgVideoCaption_143591_Content_51 = {
    Text = "Bahkan kematian yang berulang tak terhitung kali"
  },
  AvgVideoCaption_143591_Content_52 = {
    Text = "Entah itu seperti Tristan"
  },
  AvgVideoCaption_143591_Content_53 = {
    Text = "Merobek tenggorokan sendiri"
  },
  AvgVideoCaption_143591_Content_54 = {
    Text = "Atau meniru Nash yang cerdas"
  },
  AvgVideoCaption_143591_Content_55 = {
    Text = "Mencoba mengunyah lidah sendiri hingga hancur"
  },
  AvgVideoCaption_143591_Content_56 = {
    Text = "Silakan coba sesuka hati"
  },
  AvgVideoCaption_143591_Content_57 = {
    Text = "Kalian tidak bisa melarikan diri"
  },
  AvgVideoCaption_143591_Content_58 = {
    Text = "Kalian hanya akan perlahan-lahan merosot"
  },
  AvgVideoCaption_143591_Content_59 = {
    Text = "Lalu bangkit kembali"
  },
  AvgVideoCaption_143591_Content_6 = {
    Text = "Dan pada akhirnya dengan kematian kalian yang tak berarti"
  },
  AvgVideoCaption_143591_Content_60 = {
    Text = "Sampai aku bosan dengan hal ini"
  },
  AvgVideoCaption_143591_Content_61 = {
    Text = "Bahkan merasakan rasa sakit pun akan menjadi kemewahan bagi kalian"
  },
  AvgVideoCaption_143591_Content_62 = {
    Text = "Di Epoyanis hanya ada satu hukum"
  },
  AvgVideoCaption_143591_Content_63 = {
    Text = "Juru selamatmu yang hina itu tidak akan datang, mangsa"
  },
  AvgVideoCaption_143591_Content_64 = {
    Text = "Aku, satu-satunya dewa"
  },
  AvgVideoCaption_143591_Content_65 = {
    Text = "Berlutut, persembahkan dirimu kepada laut"
  },
  AvgVideoCaption_143591_Content_66 = {
    Text = "Lalu menderita selamanya di dalam jurang"
  },
  AvgVideoCaption_143591_Content_7 = {
    Text = "Untuk menyelesaikan sebuah Pengorbanan diri yang penuh Kesetiaan"
