  AvgVideoCaption_143591_Content_8 = {
    Text = "Sayang sekali"
  },
  AvgVideoCaption_143591_Content_9 = {
    Text = "Seharusnya kamu datang lebih awal"
  },
  AvgVideoCaption_148014_Content_1 = {
    Text = "Ada seseorang yang sedang melantunkan doa kepada Paus Langit Bintang"
  },
  AvgVideoCaption_148014_Content_10 = {
    Text = "Kekuatan-Nya yang liar dan ganas itu, aku merasakannya……"
  },
  AvgVideoCaption_148014_Content_100 = {
    Text = "Aku akan melindungi makhluk hidup di tempat ini"
  },
  AvgVideoCaption_148014_Content_101 = {
    Text = "Aku akan membawa ketenangan bagi kota ini"
  },
  AvgVideoCaption_148014_Content_102 = {
    Text = "Aku akan membawa ke sini, bisikan penuh kasih dari Paus Langit Bintang…"
  },
  AvgVideoCaption_148014_Content_103 = {
    Text = "Kamu...kamu..."
  },
  AvgVideoCaption_148014_Content_104 = {Text = "Tadi…"},
  AvgVideoCaption_148014_Content_105 = {
    Text = "Yang tadi itu……"
  },
  AvgVideoCaption_148014_Content_106 = {
    Text = "Adalah seorang ibu dari tiga anak!"
  },
  AvgVideoCaption_148014_Content_107 = {Text = "Benarkah?"},
  AvgVideoCaption_148014_Content_108 = {
    Text = "Kalau begitu selamat untuk mereka"
  },
  AvgVideoCaption_148014_Content_109 = {
    Text = "Terhindar dari banyak penderitaan"
  },
  AvgVideoCaption_148014_Content_11 = {
    Text = "Para penganut yang mempercayai-Nya"
  },
  AvgVideoCaption_148014_Content_110 = {
    Text = "Kau……kau sudah berjanji……"
  },
  AvgVideoCaption_148014_Content_111 = {
    Text = "Membawa pembebasan bagimu, membawa keselamatan bagi tempat ini"
  },
  AvgVideoCaption_148014_Content_112 = {
    Text = "Bukankah itulah janjiku?"
  },
  AvgVideoCaption_148014_Content_113 = {
    Text = "Tunggu! Tunggu!"
  },
  AvgVideoCaption_148014_Content_114 = {
    Text = "Kita bisa pergi bersama untuk mengikuti seleksi Paus Langit Bintang!"
  },
  AvgVideoCaption_148014_Content_115 = {
    Text = "Aku bisa membantumu, aku bisa……"
  },
  AvgVideoCaption_148014_Content_116 = {
    Text = "Tawaran yang menarik"
  },
  AvgVideoCaption_148014_Content_117 = {
    Text = "Sayang sekali aku sudah berjanji padamu"
  },
  AvgVideoCaption_148014_Content_118 = {
    Text = "Aku selalu menepati kata-kataku"
  },
  AvgVideoCaption_148014_Content_119 = {
    Text = "Kepala-kepala ini sebagai persembahan"
  },
  AvgVideoCaption_148014_Content_12 = {
    Text = "Semua akan tergerus oleh kekuatan ini"
  },
  AvgVideoCaption_148014_Content_120 = {
    Text = "Seharusnya sudah cukup……"
  },
  AvgVideoCaption_148014_Content_121 = {
    Text = "Mereka tidak mengerti apa itu kekuatan"
  },
  AvgVideoCaption_148014_Content_122 = {
    Text = "Juga tidak mengerti apa yang kau inginkan"
  },
  AvgVideoCaption_148014_Content_123 = {
    Text = "Tapi aku tahu"
  },
  AvgVideoCaption_148014_Content_124 = {
    Text = "Bukti kekuatan, telah kupersembahkan untukmu"
  },
  AvgVideoCaption_148014_Content_125 = {
    Text = "Aku melihat kegembiraanmu, Paus Langit Bintang……"
  },
  AvgVideoCaption_148014_Content_126 = {
    Text = "Ternyata begini cara membuka pintu untuk ikut bertarung……"
  },
  AvgVideoCaption_148014_Content_127 = {
    Text = "Sebentar lagi, kau akan bertemu denganku"
  },
  AvgVideoCaption_148014_Content_128 = {
    Text = "Nantikanlah kedatanganku…… Leviathan"
  },
  AvgVideoCaption_148014_Content_13 = {
    Text = "Perang, penjarahan, pembunuhan, darah……"
  },
  AvgVideoCaption_148014_Content_14 = {
    Text = "Hasrat Paus Langit Bintang, tidak pernah ada habisnya"
  },
  AvgVideoCaption_148014_Content_15 = {
    Text = "Kamu……apakah ingin menolak karunia Dewa Bapa?"
  },
  AvgVideoCaption_148014_Content_16 = {
    Text = "Aku? Heh. Tidak"
  },
  AvgVideoCaption_148014_Content_17 = {
    Text = "Aku menikmatinya, Pendeta Dewa"
  },
  AvgVideoCaption_148014_Content_18 = {
    Text = "Inilah tujuanku datang ke sini"
  },
  AvgVideoCaption_148014_Content_19 = {Text = "Sayangnya"},
  AvgVideoCaption_148014_Content_2 = {
    Text = "Gereja tempat para yang terinfeksi ditempatkan, apakah di sini?"
  },
  AvgVideoCaption_148014_Content_20 = {
    Text = "Tidak setiap penganut mampu menanggung berkah penuh semangat-Nya"
  },
  AvgVideoCaption_148014_Content_21 = {
    Text = "Ah, benar, benar"
  },
  AvgVideoCaption_148014_Content_22 = {
    Text = "Para jemaat yang malang namun bahagia itu"
  },
  AvgVideoCaption_148014_Content_23 = {
    Text = "Bersukacita karena kekuatan Dewa Bapa"
  },
  AvgVideoCaption_148014_Content_24 = {
    Text = "Dan menjadi gila karena kegembiraan itu…"
  },
  AvgVideoCaption_148014_Content_25 = {
    Text = "Maka dari itu, kami membutuhkan penganut sepertimu"
  },
  AvgVideoCaption_148014_Content_26 = {
    Text = "Untuk menghibur roh Dewa Bapa"
  },
  AvgVideoCaption_148014_Content_27 = {
    Text = "Menyelamatkan para jemaat yang malang ini. Hanya kamu…"
  },
  AvgVideoCaption_148014_Content_28 = {
    Text = "Penganut yang terkasih"
  },
  AvgVideoCaption_148014_Content_29 = {
    Text = "Kuharap kamu masih ingat janjimu"
  },
  AvgVideoCaption_148014_Content_3 = {
    Text = "Benar sekali!"
  },
  AvgVideoCaption_148014_Content_30 = {
    Text = "Aku telah berjanji padamu, akan menyelamatkan mereka yang tak mampu menanggung anugerah sang dewa"
  },
  AvgVideoCaption_148014_Content_31 = {
    Text = "Membantu kamu menyelamatkan kota ini"
  },
  AvgVideoCaption_148014_Content_32 = {
    Text = "Aku tidak pernah mengingkari janji"
  },
  AvgVideoCaption_148014_Content_33 = {
    Text = "Ini adalah kehormatan bagi kota ini, penganut"
  },
  AvgVideoCaption_148014_Content_34 = {
    Text = "Namun, kamu bilang ada beberapa korban di sini"
  },
  AvgVideoCaption_148014_Content_35 = {
    Text = "Tapi sekarang yang berdiri di hadapanku, setidaknya ada tiga ratus orang"
  },
  AvgVideoCaption_148014_Content_36 = {
    Text = "Ini adalah kota yang setia"
  },
  AvgVideoCaption_148014_Content_37 = {
    Text = "Dewa Bapa mendengar seruan kami…"
  },
  AvgVideoCaption_148014_Content_38 = {
    Text = "Suara Paus Langit Bintang telah memilih kami!"
  },
  AvgVideoCaption_148014_Content_39 = {
    Text = "Ini adalah kehormatan kami!"
  },
  AvgVideoCaption_148014_Content_4 = {
    Text = "Selamat datang di tempat persembahan paling setia milik Paus Langit Bintang"
  },
  AvgVideoCaption_148014_Content_40 = {
    Text = "Kulihat mereka sekarang sepertinya masih baik-baik saja"
  },
  AvgVideoCaption_148014_Content_41 = {
    Text = "Hanya sementara…"
  },
  AvgVideoCaption_148014_Content_42 = {
    Text = "Jika ini terus berlanjut, kita semua akan menjadi wadah bagi kehendak Paus Langit Bintang"
  },
  AvgVideoCaption_148014_Content_43 = {
    Text = "Mereka akan melantunkan bisikan-Nya"
  },
  AvgVideoCaption_148014_Content_44 = {
    Text = "Menampakkan guratan-Nya di atas kulit……"
  },
  AvgVideoCaption_148014_Content_45 = {
    Text = "Pada akhirnya, kehendak kita akan menyatu dengan Paus Langit Bintang"
  },
  AvgVideoCaption_148014_Content_46 = {
    Text = "Bukankah itu yang kalian inginkan?"
  },
  AvgVideoCaption_148014_Content_47 = {
    Text = "Tentu saja!"
  },
  AvgVideoCaption_148014_Content_48 = {
    Text = "Para penganut kami selamanya bersedia mempersembahkan segalanya untuk Dewa Bapa!"
  },
  AvgVideoCaption_148014_Content_49 = {
    Text = "Tapi, bukan sekarang……"
  },
  AvgVideoCaption_148014_Content_5 = {
    Text = "Namun mereka bukanlah orang yang terinfeksi"
  },
  AvgVideoCaption_148014_Content_50 = {
    Text = "Kami masih ingin mendengar lebih banyak wahyu dari Dewa Bapa……"
  },
  AvgVideoCaption_148014_Content_51 = {
    Text = "Aku juga akan mendapat restu Dewa Bapa, dan mengikuti seleksi-Nya"
  },
  AvgVideoCaption_148014_Content_52 = {
    Text = "Menjadi Eksekutor-Nya yang tiada duanya!"
  },
  AvgVideoCaption_148014_Content_53 = {
    Text = "Maka sebelum itu terjadi, harus...."
  },
  AvgVideoCaption_148014_Content_54 = {
    Text = "Harus ada seseorang yang melangkah lebih dulu untuk kami……"
  },
  AvgVideoCaption_148014_Content_55 = {
    Text = "Ayo, para penganutku yang fanatik"
  },
  AvgVideoCaption_148014_Content_56 = {
    Text = "Borgol wanita ini dan bawa ke hadapan altar!"
  },
  AvgVideoCaption_148014_Content_57 = {
    Text = "Ini tidak termasuk dalam perjanjian kita"
  },
  AvgVideoCaption_148014_Content_58 = {
    Text = "Nyonya yang terhormat, kau pernah berjanji kepadaku"
  },
  AvgVideoCaption_148014_Content_59 = {
    Text = "Bahwa kau tidak akan segan melakukan apa pun"
