  AvgVideoCaption_148014_Content_6 = {
    Text = "Nona yang beriman"
  },
  AvgVideoCaption_148014_Content_60 = {
    Text = "Untuk menyelamatkan kota malang ini, menyelamatkan para penganut yang malang ini"
