  },
  AvgVideoCaption_148014_Content_77 = {Text = "Hehehe..."},
  AvgVideoCaption_148014_Content_78 = {
    Text = "Seandainya kau menemukannya lebih awal"
  },
  AvgVideoCaption_148014_Content_79 = {
    Text = "Mungkin masih bisa menghentikan kami"
