  },
  AvgVideoCaption_148014_Content_98 = {Text = "Bunuh dia!"},
  AvgVideoCaption_148014_Content_99 = {
    Text = "Aku pernah berjanji kepadamu…"
  },
  AvgVideoCaption_149925_Content_1 = {
    Text = "Puncak gunung bersalju tertinggi di dunia"
