  AvgVideoCaption_149926_Content_100 = {
    Text = "menangis itu tidak ada gunanya"
  },
  AvgVideoCaption_149926_Content_101 = {
    Text = "Sekarang, ceritakan tentang dirimu"
  },
  AvgVideoCaption_149926_Content_102 = {
    Text = "Kau mengikutiku selama tiga blok, bukan?"
  },
  AvgVideoCaption_149926_Content_103 = {
    Text = "Kau lihat pergelangan tanganku yang kecil, leherku yang putih"
