  },
  AvgVideoCaption_149926_Content_110 = {
    Text = "…Tapi Tuan, apa kau tidak merasa"
  },
  AvgVideoCaption_149926_Content_111 = {
    Text = "Ruang bawah tanah ini sepertinya lebih dingin dari luar?"
