  AvgVideoCaption_149926_Content_115 = {
    Text = "Kalimat terakhir dari cerita ini"
  },
  AvgVideoCaption_149926_Content_116 = {
    Text = "Sesuai kebiasaan, seharusnya diucapkan oleh orang yang dimakan"
