  AvgVideoCaption_149926_Content_34 = {
    Text = "Tepat saat aku hampir tertidur——"
  },
  AvgVideoCaption_149926_Content_35 = {
    Text = "Aku mendengar dari bawah tumpukan salju"
  },
  AvgVideoCaption_149926_Content_36 = {
    Text = "Ada sebuah suara yang memanggilku"
  },
  AvgVideoCaption_149926_Content_37 = {
    Text = "『Gadis kecil, mengapa kamu menangis?』"
  },
  AvgVideoCaption_149926_Content_38 = {
    Text = "『Apakah karena kamu berkata jujur?』"
  },
  AvgVideoCaption_149926_Content_39 = {
    Text = "『Karena kamu terlalu jujur』"
  },
  AvgVideoCaption_149926_Content_4 = {
    Text = "Aku tidak akan menceritakan hal ini kepada siapa pun…"
  },
  AvgVideoCaption_149926_Content_40 = {
    Text = "『Sampai ditinggalkan di sini begitu saja?』"
  },
  AvgVideoCaption_149926_Content_41 = {
    Text = "Aku tidak berkata apa-apa"
  },
  AvgVideoCaption_149926_Content_42 = {
    Text = "Karena bahkan bibirku pun tak bisa kubuka"
  },
  AvgVideoCaption_149926_Content_43 = {
    Text = "Tapi ia berkata:"
  },
  AvgVideoCaption_149926_Content_44 = {
    Text = "『Tidak apa-apa』"
  },
  AvgVideoCaption_149926_Content_45 = {
    Text = "『Aku akan mengajarimu satu cara bicara』"
  },
  AvgVideoCaption_149926_Content_46 = {
    Text = "『Jika kau mengucapkannya, kau tak akan pernah merasa kedinginan lagi』"
  },
  AvgVideoCaption_149926_Content_47 = {Text = "Maka aku"},
  AvgVideoCaption_149926_Content_48 = {
    Text = "Mempelajari kebohongan pertamaku"
  },
  AvgVideoCaption_149926_Content_49 = {
    Text = "Dengan kebohongan itu"
  },
  AvgVideoCaption_149926_Content_5 = {
    Text = "Aku akan memberikan semua yang ada padaku"
  },
  AvgVideoCaption_149926_Content_50 = {
    Text = "Aku mengetuk pintu rumah petani pertama"
  },
  AvgVideoCaption_149926_Content_51 = {
    Text = "Dan menipu untuk mendapatkan sebuah apel"
  },
  AvgVideoCaption_149926_Content_52 = {
    Text = "Aku hanya menggigit satu kali"
  },
  AvgVideoCaption_149926_Content_53 = {Text = "Sisanya"},
  AvgVideoCaption_149926_Content_54 = {
    Text = "Kuserahkan semua kepada suara itu"
  },
  AvgVideoCaption_149926_Content_55 = {
    Text = "Tahukah kamu"
  },
  AvgVideoCaption_149926_Content_56 = {
    Text = "Ketika seseorang hampir mati kedinginan"
  },
  AvgVideoCaption_149926_Content_57 = {
    Text = "Seluruh tubuhnya justru akan terasa membara"
  },
  AvgVideoCaption_149926_Content_58 = {
    Text = "Lebih hangat dari semua perapian di dunia"
  },
  AvgVideoCaption_149926_Content_59 = {
    Text = "Sejak saat itu"
  },
  AvgVideoCaption_149926_Content_6 = {
    Text = "Jangan jual aku, ya?"
  },
  AvgVideoCaption_149926_Content_60 = {
    Text = "Aku tidak pernah merasa kedinginan lagi"
  },
  AvgVideoCaption_149926_Content_61 = {Text = "Ia berkata"},
  AvgVideoCaption_149926_Content_62 = {
    Text = "Ia hanya \"mengajariku\""
  },
  AvgVideoCaption_149926_Content_63 = {
    Text = "Aku belajar dengan cepat"
  },
  AvgVideoCaption_149926_Content_64 = {
    Text = "Barang-barang hasil tipuan semakin banyak"
  },
  AvgVideoCaption_149926_Content_65 = {
    Text = "Seperti bukit kecil"
  },
  AvgVideoCaption_149926_Content_66 = {
    Text = "Memenuhi seluruh rumah"
  },
  AvgVideoCaption_149926_Content_67 = {
    Text = "Namun kemudian"
  },
  AvgVideoCaption_149926_Content_68 = {
    Text = "Aku perlahan menyadari"
  },
  AvgVideoCaption_149926_Content_69 = {
    Text = "Setiap kali aku berbohong"
  },
  AvgVideoCaption_149926_Content_7 = {Text = "Kumohon"},
  AvgVideoCaption_149926_Content_70 = {
    Text = "Aku semakin lupa seperti apa diriku dulu"
  },
  AvgVideoCaption_149926_Content_71 = {
    Text = "Yang pertama terlupakan"
  },
  AvgVideoCaption_149926_Content_72 = {
    Text = "Adalah suara ayah memukul meja saat mabuk"
  },
  AvgVideoCaption_149926_Content_73 = {
    Text = "Lalu wajah ibu yang menangis"
  },
  AvgVideoCaption_149926_Content_74 = {
    Text = "Setelah itu"
  },
  AvgVideoCaption_149926_Content_75 = {
    Text = "Adalah namaku sendiri"
  },
  AvgVideoCaption_149926_Content_76 = {
    Text = "Aku pernah berpikir"
  },
  AvgVideoCaption_149926_Content_77 = {
    Text = "Apakah terus begini tidak baik-baik saja"
  },
  AvgVideoCaption_149926_Content_78 = {
    Text = "Tapi setiap kali aku baru saja hendak berpikir demikian"
  },
  AvgVideoCaption_149926_Content_79 = {
    Text = "Ia berbisik lembut di telingaku—"
  },
  AvgVideoCaption_149926_Content_8 = {
    Text = "Kasihanilah aku…"
  },
  AvgVideoCaption_149926_Content_80 = {
    Text = "『Kedinginan? Mau lebih hangat lagi?』"
  },
  AvgVideoCaption_149926_Content_81 = {
    Text = "Lalu aku pun"
  },
  AvgVideoCaption_149926_Content_82 = {
    Text = "mengucapkan satu kalimat lagi"
  },
  AvgVideoCaption_149926_Content_83 = {
    Text = "satu lagi, satu lagi"
  },
  AvgVideoCaption_149926_Content_84 = {
    Text = "satu lagi, kalimat demi kalimat"
  },
  AvgVideoCaption_149926_Content_85 = {
    Text = "Begitu mudah, begitu ringan"
  },
  AvgVideoCaption_149926_Content_86 = {
    Text = "mengalir begitu saja dari dalam salju"
  },
  AvgVideoCaption_149926_Content_87 = {
    Text = "namun hangat dan manis"
  },
  AvgVideoCaption_149926_Content_88 = {
    Text = "Siapakah aku ini,"
  },
  AvgVideoCaption_149926_Content_89 = {
    Text = "apakah aku adalah diriku sendiri?"
  },
  AvgVideoCaption_149926_Content_9 = {
    Text = "Sejak kecil aku tidak pernah disayangi"
  },
  AvgVideoCaption_149926_Content_90 = {
    Text = "Suara di bawah salju"
  },
  AvgVideoCaption_149926_Content_91 = {
    Text = "sebenarnya sejak awal"
  },
  AvgVideoCaption_149926_Content_92 = {
    Text = "adalah suaraku sendiri, bukan?"
  },
  AvgVideoCaption_149926_Content_93 = {
    Text = "Aduh, jangan lari dulu, Tuan"
  },
  AvgVideoCaption_149926_Content_94 = {
    Text = "sudah terlambat untuk lari, lho"
  },
  AvgVideoCaption_149926_Content_95 = {
    Text = "Tangan dan kakimu"
  },
  AvgVideoCaption_149926_Content_96 = {
    Text = "sudah membeku sejak tadi"
  },
  AvgVideoCaption_149926_Content_97 = {
    Text = "Perlu kami bantu menghangatkannya?"
  },
  AvgVideoCaption_149926_Content_98 = {
    Text = "Jangan menangis dong"
  },
  AvgVideoCaption_149926_Content_99 = {
    Text = "Aku sudah pernah mencoba"
  },
  AvgVideoCaption_18618_Content_1 = {
    Text = "Di kedalaman ruang rahasia, monster putih berdiri dengan tenang."
  },
  AvgVideoCaption_18619_Content_1 = {
    Text = "Kilauan liar perlahan memudar dari mata Lotan, digantikan oleh semacam warna kusam yang memancarkan cahaya perak."
  },
  AvgVideoCaption_18619_Content_2 = {
    Text = "Lotan yang telah kembali sadar tampak menderita sakit kepala yang hebat, memegang satu sisi dahinya dan menundukkan kepalanya."
  },
  AvgVideoCaption_18620_Content_1 = {
    Text = "Begitu ucapannya terdengar, semua keberadaan yang melampaui akal sehat lenyap dalam sekejap."
  },
  AvgVideoCaption_18621_Content_1 = {
    Text = "Dia mengangkat tangannya dan membersihkan sepotong kaca di depannya."
  },
  AvgVideoCaption_18622_Content_1 = {
    Text = "Sisa keemasan matahari terbenam menembus permukaan jam raksasa yang transparan di menara jam, dan menyelimuti tubuh gadis itu."
  },
  AvgVideoCaption_18623_Content_1 = {
    Text = "Sekali lagi, hanya diriku sendiri yang tersisa."
  },
  AvgVideoCaption_18624_Content_1 = {
    Text = "Sesaat kemudian, penampakan aneh itu memudar."
  },
  AvgVideoCaption_18625_Content_1 = {
    Text = "Di hadapan keberadaan-keberadaan besar dan misterius itu..."
  },
  AvgVideoCaption_18625_Content_10 = {
    Text = "Saat mendengar kata itu, suara berdengung keras disertai rasa sakit langsung menusuk ke dalam kedalaman otak."
  },
  AvgVideoCaption_18625_Content_11 = {
    Text = "Perut terasa seperti diaduk-aduk, bau menyengat dari muntah menghantam rongga hidung."
  },
  AvgVideoCaption_18625_Content_2 = {
    Text = "Manusia, sangat kecil."
  },
  AvgVideoCaption_18625_Content_3 = {
    Text = "Apakah ini mimpi?"
  },
  AvgVideoCaption_18625_Content_4 = {
    Text = "Rasa gelisah yang kuat muncul di dada."
  },
  AvgVideoCaption_18625_Content_5 = {
    Text = "—Universitas Mythag, Upacara Pemberian Kunci Perak—"
  },
  AvgVideoCaption_18625_Content_6 = {
    Text = "\"...Universitas Mythag adalah pelopor dalam melawan @2...\""
  },
  AvgVideoCaption_18625_Content_7 = {
    Text = "\"...menjadi Penyelidik di Universitas Mythag,\""
  },
  AvgVideoCaption_18625_Content_8 = {
    Text = "\"Berarti sisa hidup kalian akan bersama kematian dan kegilaan…\""
  },
  AvgVideoCaption_18625_Content_9 = {
    Text = "\"Sepuluh tahun terakhir, penyebaran@2…\""
  },
  AvgVideoCaption_18626_Content_1 = {
    Text = "Jika bisa memastikan keamanan semua orang saat ini, aku sudah merasa cukup puas."
  },
  AvgVideoCaption_18626_Content_10 = {
    Text = "Ujung jari terasa lembap, namun tidak ada sensasi nyata saat menyentuh."
  },
  AvgVideoCaption_18626_Content_11 = {
    Text = "Sebagian kecil realitas memudar di ujung jarinya, lenyap selamanya dari dunia."
  },
  AvgVideoCaption_18626_Content_2 = {
    Text = "Aku tidak akan dikuasai lagi."
  },
  AvgVideoCaption_18626_Content_3 = {
    Text = "Tidak akan memberikan kerusakan kepada siapa pun lagi."
  },
  AvgVideoCaption_18626_Content_4 = {
    Text = "Tidak akan membiarkan teman mati karena aku lagi."
  },
  AvgVideoCaption_18626_Content_5 = {
    Text = "Dengan suara lonceng sebagai penyamaran, Aigis entah bagaimana berhasil mendorong kaca yang seharusnya tersegel rapat dengan mudah."
  },
  AvgVideoCaption_18626_Content_6 = {
    Text = "Mintakan maaf untukku dan Jenkin."
  },
  AvgVideoCaption_18626_Content_7 = {
    Text = "Katakan padanya dari saya, bahwa kita akan selalu menjadi teman."
  },
  AvgVideoCaption_18626_Content_8 = {
    Text = "Aigis menutup matanya, merasa dirinya menjadi sangat ringan, sangat ringan. Di belakangnya, Ramona dengan cemas mengulurkan tangannya ke arah langit malam."
  },
  AvgVideoCaption_18626_Content_9 = {
    Text = "Menyentuh, memegang erat."
  },
  AvgVideoCaption_22146_Content_1 = {
    Text = "Bencana mengerikan telah datang"
  },
  AvgVideoCaption_22146_Content_2 = {
    Text = "\"Pelarutan\""
  },
  AvgVideoCaption_22146_Content_3 = {
    Text = "Itu melahap segalanya"
  },
  AvgVideoCaption_22146_Content_4 = {
    Text = "Bahkan memori pun tak terlepas dari cengkeramannya"
  },
  AvgVideoCaption_22146_Content_5 = {
    Text = "Setelah ratusan tahun, akhirnya kami menemukan terobosannya —"
  },
  AvgVideoCaption_22146_Content_6 = {Text = "\"Perak\""},
  AvgVideoCaption_22146_Content_7 = {
    Text = "Itu bisa membangun roh yang telah hilang"
  },
  AvgVideoCaption_22146_Content_8 = {
    Text = "Makhluk-makhluk ini adalah harapan terakhir kita."
  },
  AvgVideoCaption_22146_Content_9 = {
    Text = "Setidaknya, begitulah harapan kami…"
  },
  AvgVideoCaption_24281_Content_1 = {
    Text = "Akhirnya menyambut saat untuk mekar."
  },
  AvgVideoCaption_24724_Content_1 = {
    Text = "Jumlah kegagalan tidak menjadi masalah"
  },
  AvgVideoCaption_24724_Content_2 = {
    Text = "Tidak peduli berapa kali aku kembali, aku pasti akan menemukannya."
  },
  AvgVideoCaption_24724_Content_3 = {
    Text = "Menyelamatkan dunia ini"
  },
  AvgVideoCaption_24724_Content_4 = {
    Text = "Cara untuk menyelamatkanmu"
  },
  AvgVideoCaption_36151_Content_1 = {
    Text = "Keluar, keluar ada di sana…"
  },
  AvgVideoCaption_36151_Content_10 = {
    Text = "Dengarkan tuan kami!"
  },
  AvgVideoCaption_36151_Content_11 = {
    Text = "Kenapa harus mendengarkan!"
  },
  AvgVideoCaption_36151_Content_12 = {
    Text = "Kembali kepada Tuhanku"
  },
  AvgVideoCaption_36151_Content_13 = {
    Text = "Kenapa harus tunduk!"
  },
  AvgVideoCaption_36151_Content_14 = {
    Text = "Mengorbankan diri! Membentuk kembali Ranah dewa——"
  },
  AvgVideoCaption_36151_Content_15 = {
    Text = "Apa Ranah Dewa, apa dewa… apa hubungannya dengan aku!"
  },
  AvgVideoCaption_36151_Content_16 = {
    Text = "Mengorbankan diri! Kembalikan tuanku ——"
  },
  AvgVideoCaption_36151_Content_17 = {
    Text = "Pergi dari sini. Kita bersama-sama... pergi dari sini!"
  },
  AvgVideoCaption_36151_Content_2 = {
    Text = "Ibu Dewa, kenapa pergi?"
  },
  AvgVideoCaption_36151_Content_3 = {
    Text = "Jangan... aku tidak ingin menjadi Dewi."
  },
  AvgVideoCaption_36151_Content_4 = {
    Text = "Aku tidak ingin menjadi korban…"
  },
  AvgVideoCaption_36151_Content_5 = {
    Text = "Ranah dewa akan melahirkanmu"
  },
  AvgVideoCaption_36151_Content_6 = {
    Text = "Berapa jauh lagi? Berapa lama lagi?"
  },
  AvgVideoCaption_36151_Content_7 = {
    Text = "Saatnya Selaras——"
  },
  AvgVideoCaption_36151_Content_8 = {
    Text = "Apakah sudah... terlambat?"
  },
  AvgVideoCaption_36151_Content_9 = {
    Text = "Tapi... dengan alasan apa?!"
  },
  AvgVideoCaption_45044_Content_1 = {
    Text = "Wabah tak terlihat telah Kedatangan"
  },
  AvgVideoCaption_45044_Content_10 = {
    Text = "\"Apakah kamu akan membayar dengan Caro untuk kami?\""
  },
  AvgVideoCaption_45044_Content_11 = {
    Text = "\"Apakah kamu akan mengorbankan hidupmu untuk kami?\""
  },
  AvgVideoCaption_45044_Content_12 = {
    Text = "\"Bapa Surgawi menangis untuk kita, anak-anak-Nya.\""
  },
  AvgVideoCaption_45044_Content_13 = {
    Text = "\"Dia menginginkan kita yang terhormat menjadi wakil-Nya\""
  },
  AvgVideoCaption_45044_Content_14 = {
    Text = "\"Melenyapkan penderitaan dari bumi ini.\""
  },
  AvgVideoCaption_45044_Content_15 = {
    Text = "Aku adalah wakil dari Bapa Surgawi"
  },
  AvgVideoCaption_45044_Content_16 = {
    Text = "Akan berusaha sepenuhnya"
  },
  AvgVideoCaption_45044_Content_17 = {
    Text = "\"Mengapa, Uskup, mengapa hari ini tidak ada Berkat?\""
  },
  AvgVideoCaption_45044_Content_18 = {
    Text = "\"Mengapa kamu tidak melanjutkan? Mengapa tidak menyelamatkan kami!\""
  },
  AvgVideoCaption_45044_Content_19 = {
    Text = "\"Bagaimana mungkin kamu bisa merasa tidak berdaya?\""
  },
  AvgVideoCaption_45044_Content_2 = {
    Text = "Itu membawa kematian dan keputusasaan."
  },
  AvgVideoCaption_45044_Content_20 = {
    Text = "\"Kamu meninggalkan kami, membiarkan penderitaan menyebar!\""
  },
  AvgVideoCaption_45044_Content_21 = {
    Text = "\"Aku akan memberikan berkat, aku ingin hidup, aku ingin hidup!\""
  },
  AvgVideoCaption_45044_Content_22 = {
    Text = "\"Tidak cukup, tidak cukup, tidak cukup!\""
  },
  AvgVideoCaption_45044_Content_23 = {Text = "Hidupku"},
  AvgVideoCaption_45044_Content_24 = {
    Text = "Semua berusaha membebaskan kalian dari penderitaan."
  },
  AvgVideoCaption_45044_Content_25 = {
    Text = "Penggembala Jiwa"
  },
  AvgVideoCaption_45044_Content_26 = {
    Text = "Segalanya, demi kesejahteraan kalian."
  },
  AvgVideoCaption_45044_Content_3 = {
    Text = "Anak-anak Sang Pencipta"
  },
  AvgVideoCaption_45044_Content_4 = {
    Text = "Saudara-saudaraku"
  },
  AvgVideoCaption_45044_Content_5 = {
    Text = "Penderitaan kalian, aku merasakannya seolah-olah itu adalah penderitaanku sendiri."
  },
  AvgVideoCaption_45044_Content_6 = {
    Text = "Saya bersedia mengorbankan segalanya"
  },
  AvgVideoCaption_45044_Content_7 = {
    Text = "Hanya supaya kalian tidak merasakan sakit lagi"
  },
  AvgVideoCaption_45044_Content_8 = {
    Text = "\"Uskup Salvador, apakah hari ini Anda akan memberikan Berkat kepada kami?\""
  },
  AvgVideoCaption_45044_Content_9 = {
    Text = "\"Uskup Salvador, apakah Anda akan menyelamatkan kami?\""
  },
  AvgVideoCaption_50040_Content_1 = {
    Text = "Berkembang biak adalah bagian dari padang pasir primitif ini."
  },
  AvgVideoCaption_50040_Content_10 = {
    Text = "Bersatu dengan saya secara sempurna"
  },
  AvgVideoCaption_50040_Content_11 = {
    Text = "Melahirkan anak denganku"
  },
  AvgVideoCaption_50040_Content_12 = {
    Text = "Mari darah dan benih kita bersatu."
  },
  AvgVideoCaption_50040_Content_13 = {
    Text = "Tenggelamkan lautan pasir ini!"
  },
  AvgVideoCaption_50040_Content_14 = {
    Text = "Serahkan daging dan darahmu"
  },
  AvgVideoCaption_50040_Content_15 = {
    Text = "Dengan batang Pohon ibu"
  },
  AvgVideoCaption_50040_Content_16 = {
    Text = "Serahkan darahmu"
  },
  AvgVideoCaption_50040_Content_17 = {
    Text = "Menjadi sumber aliran Sungai Suci"
  },
  AvgVideoCaption_50040_Content_18 = {
    Text = "Menyuburkan Aran yang baru!"
  },
  AvgVideoCaption_50040_Content_19 = {
    Text = "Pembiakan, adalah saat kedatangan hari kiamat yang hitam."
  },
  AvgVideoCaption_50040_Content_2 = {
    Text = "Cara satu-satunya untuk bertahan hidup"
  },
  AvgVideoCaption_50040_Content_20 = {
    Text = "Cara satu-satunya untuk bertahan hidup"
  },
  AvgVideoCaption_50040_Content_21 = {Text = "Kamu harus"},
  AvgVideoCaption_50040_Content_22 = {
    Text = "Mau bergabung?"
  },
  AvgVideoCaption_50040_Content_23 = {
    Text = "Ibu dari Sepuluh Ribu Anak"
  },
  AvgVideoCaption_50040_Content_3 = {
    Text = "Mau bergabung?"
  },
  AvgVideoCaption_50040_Content_4 = {Text = "Mari"},
  AvgVideoCaption_50040_Content_5 = {
    Text = "Saya sudah tidak bisa bertahan lagi"
  },
  AvgVideoCaption_50040_Content_6 = {
    Text = "Ayo, kemarilah"
  },
  AvgVideoCaption_50040_Content_7 = {
    Text = "Mendekatlah padaku"
  },
  AvgVideoCaption_50040_Content_8 = {Text = "Sentuh aku"},
  AvgVideoCaption_50040_Content_9 = {
    Text = "Masuk ke dalam diriku"
  },
  AvgVideoCaption_56358_Content_1 = {
    Text = "Hujan adalah perpisahan awan dengan langit"
  },
  AvgVideoCaption_56358_Content_10 = {
    Text = "Kamu adalah musim semi"
  },
  AvgVideoCaption_56358_Content_11 = {
    Text = "Berikan aku sebuah lagu"
  },
  AvgVideoCaption_56358_Content_12 = {
    Text = "Puisi yang dipersembahkan kepada taman di musim semi"
  },
  AvgVideoCaption_56358_Content_13 = {
    Text = "Dalam hidup kita yang sunyi dan tandus, mawar merah bersemayam dengan indah."
  },
  AvgVideoCaption_56358_Content_14 = {
    Text = "\"Pegang tanganku,\" katamu"
  },
  AvgVideoCaption_56358_Content_15 = {
    Text = "Ketika ujung jari kita bersentuhan, kau akan memberiku sebuah taman."
  },
  AvgVideoCaption_56358_Content_16 = {
    Text = "Di kerajaan kecil kami"
  },
  AvgVideoCaption_56358_Content_17 = {
    Text = "Kamu akan menanggung semua duri untukku"
  },
  AvgVideoCaption_56358_Content_18 = {
    Text = "Terimalah puisi ini, sebuah persembahan musim semi untuk taman."
  },
  AvgVideoCaption_56358_Content_19 = {
    Text = "Dalam hidup kita yang sunyi dan tandus, mawar merah bersemayam dengan indah."
  },
  AvgVideoCaption_56358_Content_2 = {
    Text = "Ketika kita bertemu lagi, aku akan membawa seikat bunga."
  },
  AvgVideoCaption_56358_Content_20 = {
    Text = "Hujan adalah perpisahan musim semi dengan taman"
  },
  AvgVideoCaption_56358_Content_21 = {
    Text = "Ketika kita bertemu kembali"
  },
  AvgVideoCaption_56358_Content_22 = {
    Text = "Apakah kamu akan membawa karangan bunga?"
  },
  AvgVideoCaption_56358_Content_23 = {
    Text = "Buket bunga untuk musim semi"
  },
  AvgVideoCaption_56358_Content_24 = {
    Text = "Pertukaran denganku, syair terakhir"
  },
  AvgVideoCaption_56358_Content_3 = {
    Text = "Denganmu melakukan pertukaran, kitab puisi pertama"
  },
  AvgVideoCaption_56358_Content_4 = {
    Text = "Peganglah tangan saya"
  },
  AvgVideoCaption_56358_Content_5 = {
    Text = "Ketika ujung jari saling bersentuhan"
  },
  AvgVideoCaption_56358_Content_6 = {
    Text = "Aku akan memberikanmu sebuah taman."
  },
  AvgVideoCaption_56358_Content_7 = {
    Text = "Di kerajaan kecil kami"
  },
  AvgVideoCaption_56358_Content_8 = {
    Text = "Aku akan menopang semua duri untukmu"
  },
  AvgVideoCaption_56358_Content_9 = {
    Text = "Horla, aku adalah taman, dan kamu——"
  },
  AvgVideoCaption_60917_Content_1 = {
    Text = "Orang yang menguasai segalanya"
  },
  AvgVideoCaption_60917_Content_10 = {
    Text = "Para pemain telah tampil semuanya"
  },
  AvgVideoCaption_60917_Content_11 = {
    Text = "Biarkan suara-suara yang tidak selaras itu, lenyap dalam keheningan."
  },
  AvgVideoCaption_60917_Content_12 = {
    Text = "Biarkan semua not berdansa di sepanjang jejak tongkat musik"
  },
  AvgVideoCaption_60917_Content_13 = {
    Text = "Semua ini, hanya demi harmoni yang sempurna"
  },
  AvgVideoCaption_60917_Content_14 = {
    Text = "Sekarang, biarkan dirimu terpesona olehnya."
  },
  AvgVideoCaption_60917_Content_15 = {
    Text = "Tenggelam dalam simfoni agung ini —"
  },
  AvgVideoCaption_60917_Content_16 = {
    Text = "A minor: Symphony Terakhir"
  },
  AvgVideoCaption_60917_Content_17 = {
    Text = "Ketika tepuk tangan di teater mereda"
  },
  AvgVideoCaption_60917_Content_18 = {
    Text = "Pertunjukan yang sebenarnya"
  },
  AvgVideoCaption_60917_Content_19 = {
    Text = "Akan segera dimulai"
  },
  AvgVideoCaption_60917_Content_2 = {
    Text = "Baru bisa menguasai musik"
  },
  AvgVideoCaption_60917_Content_3 = {
    Text = "Pembukaan, bangkit"
  },
  AvgVideoCaption_60917_Content_4 = {
    Text = "Tempat tongkat musik menunjuk"
  },
  AvgVideoCaption_60917_Content_5 = {
    Text = "Segala sesuatu berbunyi di sini"
  },
  AvgVideoCaption_60917_Content_6 = {
    Text = "Biola, protagonis penuh kesedihan di atas panggung"
  },
  AvgVideoCaption_60917_Content_7 = {
    Text = "Tenggelam di sini, atau memperoleh kelahiran baru"
  },
  AvgVideoCaption_60917_Content_8 = {
    Text = "Musik tiup, lawan yang tangguh, harmoni yang berbahaya"
  },
  AvgVideoCaption_60917_Content_9 = {
    Text = "Musik perkusi, jeda tak terduga, konser penuh kejutan"
  },
  AvgVideoCaption_70276_Content_1 = {
    Text = "Kami adalah orang-orang tanpa nama."
  },
  AvgVideoCaption_70276_Content_10 = {
    Text = "Panggil namaku meskipun pita suaraku kering."
  },
  AvgVideoCaption_70276_Content_11 = {
    Text = "Masih mencari bukti keberadaan."
  },
  AvgVideoCaption_70276_Content_12 = {
    Text = "Panggil namaku, meskipun dunia memudar."
  },
  AvgVideoCaption_70276_Content_13 = {
    Text = "Masih harus erat memegang cahaya yang berkilau sesaat itu."
  },
  AvgVideoCaption_70276_Content_14 = {
    Text = "Panggil namaku, meskipun saat perpisahan sudah tiba."
  },
  AvgVideoCaption_70276_Content_15 = {
    Text = "Masih percaya pada makna mencari dan melangkah maju"
  },
  AvgVideoCaption_70276_Content_16 = {
    Text = "Panggil namaku, meskipun waktu terhenti."
  },
  AvgVideoCaption_70276_Content_17 = {
    Text = "Masih harus membangun harapan abadi yang tak pernah padam"
  },
  AvgVideoCaption_70276_Content_18 = {
    Text = "Bolehkah aku memanggilmu, meskipun dunia telah lenyap?"
  },
  AvgVideoCaption_70276_Content_19 = {
    Text = "Masih harus erat memegang cahaya yang berkilau sesaat itu."
  },
  AvgVideoCaption_70276_Content_2 = {
    Text = "Dari Dunia yang Terlupakan"
  },
  AvgVideoCaption_70276_Content_20 = {
    Text = "Semoga Kunci Perak menuntun kita"
  },
  AvgVideoCaption_70276_Content_21 = {
    Text = "Semoga Kunci Perak menuntun kita"
  },
  AvgVideoCaption_70276_Content_3 = {
    Text = "Mengayuh dayung dalam keheningan"
  },
  AvgVideoCaption_70276_Content_4 = {
    Text = "Menatap ke arah langit yang jauh dan tak tercapai"
  },
  AvgVideoCaption_70276_Content_5 = {
    Text = "Bintang pagi perak dari Qiming ditelan oleh gelombang hitam"
  },
  AvgVideoCaption_70276_Content_6 = {
    Text = "Catatan yang samar, wajah yang pudar"
  },
  AvgVideoCaption_70276_Content_7 = {
    Text = "Berusaha keras untuk menangkap, tetapi tidak bisa menahan"
  },
  AvgVideoCaption_70276_Content_8 = {
    Text = "Di tengah malam kutub yang perlahan mencair, ungkapkan Keinginan terakhir"
  },
  AvgVideoCaption_70276_Content_9 = {
    Text = "Sebelum fajar yang dilupakan"
  },
  AvgVideoCaption_72086_Content_1 = {
    Text = "Angkat kepalamu dan pandanglah ke atas"
  },
  AvgVideoCaption_72086_Content_10 = {
    Text = "Ilusi bukanlah niat aslinya"
  },
  AvgVideoCaption_72086_Content_11 = {
    Text = "Kegilaan akan pengetahuan mendorongnya untuk secara pribadi mengaktifkan mesin kehancuran."
  },
  AvgVideoCaption_72086_Content_12 = {
    Text = "Dia adalah pemandu di Hutan Pikiran"
  },
  AvgVideoCaption_72086_Content_13 = {
    Text = "Di bawah bandul roh yang terus-menerus bergoyang"
  },
  AvgVideoCaption_72086_Content_14 = {
    Text = "Jiwa yang menderita memuntahkan isi perut berwarna hitam pekat dari dalam."
  },
  AvgVideoCaption_72086_Content_15 = {
    Text = "Estetika makhluk hidup telah mengalami pembusukan"
  },
  AvgVideoCaption_72086_Content_16 = {
    Text = "Di bawah takdir pisau dan talenan, dia menari bersama yang telah tiada."
  },
  AvgVideoCaption_72086_Content_17 = {
    Text = "Anak keturunan dewa, juga merupakan ibu dari dewa"
  },
  AvgVideoCaption_72086_Content_18 = {
    Text = "Untuk hari kelahiran raja, persembahkan orang yang merangkak dengan Caro."
  },
  AvgVideoCaption_72086_Content_19 = {
    Text = "Menikmati kemuliaan tanpa batas"
  },
  AvgVideoCaption_72086_Content_2 = {
    Text = "Saat bintang-bintang berada dalam posisi selaras akan segera tiba"
  },
  AvgVideoCaption_72086_Content_20 = {
    Text = "Ribuan gletser, dataran salju yang luas dan berselimut putih"
  },
  AvgVideoCaption_72086_Content_21 = {
    Text = "Dia adalah warna putih paling murni."
  },
  AvgVideoCaption_72086_Content_22 = {
    Text = "...Apakah kamu akan mempercayai omong kosong seperti itu?"
  },
  AvgVideoCaption_72086_Content_23 = {
    Text = "Bernyanyilah, ratapkanlah, dan anyamlah jaring laba-laba dengan lidahmu"
  },
  AvgVideoCaption_72086_Content_24 = {
    Text = "Di atas alat tenunnya"
  },
  AvgVideoCaption_72086_Content_25 = {
    Text = "Setiap orang yang terhubung oleh Tautan"
  },
  AvgVideoCaption_72086_Content_26 = {
    Text = "Semua adalah boneka takdir"
  },
  AvgVideoCaption_72086_Content_27 = {
    Text = "Menyelesaikan misi di sini"
  },
  AvgVideoCaption_72086_Content_28 = {
    Text = "Kembali ke dunia semula"
  },
  AvgVideoCaption_72086_Content_29 = {
    Text = "Tidur tanpa alasan telah berakhir"
  },
  AvgVideoCaption_72086_Content_3 = {
    Text = "Dari dunia yang telah menyambut \"akhir\""
  },
  AvgVideoCaption_72086_Content_30 = {
    Text = "Di bawah pemerintahan Yu, Lemuria ditetapkan sebagai tanah kerajaan abadi yang tak terhapuskan."
  },
  AvgVideoCaption_72086_Content_31 = {
    Text = "Angkat kepalamu dan pandanglah ke atas"
  },
  AvgVideoCaption_72086_Content_32 = {
    Text = "Saat bintang-bintang berada dalam posisi selaras"
  },
  AvgVideoCaption_72086_Content_4 = {
    Text = "Oh, sang\"tamu\"yang datang dari jauh"
  },
  AvgVideoCaption_72086_Content_5 = {
    Text = "Makhluk yang bodoh telah lenyap menjadi abu."
  },
  AvgVideoCaption_72086_Content_6 = {
    Text = "Maka dengan kecerdasan kalian"
  },
  AvgVideoCaption_72086_Content_7 = {
    Text = "Menyuburkan jalur keberlangsungan hidup"
  },
  AvgVideoCaption_72086_Content_8 = {
    Text = "Untuk kedatangan Raja Dewa yang sejati"
  },
  AvgVideoCaption_72086_Content_9 = {
    Text = "Persembahkan seluruh spiritualitas dan mimpi"
  },
  AvgVideoCaption_76210_Content_1 = {
    Text = "Kerang, nyalakan mesin piringan hitam."
  },
  AvgVideoCaption_76210_Content_10 = {
    Text = "Strategi terbaik saat ini adalah saya melakukan operasi pada tangki otak ini untuk memodifikasi antarmukanya dengan cairan nutrisi."
  },
  AvgVideoCaption_76210_Content_11 = {
    Text = "Meningkatkan aktivitas otak secara paksa, sehingga mengaktifkan kesadaran Penjaga."
  },
  AvgVideoCaption_76210_Content_12 = {
    Text = "Anak anjing yang tercinta, jangan takut, ya."
  },
  AvgVideoCaption_76210_Content_13 = {
    Text = "Baiklah, semua instrumen sudah siap, keluarlah."
  },
  AvgVideoCaption_76210_Content_14 = {
    Text = "Benar-benar indah alur pikirannya"
  },
  AvgVideoCaption_76210_Content_15 = {
    Text = "Menghilangkan kotoran berlebih..."
  },
  AvgVideoCaption_76210_Content_16 = {
    Text = "Memulihkan kemurnian korteks otak"
  },
  AvgVideoCaption_76210_Content_17 = {Text = "Di sini..."},
  AvgVideoCaption_76210_Content_18 = {
    Text = "Nukleus Kaudatus"
  },
  AvgVideoCaption_76210_Content_19 = {
    Text = "Nukleus berbentuk kacang"
  },
  AvgVideoCaption_76210_Content_2 = {
    Text = "Apakah kesadaran-Nya masih belum bisa terhubung dengan normal ke tangki otak?"
  },
  AvgVideoCaption_76210_Content_20 = {
    Text = "Inti Almond"
  },
  AvgVideoCaption_76210_Content_21 = {
    Text = "Nukleus layar..."
  },
  AvgVideoCaption_76210_Content_22 = {
    Text = "Semua fungsi beroperasi dengan normal."
  },
  AvgVideoCaption_76210_Content_23 = {
    Text = "Anak anjing yang tercinta, aku akan berhati-hati melindungi otakmu."
  },
  AvgVideoCaption_76210_Content_24 = {
    Text = "Jika hipokampus rusak, menyebabkan hilangnya memori berharga antara kamu dan aku, itu akan sangat disayangkan."
  },
  AvgVideoCaption_76210_Content_25 = {
    Text = "Aku masih ingat hari pertama kali bertemu denganmu, kamu mengira aku adalah Boneka."
  },
  AvgVideoCaption_76210_Content_26 = {
    Text = "Kamu menatapku, suaramu bergetar saat memanggilku \"Profesor Boneka\""
  },
  AvgVideoCaption_76210_Content_27 = {
    Text = "Saya mengira saya sangat berwibawa, ternyata kamu takut dia akan memarahimu karena laporan lapangan belum selesai."
  },
  AvgVideoCaption_76210_Content_28 = {
    Text = "Memori ini, berada di bagian mana dari otakmu?"
  },
  AvgVideoCaption_76210_Content_29 = {
    Text = "Apakah ini tempatnya?"
  },
  AvgVideoCaption_76210_Content_3 = {
    Text = "Hanya penyambungan antar dimensi, apakah itu benar-benar begitu sulit bagimu?"
  },
  AvgVideoCaption_76210_Content_30 = {
    Text = "... atau di sini?"
  },
  AvgVideoCaption_76210_Content_31 = {
    Text = "Haa, tidak masalah. Di mana pun tidak apa-apa."
  },
  AvgVideoCaption_76210_Content_32 = {
    Text = "Karena, ada hal yang lebih penting."
  },
  AvgVideoCaption_76210_Content_33 = {
    Text = "Pada akhir hari itu, kau dan profesor dari Mythag, dengan tangan kalian sendiri, menyegelku di bawah tanah yang gelap gulita."
  },
  AvgVideoCaption_76210_Content_34 = {
    Text = "Keempat anggota tubuh terikat oleh alat pengikat, ruang gerak sangat sempit hingga bahkan memutar badan pun terasa sesak…"
  },
  AvgVideoCaption_76210_Content_35 = {
    Text = "Meskipun kamu lupa……"
  },
  AvgVideoCaption_76210_Content_36 = {
    Text = "Aku takkan pernah, pernah melupakannya!"
  },
  AvgVideoCaption_76210_Content_37 = {
    Text = "Di dalam neraka tanpa akhir, teruslah tenggelam selamanya!"
  },
  AvgVideoCaption_76210_Content_38 = {
    Text = "Tidak perlu khawatir, aku sudah kembali pulih."
  },
  AvgVideoCaption_76210_Content_39 = {
    Text = "Maaf ya, anak anjing Mythag"
  },
  AvgVideoCaption_76210_Content_4 = {
    Text = "Awalnya mengira bahwa ▼▼ Teknologi seumur hidup didedikasikan untuk Penelitian transfer kesadaran, masalah kecil ini pasti bisa diselesaikan."
  },
  AvgVideoCaption_76210_Content_40 = {
    Text = "Aku tidak seharusnya begitu terbawa emosi."
  },
  AvgVideoCaption_76210_Content_41 = {
    Text = "Selanjutnya, aku akan membelah batang otakmu."
  },
  AvgVideoCaption_76210_Content_42 = {
    Text = "Menyentuh hipotalamus Anda, menyesuaikan otak tengah Anda..."
  },
  AvgVideoCaption_76210_Content_43 = {
    Text = "Astaga, sarafmu sedang berkedut."
  },
  AvgVideoCaption_76210_Content_44 = {
    Text = "Terlalu kasihan, haruskah aku menyuntikkan beberapa obat bius?"
  },
  AvgVideoCaption_76210_Content_45 = {
    Text = "Sayangnya, sekarang sudah terlambat."
  },
  AvgVideoCaption_76210_Content_46 = {
    Text = "Bertahanlah sebentar lagi, segera, segera akan——"
  },
  AvgVideoCaption_76210_Content_47 = {
    Text = "Hm hm, biarkan aku lihat."
  },
  AvgVideoCaption_76210_Content_48 = {Text = "Di mana?"},
  AvgVideoCaption_76210_Content_49 = {Text = "Ditemukan"},
  AvgVideoCaption_76210_Content_5 = {
    Text = "Sepertinya aku terlalu memandangmu tinggi."
  },
  AvgVideoCaption_76210_Content_50 = {
    Text = "Hmm, untuk mengembalikan aktivitasnya, diperlukan sedikit rangsangan kejut listrik."
  },
  AvgVideoCaption_76210_Content_51 = {
    Text = "Aku akan mengambil senjata kejut listrik, kamu hati-hati ya."
  },
  AvgVideoCaption_76210_Content_52 = {
    Text = "Lama menunggu, makhluk kecil yang malang."
  },
  AvgVideoCaption_76210_Content_53 = {
    Text = "Aku akan membuatmu merasakannya dengan baik..."
  },
  AvgVideoCaption_76210_Content_54 = {
    Text = "Seperti aku, dalam dan kental... hitam seperti tinta..."
  },
  AvgVideoCaption_76210_Content_55 = {
    Text = "Sekarang, mulailah dari level terendah."
  },
  AvgVideoCaption_76210_Content_56 = {
    Text = "Meskipun saya lebih mengagungkan kematian yang efisien dan datang dalam sekejap."
  },
  AvgVideoCaption_76210_Content_57 = {
    Text = "Tetapi sekarang adalah saatnya untuk benar-benar \"menikmati\", aku tidak akan melewatkannya."
  },
  AvgVideoCaption_76210_Content_58 = {
    Text = "Pada hari pertama saya mendapatkan Tablet, saya pernah mengira itu hanyalah omong kosong belaka."
  },
  AvgVideoCaption_76210_Content_59 = {
    Text = "Namun, saya hanya membaca baris pertamanya."
  },
  AvgVideoCaption_76210_Content_6 = {
    Text = "Tidak ada pilihan lain, aku akan melakukannya sendiri."
  },
  AvgVideoCaption_76210_Content_60 = {
    Text = "Tidak... separuh jalan"
  },
  AvgVideoCaption_76210_Content_61 = {
    Text = "Saya segera menyadari, itu pasti barang asli."
  },
  AvgVideoCaption_76210_Content_62 = {
    Text = "Perasaan euforia menyelimuti saya"
  },
  AvgVideoCaption_76210_Content_63 = {
    Text = "Aku akan menggambarkan perasaan seperti itu kepadamu. Persis seperti yang kamu rasakan saat ini."
  },
  AvgVideoCaption_76210_Content_64 = {
    Text = "Hampir tak terasa, dari entah mana, kelumpuhan yang ringan."
  },
  AvgVideoCaption_76210_Content_65 = {
    Text = "Saya tidak merasakan tanda-tanda krisis, bahkan merasa sedikit nyaman…"
  },
  AvgVideoCaption_76210_Content_66 = {
    Text = "Tentu saja! Kebenaran dunia, jawaban ultimat yang kucari mungkin sudah ada di depan mata."
  },
  AvgVideoCaption_76210_Content_67 = {
    Text = "Sama seperti tergoda oleh madu, tanpa sadar aku membaca dengan penuh semangat dan serakah."
  },
  AvgVideoCaption_76210_Content_68 = {
    Text = "Melangkah demi langkah menuju jebakan terakhir itu…"
  },
  AvgVideoCaption_76210_Content_69 = {
    Text = "Saya terjebak dalam sebuah jebakan"
  },
  AvgVideoCaption_76210_Content_7 = {
    Text = "Anak anjing Mythag, ini adalah kehormatan bagi kamu."
  },
  AvgVideoCaption_76210_Content_70 = {
    Text = "Sebuah jebakan yang dibuat khusus untukku, untuk sang jenius sombong dan munafik ini!"
  },
  AvgVideoCaption_76210_Content_71 = {
    Text = "Ya! Tepat di tengah Tablet, Jebakan besar sudah menunggu lama!"
  },
  AvgVideoCaption_76210_Content_72 = {
    Text = "Saya melangkah maju, satu per satu, hampir menangis kebahagiaan!"
  },
  AvgVideoCaption_76210_Content_73 = {
    Text = "Ketika saya menyadari apa yang saya baca, semuanya sudah terlambat!"
  },
  AvgVideoCaption_76210_Content_74 = {
    Text = "Aku mengetahui segalanya! Aku mengetahui jawabannya! Aku mengetahui▼▼!!"
  },
  AvgVideoCaption_76210_Content_75 = {
    Text = "Apakah kamu merasakannya?"
  },
  AvgVideoCaption_76210_Content_76 = {
    Text = "Rasa sakit yang menusuk tulang ini, keputusasaan yang tak tertahankan!"
  },
  AvgVideoCaption_76210_Content_77 = {
    Text = "Kegilaan yang mencekam, keputusasaan hitam pekat!"
  },
  AvgVideoCaption_76210_Content_78 = {
    Text = "Maafkan aku, Anak anjing Mythag, aku tidak bisa mengendalikan emosiku lagi."
  },
  AvgVideoCaption_76210_Content_79 = {
    Text = "Namun, jangan khawatir. Meskipun tekniknya agak kasar, tingkat aktivitas dasarnya pasti sudah memenuhi standar."
  },
  AvgVideoCaption_76210_Content_8 = {
    Text = "Masalah spesifik sudah diketahui, aktivitas tangki otak yang kamu pilih tidak cukup untuk menopang kesadaran Penjaga Mythag."
  },
  AvgVideoCaption_76210_Content_80 = {
    Text = "Saya akan segera membantu Anda memasang sensor ini."
  },
  AvgVideoCaption_76210_Content_81 = {
    Text = "Tidak lama lagi, kamu akan segera dilahirkan ke dunia ini."
  },
  AvgVideoCaption_76210_Content_82 = {
    Text = "Selanjutnya, tinggal menunggu saat kamu bangun, dan bagaimana kamu akan menghadapi penampilanmu sendiri."
  },
  AvgVideoCaption_76210_Content_83 = {
    Text = "Saya menantikan kedatangan hari itu."
  },
  AvgVideoCaption_76210_Content_9 = {
    Text = "Namun, pemindahan ulang memiliki risiko kehilangan kesadaran yang lebih tinggi."
  },
  AvgVideoCaption_81062_Content_1 = {
    Text = "Sayang, silakan ikut saya"
  },
  AvgVideoCaption_81062_Content_10 = {
    Text = "Daun-daun yang jatuh berkutik di bawah kakimu"
  },
  AvgVideoCaption_81062_Content_11 = {
    Text = "Apakah napasmu lebih ringan daripada tiga detik yang lalu?"
  },
  AvgVideoCaption_81062_Content_12 = {
    Text = "Mendongak melihat... sebuah pondok hutan muncul di depan Anda"
  },
  AvgVideoCaption_81062_Content_13 = {
    Text = "Sekarang, silakan naik ke tangga yang berderit"
  },
  AvgVideoCaption_81062_Content_14 = {
    Text = "Dorong pintu kayu yang familiar"
  },
  AvgVideoCaption_81062_Content_15 = {
    Text = "Dengarkan, suara api beringas di perapia"
  },
  AvgVideoCaption_81062_Content_16 = {
    Text = "Karpet bergaya Persia"
  },
  AvgVideoCaption_81062_Content_17 = {
    Text = "Sofa beludru merah yang gelap merah"
  },
  AvgVideoCaption_81062_Content_18 = {
    Text = "Gelashina yang terbalik dan anggur merah yang tumpah"
  },
  AvgVideoCaption_81062_Content_19 = {
    Text = "Persis sama dengan ingatanmu"
  },
  AvgVideoCaption_81062_Content_2 = {
    Text = "Silakan duduk di sofa di seberang sana"
  },
  AvgVideoCaption_81062_Content_20 = {
    Text = "Pikirkan lagi"
  },
  AvgVideoCaption_81062_Content_21 = {
    Text = "Apakah sofa itu benar-benar kosong?"
  },
  AvgVideoCaption_81062_Content_22 = {
    Text = "Apakah yang mengotori karpet Persia itu benar-benar anggur merah sebelum makan?"
  },
  AvgVideoCaption_81062_Content_23 = {
    Text = "Ssshh... jangan terburu-buru, dan tidak perlu mencoba melarikan diri."
  },
  AvgVideoCaption_81062_Content_24 = {
    Text = "Keempat anggota tubuhmu sudah lemas dan tidak bisa bergerak lagi"
  },
  AvgVideoCaption_81062_Content_25 = {
    Text = "Sepenuh hati, dengarkan aku… rasakan dengan baik"
  },
  AvgVideoCaption_81062_Content_26 = {
    Text = "Apakah sendi ketiga tulang belakang mulai gatal?"
  },
  AvgVideoCaption_81062_Content_27 = {
    Text = "Sepertinya ingatanmu telah kembali"
  },
  AvgVideoCaption_81062_Content_28 = {
    Text = "Mayat yang membusuk terletak di sofa"
  },
  AvgVideoCaption_81062_Content_29 = {
    Text = "Bukankah itu merupakan bapakmu yang terhormat dan disayangi?"
  },
  AvgVideoCaption_81062_Content_3 = {
    Text = "Apakah suhu perapian cukup nyaman?"
  },
  AvgVideoCaption_81062_Content_30 = {
    Text = "Apakah kamu sudah lupa? Mungkin kamu sudah lupa?"
  },
  AvgVideoCaption_81062_Content_31 = {
    Text = "Tidak, Anda sama sekali tidak lupa......"
  },
  AvgVideoCaption_81062_Content_32 = {
    Text = "Hanya, kamu di sini dengan sebuah kotak rahasia"
  },
  AvgVideoCaption_81062_Content_33 = {
    Text = "Menguburnya dengan debu"
  },
  AvgVideoCaption_81062_Content_34 = {
    Text = "Otak setia ini dalam dua puluh tujuh tahun terakhir"
  },
  AvgVideoCaption_81062_Content_35 = {
    Text = "Sama sekali tidak mengizinkan wajah asli Anda terungkap sedikit pun"
  },
  AvgVideoCaption_81062_Content_36 = {
    Text = "Sungguh mengagumkan"
  },
  AvgVideoCaption_81062_Content_37 = {
    Text = "Apa sebenarnya yang membelenggu Anda?"
  },
  AvgVideoCaption_81062_Content_38 = {
    Text = "Mengungkapkan teriakan dalam dirimu"
  },
  AvgVideoCaption_81062_Content_39 = {
    Text = "Ungkapkan hasratmu, keinginanmu"
  },
  AvgVideoCaption_81062_Content_4 = {
    Text = "Apakah jam ini dan sofa beludru merah membuatmu merasa familiar?"
  },
  AvgVideoCaption_81062_Content_40 = {
    Text = "\"Kami\" akan menerima segalanya tentangmu..."
  },
  AvgVideoCaption_81062_Content_41 = {
    Text = "Moralitas hanyalah benang pancing berkualitas rendah yang dijahit manusia di antara sinapsis saraf"
  },
  AvgVideoCaption_81062_Content_42 = {
    Text = "Sekarang mari kita dengan lembut... cabut... kait pancing dari tubuh almond... keluar..."
  },
  AvgVideoCaption_81062_Content_43 = {
    Text = "Ceritakan padaku, sahabat tersayang……"
  },
  AvgVideoCaption_81062_Content_44 = {
    Text = "Untuk kebebasan...... dan untuk kenikmatan yang dibuka sejak saat itu"
  },
  AvgVideoCaption_81062_Content_45 = {
    Text = "Apa saja yang telah kamu lakukan?"
  },
  AvgVideoCaption_81062_Content_46 = {
    Text = "Ketika kamu berusia tujuh tahun, memadamkan lilin di ruang bawah tanah selama tiga puluh detik"
  },
  AvgVideoCaption_81062_Content_47 = {
    Text = "Apa yang sebenarnya ditakuti?"
  },
  AvgVideoCaption_81062_Content_48 = {
    Text = "Apakah itu suara langkah kaki dari luar pintu?"
  },
  AvgVideoCaption_81062_Content_49 = {
    Text = "Apakah itu senyuman yang akan mekar dari dirimu?"
  },
  AvgVideoCaption_81062_Content_5 = {
    Text = "Tentu saja, membuat pasien merasa tenang adalah prinsip kami"
  },
  AvgVideoCaption_81062_Content_50 = {
    Text = "Insiden tenggelam yang Anda sebut \"kecelakaan\"..."
  },
  AvgVideoCaption_81062_Content_51 = {
    Text = "Di dalam riak terakhir perjuangan si tenggelam"
  },
  AvgVideoCaption_81062_Content_52 = {
    Text = "Menggambarkan sudut bibir Anda yang sedang menyanyi?"
  },
  AvgVideoCaption_81062_Content_53 = {
    Text = "Jangan melawan, tetap tenang……"
  },
  AvgVideoCaption_81062_Content_54 = {
    Text = "Kamu tidak ingin tahu ke mana perginya tuan yang berjuang sebelumnya"
  },
  AvgVideoCaption_81062_Content_55 = {
    Text = "Namun, mawar di halaman belakang gereja tahun ini mekar dengan sangat indah, bukan?"
  },
  AvgVideoCaption_81062_Content_56 = {Text = "Anak baik"},
  AvgVideoCaption_81062_Content_57 = {
    Text = "Sekarang, serahkan tanganmu padaku"
  },
  AvgVideoCaption_81062_Content_58 = {
    Text = "Ya, diletakkan di telapak tanganku..."
  },
  AvgVideoCaption_81062_Content_59 = {
    Text = "Perhatikan baik-baik"
  },
  AvgVideoCaption_81062_Content_6 = {
    Text = "Sekarang, silakan lewati pendulum, tatap mataku"
  },
  AvgVideoCaption_81062_Content_60 = {
    Text = "Apakah ini masih bisa disebut tangan?"
  },
  AvgVideoCaption_81062_Content_61 = {
    Text = "Kitin sedang tumbuh"
  },
  AvgVideoCaption_81062_Content_62 = {
    Text = "Cangkang akan menutupi tubuh yang lemah, lembut, dan tak berdaya..."
  },
  AvgVideoCaption_81062_Content_63 = {
    Text = "Tidak perlu mencoba berteriak"
  },
  AvgVideoCaption_81062_Content_64 = {
    Text = "Tolong rawat pita suaramu dengan lembut"
  },
  AvgVideoCaption_81062_Content_65 = {
    Text = "Ia belum sepenuhnya tertransformasi..."
  },
  AvgVideoCaption_81062_Content_66 = {
    Text = "Belenggu moral yang digunakan manusia untuk mengurung dirinya sendiri"
  },
  AvgVideoCaption_81062_Content_67 = {
    Text = "Sedang terlepas satu per satu, bukan?"
  },
  AvgVideoCaption_81062_Content_68 = {
    Text = "Seperti ular yang melepaskan kulit lama yang tidak berguna……"
  },
  AvgVideoCaption_81062_Content_69 = {
    Text = "Saya akan membebaskanmu..."
  },
  AvgVideoCaption_81062_Content_7 = {
    Text = "Tarik napas dalam"
  },
  AvgVideoCaption_81062_Content_70 = {
    Text = "Ya... begitulah membuat iris terbelah menjadi matriks heksagonal yang sempurna"
  },
  AvgVideoCaption_81062_Content_71 = {
    Text = "Mari kita puji wadah kuno yang akan segera terbangun ini…"
  },
  AvgVideoCaption_81062_Content_72 = {
    Text = "Untuk sepenuhnya mengucapkan selamat tinggal pada masa lalu yang bobrok"
  },
  AvgVideoCaption_81062_Content_73 = {
    Text = "Mari kita rendam topeng sosial ke dalam asam sulfat pekat…"
  },
  AvgVideoCaption_81062_Content_74 = {
    Text = "Beserta rekening bank dan ijazahmu yang konyol"
  },
  AvgVideoCaption_81062_Content_75 = {
    Text = "Melihat mereka membusuk dan larut seperti humus sarang serangga"
  },
  AvgVideoCaption_81062_Content_76 = {
    Text = "Bagus, bagus..."
  },
  AvgVideoCaption_81062_Content_77 = {
    Text = "Tarik napas dalam-dalam……"
  },
  AvgVideoCaption_81062_Content_78 = {
    Text = "Sekarang silakan ulangi setelahku"
  },
  AvgVideoCaption_81062_Content_79 = {
    Text = "Saya secara sukarela mencabut rantai gen inferior Homo sapiens"
  },
  AvgVideoCaption_81062_Content_8 = {
    Text = "Keberadaan kehangatan perapian perlahan-lahan merayap naik pergelangan kakimu"
  },
  AvgVideoCaption_81062_Content_80 = {
    Text = "Hubungkan sinaps saraf ke awan sarang"
  },
  AvgVideoCaption_81062_Content_81 = {
    Text = "Yang disebut manusia hanyalah mimikri yang konyol belaka"
  },
  AvgVideoCaption_81062_Content_82 = {
    Text = "Seperti kupu-kupu yang berpura-pura menjadi daun dalam waktu singkat"
  },
  AvgVideoCaption_81062_Content_83 = {
    Text = "Sekarang saatnya kembali ke rahim abadi kelompok"
  },
  AvgVideoCaption_81062_Content_84 = {
    Text = "Tidakkah kamu sudah tak mendengar suara detak jantung lagi?"
  },
  AvgVideoCaption_81062_Content_85 = {
    Text = "Frekuensi sayap kawanan serangga telah cukup menggantikan detakan yang menyedihkan itu ..."
  },
  AvgVideoCaption_81062_Content_86 = {
    Text = "Ucapkan selamat tinggal pada bangkai tua yang sedang terkarbonisasi itu"
  },
  AvgVideoCaption_81062_Content_87 = {
    Text = "Anda yang \"mati\" dalam arti hukum"
  },
  AvgVideoCaption_81062_Content_88 = {
    Text = "Akan menerima kantong fertilisasi sarang pertama setelah sepuluh menit"
  },
  AvgVideoCaption_81062_Content_89 = {
    Text = "Tutup kedua matamu"
  },
  AvgVideoCaption_81062_Content_9 = {
    Text = "Sekarang, bayangkan Anda sedang berjalan di trotoar Hyde Park"
  },
  AvgVideoCaption_81062_Content_90 = {
    Text = "Terima kegelapan yang ada di depan..."
  },
  AvgVideoCaption_81062_Content_91 = {
    Text = "Kemudian, buka kembali matamu yang sebenarnya…"
  },
  AvgVideoCaption_81062_Content_92 = {
    Text = "Selamat... sekarang kamu lebih dekat dengan Tuhan daripada siapa pun"
  },
  AvgVideoCaption_81062_Content_93 = {
    Text = "Melihat kebenaran alam semesta melalui mata lensa tiga ratus enam puluh derajat..."
  },
  AvgVideoCaption_81062_Content_94 = {
    Text = "Selamat datang mendengarkan resonansi triliunan jantung di kedalaman jalur..."
  },
  AvgVideoCaption_81062_Content_95 = {
    Text = "Selamat datang menjadi wadah sempurna-Nya..."
  },
  AvgVideoCaption_81062_Content_96 = {
    Text = "Selamat datang di rumah"
  },
  AvgVideoCaption_81283_Content_1 = {
    Text = "Kesedihanmu membuatku merasakan sakit"
  },
  AvgVideoCaption_81283_Content_10 = {
    Text = "Biarkan aku menyentuh jiwamu"
  },
  AvgVideoCaption_81283_Content_11 = {
    Text = "Menyentuh semua kesedihan dan keinginan terdalam yang tersembunyi dalam hatimu"
  },
  AvgVideoCaption_81283_Content_12 = {
    Text = "Ah, itu saja..."
  },
  AvgVideoCaption_81283_Content_13 = {
    Text = "Konsultasi psikologis ini, akhirnya mencapai tahap favoritku"
  },
  AvgVideoCaption_81283_Content_14 = {
    Text = "Kesedihan, ketakutan, ketidakberdayaan"
  },
  AvgVideoCaption_81283_Content_15 = {
    Text = "Neurotransmiter secara jujur mengakui tentang dirimu yang sebenarnya kepadaku"
  },
  AvgVideoCaption_81283_Content_16 = {
    Text = "Namun belum cukup, jauh dari cukup"
  },
  AvgVideoCaption_81283_Content_17 = {
    Text = "Tunjukkan padaku lebih banyak lagi!"
  },
  AvgVideoCaption_81283_Content_18 = {
    Text = "Lapisan demi lapisan menanggalkan hati dan jiwamu"
  },
  AvgVideoCaption_81283_Content_19 = {
    Text = "Tunjukkan padaku keputusasaan dan perjuanganmu yang terdalam"
  },
  AvgVideoCaption_81283_Content_2 = {
    Text = "Rasakan sepenuhnya"
  },
  AvgVideoCaption_81283_Content_20 = {
    Text = "Untuk saya nikmati..."
  },
  AvgVideoCaption_81283_Content_21 = {Text = "Ah, maaf"},
  AvgVideoCaption_81283_Content_22 = {
    Text = "Berbincang dengan pasien tingkat atas terlalu seru"
  },
  AvgVideoCaption_81283_Content_23 = {
    Text = "Sudah lama menunggu, silakan masuk"
  },
  AvgVideoCaption_81283_Content_24 = {
    Text = "Mari kita, memulai perjalanan batin bersama"
  },
  AvgVideoCaption_81283_Content_3 = {
    Text = "Juga memahami keinginanmu untuk mendapatkan kelahiran kembali"
  },
  AvgVideoCaption_81283_Content_4 = {
    Text = "Tidak apa-apa, serahkan semuanya padaku"
  },
  AvgVideoCaption_81283_Content_5 = {
    Text = "Aku akan membuatmu sembuh"
  },
  AvgVideoCaption_81283_Content_6 = {
    Text = "Menemukan diri sejati"
  },
  AvgVideoCaption_81283_Content_7 = {
    Text = "Sekarang, santai saja..."
  },
  AvgVideoCaption_81283_Content_8 = {
    Text = "Tunjukkan batinmu padaku"
  },
  AvgVideoCaption_81283_Content_9 = {
    Text = "Buka potensi bawah sadarmu dan spiritualitasmu padaku"
  },
  AvgVideoCaption_84327_Content_1 = {
    Text = "Kapal akan tenggelam! Cepat buka pintunya!"
  },
  AvgVideoCaption_84327_Content_10 = {
    Text = "Dia adalah satu-satunya \"penumpang\" di kapal Nautilus saat ini"
  },
  AvgVideoCaption_84327_Content_100 = {
    Text = "Tetapi saat ini, saya bukan lagi manusia"
  },
  AvgVideoCaption_84327_Content_101 = {
    Text = "Oleh karena itu, entitas yang pernah memanggil kita"
  },
  AvgVideoCaption_84327_Content_102 = {
    Text = "Membimbingku, menjanjikanku"
  },
  AvgVideoCaption_84327_Content_103 = {
    Text = "Negara yang tenggelam mengungkapkan masa lalunya di dalam arus dalam laut"
  },
  AvgVideoCaption_84327_Content_104 = {
    Text = "Dan kepala gading yang telah retak itu, juga menunjukkan kepada saya dewa yang sebenarnya"
  },
  AvgVideoCaption_84327_Content_105 = {
    Text = "Saat ini, kenyataan dan fatamorgana tidak lagi penting"
  },
  AvgVideoCaption_84327_Content_106 = {
    Text = "Bagi Tuhan, segalanya adalah ilusi, semuanya tidak berarti"
  },
  AvgVideoCaption_84327_Content_107 = {
    Text = "Air laut masih memeluk saya, mencakup saya, menelan saya"
  },
  AvgVideoCaption_84327_Content_108 = {
    Text = "Dan di balik pintu itu, ada dimensi dan ruang hampa yang tak berujung"
  },
  AvgVideoCaption_84327_Content_109 = {
    Text = "Otak dangkal saya telah sepenuhnya dirasuki oleh lautan yang dalam"
  },
  AvgVideoCaption_84327_Content_11 = {
    Text = "Apakah kamu menyelamatkanku?"
  },
  AvgVideoCaption_84327_Content_110 = {
    Text = "Tidak dapat berpikir sedikit pun"
  },
  AvgVideoCaption_84327_Content_111 = {
    Text = "Dan tubuhku, tunduk pada lautan ini"
  },
  AvgVideoCaption_84327_Content_112 = {
    Text = "Lautan tak berujung dan kehampaan yang luas"
  },
  AvgVideoCaption_84327_Content_113 = {
    Text = "Akan menjadi arah baru saya"
  },
  AvgVideoCaption_84327_Content_12 = {
    Text = "Selamat datang di Nautilus"
  },
  AvgVideoCaption_84327_Content_13 = {
    Text = "Saya adalah navigator kapal ini, Keperasan"
  },
  AvgVideoCaption_84327_Content_14 = {
    Text = "Silahkan menjaga kapal ini, ikuti aturan"
  },
  AvgVideoCaption_84327_Content_15 = {
    Text = "Dan masih mengingat kode sekoci, biasanya tercetak di belakang kartu kamar Anda"
  },
  AvgVideoCaption_84327_Content_16 = {
    Text = "Namun menurut aturan, para bajak laut tidak dapat memperoleh kartu kamar"
  },
  AvgVideoCaption_84327_Content_17 = {
    Text = "Maafkan saya"
  },
  AvgVideoCaption_84327_Content_18 = {
    Text = "Hah? Ini bukan masalah kartu rumah!"
  },
  AvgVideoCaption_84327_Content_19 = {
    Text = "Di sini, di sini adalah Aequor"
  },
  AvgVideoCaption_84327_Content_2 = {
    Text = "Tolong... aku... tolong aku..."
  },
  AvgVideoCaption_84327_Content_20 = {
    Text = "Saya bernapas di lautan! Hidup!"
  },
  AvgVideoCaption_84327_Content_21 = {
    Text = "Ah, pasti aku sudah gila"
  },
  AvgVideoCaption_84327_Content_22 = {
    Text = "Seperti yang mereka katakan, sejak mendapatkan ukiran kepala gading yang aneh itu, saya menjadi gila"
  },
  AvgVideoCaption_84327_Content_23 = {
    Text = "Apa itu ukiran kepala gading, apa itu Lemuria, semua itu adalah fatamorgana, semua itu adalah mimpi!"
  },
  AvgVideoCaption_84327_Content_24 = {
    Text = "Saat saya terbangun dari mimpi, saya akan pulang"
  },
  AvgVideoCaption_84327_Content_25 = {
    Text = "Ya, pulang, pulang..."
  },
  AvgVideoCaption_84327_Content_26 = {
    Text = "Sepertinya sekarang, Anda harus sudah memahami situasi Anda"
  },
  AvgVideoCaption_84327_Content_27 = {
    Text = "Ini adalah Situs Kapal Tenggelam Nautilus, ini juga Aequor"
  },
  AvgVideoCaption_84327_Content_28 = {
    Text = "Segera, kita akan tenggelam ke dasar laut"
  },
  AvgVideoCaption_84327_Content_29 = {
    Text = "Saya akan berusaha menghemat kehidupan Anda"
  },
  AvgVideoCaption_84327_Content_3 = {
    Text = "Hari itu adalah 12 September"
  },
  AvgVideoCaption_84327_Content_30 = {
    Text = "Tapi sebagai navigator dan satu-satunya awak kapal"
  },
  AvgVideoCaption_84327_Content_31 = {
    Text = "Saya harus dengan jujur memberi tahu penumpang tentang keterbatasan kemampuan saya"
  },
  AvgVideoCaption_84327_Content_32 = {
    Text = "Setelah hari itu, para bajak laut terjatuh dalam keheningan"
  },
  AvgVideoCaption_84327_Content_33 = {
    Text = "Dia tidak lagi berusaha melarikan diri, melainkan berdiri di depan jendela kabin yang penuh air"
  },
  AvgVideoCaption_84327_Content_34 = {
    Text = "Melihat lautan dalam melalui jendela, berbisik pelan"
  },
  AvgVideoCaption_84327_Content_35 = {
    Text = "Dia terkadang tertawa besar"
  },
  AvgVideoCaption_84327_Content_36 = {
    Text = "Kadang-kadang kegilaan"
  },
  AvgVideoCaption_84327_Content_37 = {
    Text = "Kadang-kadang berseru Lemuria"
  },
  AvgVideoCaption_84327_Content_38 = {
    Text = "Lemuria memanggilku"
  },
  AvgVideoCaption_84327_Content_39 = {
    Text = "Kadang berteriak \"Ibu,\" \"Pulang\""
  },
  AvgVideoCaption_84327_Content_4 = {
    Text = "Hari ke-791 Nautilus menjadi kapal hantu"
  },
  AvgVideoCaption_84327_Content_40 = {
    Text = "Lemuria, pulang……"
  },
  AvgVideoCaption_84327_Content_41 = {
    Text = "Saya akan kembali ke Lemuria..."
  },
  AvgVideoCaption_84327_Content_42 = {
    Text = "Aku telah berlayar ke banyak tempat, tetapi tidak pernah mendengar tentang \"Lemuria\""
  },
  AvgVideoCaption_84327_Content_43 = {
    Text = "Takutnya, penumpang tunggal dari Nodylius"
  },
  AvgVideoCaption_84327_Content_44 = {
    Text = "Telah terjangkit sindrom delusi maritim"
  },
  AvgVideoCaption_84327_Content_45 = {
    Text = "Itu adalah penyakit yang umum di laut"
  },
  AvgVideoCaption_84327_Content_46 = {
    Text = "Menurut deskripsi dokter kapal Ralph"
  },
  AvgVideoCaption_84327_Content_47 = {
    Text = "Ini adalah otak dangkal manusia"
  },
  AvgVideoCaption_84327_Content_48 = {
    Text = "Tidak dapat sepenuhnya memahami gejala yang disebabkan oleh lautan yang mendalam"
  },
  AvgVideoCaption_84327_Content_49 = {
    Text = "Saat ini, kita tidak sedang berlayar di laut"
  },
  AvgVideoCaption_84327_Content_5 = {
    Text = "Pembajakan gagal melarikan diri dari ditinggalkan oleh teman-temannya"
  },
  AvgVideoCaption_84327_Content_50 = {
    Text = "Namun berada di dalam laut, dan perlahan tenggelam ke dalam kedalaman laut dengan kapal Nautilus"
  },
  AvgVideoCaption_84327_Content_51 = {
    Text = "Keadaan ini cukup untuk membuat siapa pun Kegilaan"
  },
  AvgVideoCaption_84327_Content_52 = {
    Text = "Bahkan saya…"
  },
  AvgVideoCaption_84327_Content_53 = {
    Text = "Telah mati, kesadaran entah bagaimana terikat pada Nodylius"
  },
  AvgVideoCaption_84327_Content_54 = {
    Text = "Setelah menyelamatkan bajak laut muda, aku juga mengalami fatamorgana"
  },
  AvgVideoCaption_84327_Content_55 = {
    Text = "Saya melihat Nodylius pulang…"
  },
  AvgVideoCaption_84327_Content_56 = {
    Text = "Saya juga melihat Nodylius tenggelam…"
  },
  AvgVideoCaption_84327_Content_57 = {
    Text = "Pada awalnya, saya masih menjaga kewarasan saya"
  },
  AvgVideoCaption_84327_Content_58 = {
    Text = "Bedakan mana yang merupakan fatamorgana, mana yang nyata"
  },
  AvgVideoCaption_84327_Content_59 = {
    Text = "Tapi kemudian..."
  },
  AvgVideoCaption_84327_Content_6 = {
    Text = "Seiring dengan kapalnya Nautilus terbenam ke dalam lautan"
  },
  AvgVideoCaption_84327_Content_60 = {
    Text = "Saya mendengar, saya mendengar"
  },
  AvgVideoCaption_84327_Content_61 = {
    Text = "Dia memanggil kami!"
  },
  AvgVideoCaption_84327_Content_62 = {
    Text = "Apa pun yang tersesat, Tuhanku akan membimbing"
  },
  AvgVideoCaption_84327_Content_63 = {
    Text = "Apa pun yang diinginkan, Tuhanku akan memberi janji"
  },
  AvgVideoCaption_84327_Content_64 = {
    Text = "Ya, ya, bimbing saya, izinkan saya!"
  },
  AvgVideoCaption_84327_Content_65 = {
    Text = "Tuhan yang agung, bawa aku ke Lemuria, biarkan aku masuk ke dalam ranah dewa-Mu!"
  },
  AvgVideoCaption_84327_Content_66 = {
    Text = "Ranah dewa, di ranah dewa aku akan mendapatkan kebahagiaan, akan mendapatkan kehidupan abadi"
  },
  AvgVideoCaption_84327_Content_67 = {
    Text = "Akan pulang! Pulang! Pulang!"
  },
  AvgVideoCaption_84327_Content_68 = {
    Text = "Ralph benar"
  },
  AvgVideoCaption_84327_Content_69 = {
    Text = "Otak manusia yang dangkal tidak dapat sepenuhnya memahami lautan yang dalam"
  },
  AvgVideoCaption_84327_Content_7 = {
    Text = "Sebenarnya, saya benci bajak laut"
  },
  AvgVideoCaption_84327_Content_70 = {
    Text = "Oleh karena itu, ketika kota megah itu muncul di hadapku"
  },
  AvgVideoCaption_84327_Content_71 = {
    Text = "Saya menganggapnya sebagai ilusi yang disebabkan oleh sindrom delusi maritim"
  },
  AvgVideoCaption_84327_Content_72 = {
    Text = "Itu adalah kota yang tidak dapat diungkapkan dengan kata-kata, tidak dapat dinamakan"
  },
  AvgVideoCaption_84327_Content_73 = {
    Text = "Bersinar dengan cahaya redup kuno, terpaut teratur di dasar laut"
  },
  AvgVideoCaption_84327_Content_74 = {
    Text = "Di dalam lautan dalam yang gelap ini, tidur dalam kesunyian, berdiri"
  },
  AvgVideoCaption_84327_Content_75 = {
    Text = "Menunggu diam-diam"
  },
  AvgVideoCaption_84327_Content_76 = {
    Text = "Kami para pengunjung terperangkap dalam jebakan"
  },
  AvgVideoCaption_84327_Content_77 = {Text = "Lemuria!"},
  AvgVideoCaption_84327_Content_78 = {
    Text = "Itu adalah, Lemuria!"
  },
  AvgVideoCaption_84327_Content_79 = {
    Text = "Dia memanggil kami, Dia memanggil kami!"
  },
  AvgVideoCaption_84327_Content_8 = {
    Text = "Dengki pada semua yang menghalangi perjalanan aman kapal"
  },
  AvgVideoCaption_84327_Content_80 = {
    Text = "Bahaya, jangan dekati!"
  },
  AvgVideoCaption_84327_Content_81 = {
    Text = "Begitulah, penumpang tunggal dari Nodylius mati di depan mata saya"
  },
  AvgVideoCaption_84327_Content_82 = {
    Text = "Hanya menyisakan ukiran kepala gading yang aneh itu"
  },
  AvgVideoCaption_84327_Content_83 = {
    Text = "Aku tahu pilihan paling bijak saat ini seharusnya adalah apa"
  },
  AvgVideoCaption_84327_Content_84 = {Text = "Namun..."},
  AvgVideoCaption_84327_Content_85 = {
    Text = "Saya adalah seorang navigator, akrab dengan lautan adalah pekerjaan saya yang penting"
  },
  AvgVideoCaption_84327_Content_86 = {
    Text = "Ketika peta kesadaran mengalami kesalahan"
  },
  AvgVideoCaption_84327_Content_87 = {
    Text = "Apa yang saya lakukan bukanlah melarikan diri, tetapi memperbaiki"
  },
  AvgVideoCaption_84327_Content_88 = {
    Text = "<Red: Jadi, dekati itu>"
  },
  AvgVideoCaption_84327_Content_89 = {
    Text = "Dan memperbaiki kesalahan, perlu......"
  },
  AvgVideoCaption_84327_Content_9 = {Text = "Namun..."},
  AvgVideoCaption_84327_Content_90 = {
    Text = "Perlu memahami masalah dengan lebih mendalam, merasakan permasalahan"
  },
  AvgVideoCaption_84327_Content_91 = {
    Text = "Menjelajahi ranah tidur para dewa ini"
  },
  AvgVideoCaption_84327_Content_92 = {
    Text = "<Red: Jadi, tanggapi itu>"
  },
  AvgVideoCaption_84327_Content_93 = {
    Text = "Jalur kehidupan di dunia ini tidak dapat memandu ke kebahagiaan"
  },
  AvgVideoCaption_84327_Content_94 = {
    Text = "Hanya mereka yang menyerahkan segalanya yang berhak untuk melihat Ranah dewa"
  },
  AvgVideoCaption_84327_Content_95 = {
    Text = "<Red: Jadi, kembali kepada itu！>"
  },
  AvgVideoCaption_84327_Content_96 = {
    Text = "<Red: Persembahkan segalanya！>"
  },
  AvgVideoCaption_84327_Content_97 = {
    Text = "Akhirnya, setelah memberikan segalanya, aku melihat......"
  },
  AvgVideoCaption_84327_Content_98 = {
    Text = "Kehadiran yang megah, tak terhingga, dan tidak dapat dijelaskan……"
  },
  AvgVideoCaption_84327_Content_99 = {
    Text = "Otak manusia yang dangkal tidak dapat sepenuhnya memahami lautan yang dalam"
  },
  AvgVideoCaption_90244_Content_1 = {Text = "Ha..."},
  AvgVideoCaption_90244_Content_10 = {
    Text = "Tertangkap sangat dalam... bulu-bulu terjebak dengan darahnya"
  },
  AvgVideoCaption_90244_Content_100 = {
    Text = "Begitu banyak tempat dalam buku catatan yang belum kita kunjungi, sungguh ingin melihat semuanya"
  },
  AvgVideoCaption_90244_Content_101 = {
    Text = "Akan pergi, pasti"
  },
  AvgVideoCaption_90244_Content_102 = {
    Text = "Akhirnya, ksatria membawa putri kembali ke negeri"
  },
  AvgVideoCaption_90244_Content_103 = {
    Text = "Banyak bunga dilemparkan di jalan-jalan yang menyambut mereka"
  },
  AvgVideoCaption_90244_Content_104 = {
    Text = "Nama baik ksatria menyebar ke seluruh negeri"
  },
  AvgVideoCaption_90244_Content_105 = {
    Text = "Ah, sudah berakhir"
  },
  AvgVideoCaption_90244_Content_106 = {
    Text = "Selalu ingin tahu apa yang terjadi setelah akhir cerita bukan?"
  },
  AvgVideoCaption_90244_Content_107 = {
    Text = "Kakak, menurutmu bagaimana nasib ksatria itu nanti?"
  },
  AvgVideoCaption_90244_Content_108 = {
    Text = "Akankah dia mendapatkan kehormatan, kekayaan, dan cinta sang putri?"
  },
  AvgVideoCaption_90244_Content_109 = {
    Text = "Saya tidak tahu..."
  },
  AvgVideoCaption_90244_Content_11 = {
    Text = "Saya membersihkan semua hal kotor ini dulu"
  },
  AvgVideoCaption_90244_Content_110 = {
    Text = "Tapi setidaknya dia sudah mendapatkan kehormatan, bukan?"
  },
  AvgVideoCaption_90244_Content_111 = {
    Text = "Maka, dia menempuh perjalanan jauh untuk menyelamatkan sang putri"
  },
  AvgVideoCaption_90244_Content_112 = {
    Text = "Raja pasti akan memberinya hadiah, kan?"
  },
  AvgVideoCaption_90244_Content_113 = {
    Text = "Benar, seharusnya raja bukan orang yang pelit"
  },
  AvgVideoCaption_90244_Content_114 = {
    Text = "Dia melarikan putri dari kastil, kemudian melewati banyak sekali tempat"
  },
  AvgVideoCaption_90244_Content_115 = {
    Text = "Mungkin putri juga akan mencintainya?"
  },
  AvgVideoCaption_90244_Content_116 = {
    Text = "Hmm... Benar juga"
  },
  AvgVideoCaption_90244_Content_117 = {
    Text = "Meskipun ksatria tidak menginginkan apa pun"
  },
  AvgVideoCaption_90244_Content_118 = {
    Text = "Namun tetap akan mendapatkan segalanya"
  },
  AvgVideoCaption_90244_Content_119 = {
    Text = "Ternyata orang yang pemberani akhirnya pasti akan... mendapatkan... segalanya..."
  },
  AvgVideoCaption_90244_Content_12 = {
    Text = "......sakit? Maaf, aku akan lebih hati-hati"
  },
  AvgVideoCaption_90244_Content_120 = {
    Text = "(Sudah tidur... Pelarian beberapa hari ini benar-benar melelahkan.)"
  },
  AvgVideoCaption_90244_Content_121 = {
    Text = "(Banyak bulu yang jatuh, sayang sekali... Hm? Yang ini masih utuh.)"
  },
  AvgVideoCaption_90244_Content_122 = {
    Text = "(Simpan dulu, nanti saat ada waktu aku akan membuatkan kalung untuk Pollux)"
  },
  AvgVideoCaption_90244_Content_123 = {
    Text = "(Bulan bulat yang indah, langit berbintang yang indah.)"
  },
  AvgVideoCaption_90244_Content_124 = {
    Text = "(Apakah seperti dalam buku... Orang yang berani akan mendapatkan segalanya?)"
  },
  AvgVideoCaption_90244_Content_125 = {
    Text = "(Apakah cerita dalam buku itu tidak berbohong...)"
  },
  AvgVideoCaption_90244_Content_126 = {
    Text = "(Selamat malam, Ksatria Pollux)"
  },
  AvgVideoCaption_90244_Content_13 = {
    Text = "Yah, juga lumayanlah"
  },
  AvgVideoCaption_90244_Content_14 = {
    Text = "Daripada merobek dada pada saat upacara modifikasi, mengukir mantra pada organ sedikit demi sedikit"
  },
  AvgVideoCaption_90244_Content_15 = {
    Text = "Rasa sakit ini tidak seberapa"
  },
  AvgVideoCaption_90244_Content_16 = {
    Text = "......ya, di antara kita, kau selalu menanggung lebih banyak rasa sakit"
  },
  AvgVideoCaption_90244_Content_17 = {
    Text = "(Ah, celaka, salah ucap...)"
  },
  AvgVideoCaption_90244_Content_18 = {
    Text = "Sudah berlalu, kakak"
  },
  AvgVideoCaption_90244_Content_19 = {
    Text = "Dulu kita tidak bisa memutuskan apa-apa, tapi mulai sekarang kita bebas!"
  },
  AvgVideoCaption_90244_Content_2 = {
    Text = "Setelah melarikan diri ke sini, monster itu seharusnya tidak akan mengejar lagi"
  },
  AvgVideoCaption_90244_Content_20 = {
    Text = "Bacakan lagi cerita dari naskah Anda"
  },
  AvgVideoCaption_90244_Content_21 = {
    Text = "Seperti setiap kali setelah ritual rekonstruksi, mendengarkan cerita membuat luka menjadi tidak sakit"
  },
  AvgVideoCaption_90244_Content_22 = {Text = "Baik"},
  AvgVideoCaption_90244_Content_23 = {
    Text = "Jadi... mari kita bicara lagi tentang petualangan ksatria legendaris"
  },
  AvgVideoCaption_90244_Content_24 = {
    Text = "Akhirnya, ksatria mencapai kastil dan menemukan monster di bayangan itu"
  },
  AvgVideoCaption_90244_Content_25 = {
    Text = "Menanyakan keberadaan putri kepadanya"
  },
  AvgVideoCaption_90244_Content_26 = {
    Text = "Monster berwarna hijau gelap itu besar seperti raksasa"
  },
  AvgVideoCaption_90244_Content_27 = {
    Text = "Teriakan aneh dan menakutkan terdengar dari jauh dari dalam tubuh yang bergetar"
  },
  AvgVideoCaption_90244_Content_28 = {
    Text = "Ia mengangkat tinggi kapaknya"
  },
  AvgVideoCaption_90244_Content_29 = {
    Text = "Cahaya dingin seperti bulan sabit memotong keheningan aula"
  },
  AvgVideoCaption_90244_Content_3 = {
    Text = "Istirahat sedikit, aduh..."
  },
  AvgVideoCaption_90244_Content_30 = {
    Text = "Ksatria pemberani berdiri dengan tenang"
  },
  AvgVideoCaption_90244_Content_31 = {
    Text = "Hanya rambut pirang bergoyang sedikit di angin"
  },
  AvgVideoCaption_90244_Content_32 = {
    Text = "Kapak meluncur dengan berdesing, namun seketika berhenti sebelum menyentuh leher Ksatria"
  },
  AvgVideoCaption_90244_Content_33 = {
    Text = "\"Ini adalah serangan untuk memegang janjimu.\""
  },
  AvgVideoCaption_90244_Content_34 = {
    Text = "Monster itu berbisik dengan mulut menyeringai, suara bising seperti potongan besi berkarat saling menggesek"
  },
  AvgVideoCaption_90244_Content_35 = {
    Text = "\"Kau tidak mundur dalam duel hari ini, layak mendapatkan gelar ksatria.\""
  },
  AvgVideoCaption_90244_Content_36 = {
    Text = "Seperti kita tidak dikalahkan oleh monster hari ini!"
  },
  AvgVideoCaption_90244_Content_37 = {
    Text = "Pukulan kedua jatuh kembali"
  },
  AvgVideoCaption_90244_Content_38 = {
    Text = "Tetap berhenti tepat sebelum seperseribu, hanya menggores kulit ksatria..."
  },
  AvgVideoCaption_90244_Content_39 = {
    Text = "Polydeuces, bahkan bulu terbang terbesar telah patah"
  },
  AvgVideoCaption_90244_Content_4 = {
    Text = "Polydeuces! Sayapmu terluka parah"
  },
  AvgVideoCaption_90244_Content_40 = {
    Text = "Kamu biasanya sangat melindungi mereka..."
  },
  AvgVideoCaption_90244_Content_41 = {
    Text = "Tidak apa-apa, bulu-bulu akan tumbuh kembali, ini adalah lambang kebebasan"
  },
  AvgVideoCaption_90244_Content_42 = {
    Text = "Seperti ksatria, benar kan?"
  },
  AvgVideoCaption_90244_Content_43 = {
    Text = "Hmm... Luka di sekitar sudah dibersihkan"
  },
  AvgVideoCaption_90244_Content_44 = {
    Text = "Bulu kamu berantakan, biar aku bantu menyisirnya"
  },
  AvgVideoCaption_90244_Content_45 = {
    Text = "Terima kasih banyak, Ksatria Castor"
  },
  AvgVideoCaption_90244_Content_46 = {
    Text = "Silakan lanjutkan untuk menceritakan Cerita petualangan!"
  },
  AvgVideoCaption_90244_Content_47 = {
    Text = "Baiklah, aku mengerti"
  },
  AvgVideoCaption_90244_Content_48 = {
    Text = "Mata monster itu bersinar dengan cahaya terima kasih"
  },
  AvgVideoCaption_90244_Content_49 = {
    Text = "\"Ini adalah hukuman karena kau telah menyelamatkan putriku, tetapi mencuri kunci darinya, dan menyusup ke kastil.\""
  },
  AvgVideoCaption_90244_Content_5 = {
    Text = "Sial, baru-baru ini aku tidak bisa menghentikannya, seandainya aku..."
  },
  AvgVideoCaption_90244_Content_50 = {
    Text = "Ksatria akhirnya menyadari"
  },
  AvgVideoCaption_90244_Content_51 = {
    Text = "\"Gadis yang terjatuh ke dalam air itu adalah putrimu!\""
  },
  AvgVideoCaption_90244_Content_52 = {
    Text = "Monster itu mengangguk"
  },
  AvgVideoCaption_90244_Content_53 = {
    Text = "\"Benar, serangan terakhir berikutnya adalah pertarungan kita yang sesungguhnya.\""
  },
  AvgVideoCaption_90244_Content_54 = {
    Text = "Ksatria mengangkat pedangnya, mengarahkan ujung pedang ke atas memberi hormat kepada monster"
  },
  AvgVideoCaption_90244_Content_55 = {
    Text = "Saat itu bayangan monster tiba-tiba menghilang"
  },
  AvgVideoCaption_90244_Content_56 = {
    Text = "Ksatria maju dengan hati-hati"
  },
  AvgVideoCaption_90244_Content_57 = {
    Text = "Kastil yang kosong tertutup bayangan gelap yang berputar"
  },
  AvgVideoCaption_90244_Content_58 = {
    Text = "Hanya mendengar suara hantu menggema di telinganya"
  },
  AvgVideoCaption_90244_Content_59 = {
    Text = "\"Ksatria pemberani, untuk apa kau terus berjuang?"
  },
  AvgVideoCaption_90244_Content_6 = {
    Text = "Sudahlah, jangan bicara begitu, kita baru pertama kali pergi ke luar"
  },
  AvgVideoCaption_90244_Content_60 = {
    Text = "\"Apa untuk kemuliaan dan pemujaan?\""
  },
  AvgVideoCaption_90244_Content_61 = {
    Text = "Sekelompok rakyat jelata muncul entah dari mana, mereka berlapis-lapis melingkari ksatria itu"
  },
  AvgVideoCaption_90244_Content_62 = {
    Text = "Berbagai wajah yang tersenyum, terus-menerus memuji kemuliaannya"
  },
  AvgVideoCaption_90244_Content_63 = {
    Text = "Ksatria menyadari ketidakberesan dari bayangan itu"
  },
  AvgVideoCaption_90244_Content_64 = {
    Text = "Ekspresinya tidak goyah, segera memotong bayangan-bayangan palsu tersebut"
  },
  AvgVideoCaption_90244_Content_65 = {
    Text = "\"Lantas, apakah untuk hadiah dan kekayaan?\""
  },
  AvgVideoCaption_90244_Content_66 = {
    Text = "Seorang pelayan rendah hati datang ke depan ksatria"
  },
  AvgVideoCaption_90244_Content_67 = {
    Text = "Dia menggendong uang yang berkilauan dan mahkota mewah yang berhiaskan permata merah darah"
  },
  AvgVideoCaption_90244_Content_68 = {
    Text = "Dipersembahkan dengan menjilat pada ksatria"
  },
  AvgVideoCaption_90244_Content_69 = {
    Text = "Ksatria tidak melihat mahkota yang melambangkan kekayaan dan kekuasaan yang tak terbatas"
  },
  AvgVideoCaption_90244_Content_7 = {
    Text = "Lagipula, bukankah kita sudah berhasil kabur? Bersukacitalah sedikit, kita sudah sangat hebat!"
  },
  AvgVideoCaption_90244_Content_70 = {
    Text = "Menebas dan menghancurkan Fatamorgana pelayan itu"
  },
  AvgVideoCaption_90244_Content_71 = {
    Text = "Suara monster yang mencolok melanjutkan, \"Oh? Apakah itu untuk mendapatkan cinta sang putri?\""
  },
  AvgVideoCaption_90244_Content_72 = {
    Text = "Sosok indah putri turun di depan ksatria"
  },
  AvgVideoCaption_90244_Content_73 = {
    Text = "Bulu matanya yang panjang berkedip, dengan tatapan melamun dia bersandar ke pelukan ksatria"
  },
  AvgVideoCaption_90244_Content_74 = {
    Text = "Ksatria mengayunkan pedang menuju bayangan sang putri,"
  },
  AvgVideoCaption_90244_Content_75 = {
    Text = "\"Tidak, tidak sama sekali, aku bertempur hanya untuk menyelamatkan mereka yang menderita, agar yang lain tidak perlu bertempur lagi!\""
  },
  AvgVideoCaption_90244_Content_76 = {
    Text = "Pada saat ketika ksatria menyelesaikan kalimatnya"
  },
  AvgVideoCaption_90244_Content_77 = {
    Text = "Bayangan yang bergoyang seperti tentakel tak terhitung jumlahnya dan ilusi yang terasa nyata semuanya menghilang"
  },
  AvgVideoCaption_90244_Content_78 = {
    Text = "Dengan suara dentang, pedang yang diayunkan ksatria bertemu dengan kapak monster, menebaskan kapak itu terbang"
  },
  AvgVideoCaption_90244_Content_79 = {
    Text = "\"Kau telah membuktikan kemurahan hatimu, kesetiaan, dan kemurnianmu\""
  },
  AvgVideoCaption_90244_Content_8 = {
    Text = "...... kau benar, biarkan aku merawat lukamu dulu"
  },
  AvgVideoCaption_90244_Content_80 = {
    Text = "\"Sekarang, kau bisa membawa sang putri pergi.\""
  },
  AvgVideoCaption_90244_Content_81 = {
    Text = "Sosok hantu yang menakutkan ini berubah menjadi asap tipis yang perlahan-lahan memudar"
  },
  AvgVideoCaption_90244_Content_82 = {
    Text = "Yang tertinggal di tempat itu hanyalah baju besi kuno yang dilapisi karat hijau"
  },
  AvgVideoCaption_90244_Content_83 = {
    Text = "Ksatria membungkuk dalam-dalam memberi hormat pada baju zirah itu"
  },
  AvgVideoCaption_90244_Content_84 = {
    Text = "Dia melangkah naik satu demi satu melalui tangga spiral"
  },
  AvgVideoCaption_90244_Content_85 = {
    Text = "Akhirnya menemukan putri di puncak kastil"
  },
  AvgVideoCaption_90244_Content_86 = {
    Text = "Putri yang terperangkap di kastil, sungguh mirip dengan kita sebelumnya"
  },
  AvgVideoCaption_90244_Content_87 = {
    Text = "Namun tidak ada ksatria yang datang menyelamatkan kita..."
  },
  AvgVideoCaption_90244_Content_88 = {
    Text = "Kami menyelamatkan diri kami sendiri"
  },
  AvgVideoCaption_90244_Content_89 = {
    Text = "Kami menjadi ksatria kami sendiri"
  },
  AvgVideoCaption_90244_Content_9 = {Text = "Ya!"},
  AvgVideoCaption_90244_Content_90 = {
    Text = "Benar sekali! Hahaha"
  },
  AvgVideoCaption_90244_Content_91 = {
    Text = "Memikirkannya saja, selama putri pemberani mengangkat pedangnya"
  },
  AvgVideoCaption_90244_Content_92 = {
    Text = "Cerita ini tidak ada urusan dengan para ksatria"
  },
  AvgVideoCaption_90244_Content_93 = {
    Text = "Ya, tapi sekarang, ksatria tetap berhasil menyelamatkan sang putri"
  },
  AvgVideoCaption_90244_Content_94 = {
    Text = "Dia membawa putri naik kudanya, berlari di bawah langit berbintang dan bulan purnama,"
  },
  AvgVideoCaption_90244_Content_95 = {
    Text = "Mereka melintasi padang rumput yang luas dan arus mengapung yang jernih,"
  },
  AvgVideoCaption_90244_Content_96 = {
    Text = "Melewati pegunungan megah dan hutan yang lebat"
  },
  AvgVideoCaption_90244_Content_97 = {
    Text = "Padang rumput, gunung..."
  },
  AvgVideoCaption_90244_Content_98 = {
    Text = "Pikirkan ke mana kita akan pergi?"
  },
  AvgVideoCaption_90244_Content_99 = {
    Text = "Lautan, gurun, lahan pertanian, dan padang rumput"
  },
  AvgVideoCaption_96010_Content_1 = {
    Text = "Selamat datang di kastil kuno saya, Tuan Pikman"
  },
  AvgVideoCaption_96010_Content_10 = {Text = "Namun..."},
  AvgVideoCaption_96010_Content_100 = {Text = "Tentu saja"},
  AvgVideoCaption_96010_Content_101 = {
    Text = "Terus makan, Tuan Pikeman, makanlah"
  },
  AvgVideoCaption_96010_Content_102 = {
    Text = "Merobek daging dan tulangnya, memotong jantungnya"
  },
  AvgVideoCaption_96010_Content_103 = {
    Text = "Dengar permohonan jiwa-jiwa itu di telingamu"
  },
  AvgVideoCaption_96010_Content_104 = {
    Text = "Catat dengan setia setiap pemandangan yang Anda lihat"
  },
  AvgVideoCaption_96010_Content_105 = {
    Text = "Nikmatilah kejayaan sebagai seorang ghoul"
  },
  AvgVideoCaption_96010_Content_106 = {
    Text = "Setiap warga dari kerajaan saya"
  },
  AvgVideoCaption_96010_Content_107 = {
    Text = "Hidup untuk keabadian yang kejam ini"
  },
  AvgVideoCaption_96010_Content_108 = {
    Text = "Maka, makan malam yang menyenangkan ini harus berakhir"
  },
  AvgVideoCaption_96010_Content_109 = {
    Text = "Di festival arwah tahun ini, kita pasti akan menyaksikan sebuah mahakarya"
  },
  AvgVideoCaption_96010_Content_11 = {
    Text = "Mohon maaf, Tuan Pickman"
  },
  AvgVideoCaption_96010_Content_110 = {
    Text = "Selamat datang di Kota Pemakaman, pengrajin besar masa depan"
  },
  AvgVideoCaption_96010_Content_111 = {
    Text = "Tuan Pikman"
  },
  AvgVideoCaption_96010_Content_12 = {
    Text = "Lukisan masa lalumu"
  },
  AvgVideoCaption_96010_Content_13 = {
    Text = "Semuanya adalah karya-karya sederhana yang terkungkung dalam pandangan sempit masyarakat"
  },
  AvgVideoCaption_96010_Content_14 = {
    Text = "Dan itulah alasan saya mengundang Anda ke sini"
  },
  AvgVideoCaption_96010_Content_15 = {
    Text = "Perayaan besar kami membutuhkan sebuah lukisan yang tak tertandingi"
  },
  AvgVideoCaption_96010_Content_16 = {
    Text = "Dan Anda, perlu melihat seni yang sesungguhnya"
  },
  AvgVideoCaption_96010_Content_17 = {
    Text = "Sebuah jasad manusia?"
  },
  AvgVideoCaption_96010_Content_18 = {Text = "Ini…"},
  AvgVideoCaption_96010_Content_19 = {
    Text = "Apakah kamu menciumnya?"
  },
  AvgVideoCaption_96010_Content_2 = {
    Text = "Silakan duduk"
  },
  AvgVideoCaption_96010_Content_20 = {
    Text = "Aroma yang dihasilkan oleh kayu oak, cedar, dan vetiver"
  },
  AvgVideoCaption_96010_Content_21 = {
    Text = "Dia telah meresap di peti mati ini selama tiga abad"
  },
  AvgVideoCaption_96010_Content_22 = {
    Text = "Karena itu, dia memperoleh kehormatan untuk menjadi hidangan utama dari jamuan malam ini"
  },
  AvgVideoCaption_96010_Content_23 = {
    Text = "Persiapan penting sebelum makan"
  },
  AvgVideoCaption_96010_Content_24 = {
    Text = "0.5 inci luka pisau"
  },
  AvgVideoCaption_96010_Content_25 = {
    Text = "Pisahkan tulang dan daging di sepanjang leher punggung dan tulang kipas"
  },
  AvgVideoCaption_96010_Content_26 = {
    Text = "Apa yang kau lakukan... organ dalamnya..."
  },
  AvgVideoCaption_96010_Content_27 = {
    Text = "Sial, aku harus meninggalkan tempat ini"
  },
  AvgVideoCaption_96010_Content_28 = {
    Text = "Apa yang kalian lakukan... lepaskan aku"
  },
  AvgVideoCaption_96010_Content_29 = {
    Text = "Mohon tenang, Tuan Pelukis"
  },
  AvgVideoCaption_96010_Content_3 = {
    Text = "Saya mendengar bahwa seni sejati dapat ditemukan di kediaman raja ghoul……"
  },
  AvgVideoCaption_96010_Content_30 = {
    Text = "Kau telah menggoyahkan jiwa bahan makanan ini, dan mengganggu karyaku"
  },
  AvgVideoCaption_96010_Content_31 = {
    Text = "Saya dengan sengaja mengatur agar organ dalamnya tetap ada"
  },
  AvgVideoCaption_96010_Content_32 = {
    Text = "Organ dalam itu rumit dan kotor"
  },
  AvgVideoCaption_96010_Content_33 = {
    Text = "Tetapi setelah dimasak, mereka akan menjadi bagian paling mulia dan menarik"
  },
  AvgVideoCaption_96010_Content_34 = {
    Text = "Silakan, Tuan Pikman"
  },
  AvgVideoCaption_96010_Content_35 = {
    Text = "Separuh hati ini adalah milikmu"
  },
  AvgVideoCaption_96010_Content_36 = {
    Text = "Tidak… aku… aku tidak memiliki minat itu…"
  },
  AvgVideoCaption_96010_Content_37 = {
    Text = "Saya datang untuk mencari inspirasi……"
  },
  AvgVideoCaption_96010_Content_38 = {
    Text = "Apa hubungan memakan tubuh dengan seni?"
  },
  AvgVideoCaption_96010_Content_39 = {
    Text = "Ini bisa membantumu memasuki kreasi"
  },
  AvgVideoCaption_96010_Content_4 = {
    Text = "Saya meninggalkan segala sesuatu di dunia manusia untuk datang ke sini"
  },
  AvgVideoCaption_96010_Content_40 = {
    Text = "Memahami ghoul, menjadi ghoul"
  },
  AvgVideoCaption_96010_Content_41 = {
    Text = "Setelah itu, kuas Anda baru bisa menyentuh keindahan sejati"
  },
  AvgVideoCaption_96010_Content_42 = {
    Text = "Kebenaran karya seni, kau selalu mengetahuinya"
  },
  AvgVideoCaption_96010_Content_43 = {
    Text = "Jadi Anda meninggalkan dunia manusia, datang ke kastil saya"
  },
  AvgVideoCaption_96010_Content_44 = {
    Text = "Benar, tetapi …"
  },
  AvgVideoCaption_96010_Content_45 = {
    Text = "Nikmatilah, Tuan Pikman"
  },
  AvgVideoCaption_96010_Content_46 = {Text = "Demi Seni"},
  AvgVideoCaption_96010_Content_47 = {Text = "Ini…"},
  AvgVideoCaption_96010_Content_48 = {
    Text = "Benar, Tuan Pikman"
  },
  AvgVideoCaption_96010_Content_49 = {
    Text = "Di telinga Anda berbisik"
  },
  AvgVideoCaption_96010_Content_5 = {
    Text = "Namun sekarang, restoran klise ini"
  },
  AvgVideoCaption_96010_Content_50 = {
    Text = "Adalah jiwa yang dimakan"
  },
  AvgVideoCaption_96010_Content_51 = {
    Text = "Jiwa... jiwa?"
  },
  AvgVideoCaption_96010_Content_52 = {
    Text = "Manusia sering menggambarkan kita sebagai makhluk pemakan bangkai yang rendah"
  },
  AvgVideoCaption_96010_Content_53 = {
    Text = "Namun para ghoul tidak menginginkan daging busuk"
  },
  AvgVideoCaption_96010_Content_54 = {
    Text = "Yang benar-benar kami pedulikan, adalah jiwa di bawah daging yang busuk"
  },
  AvgVideoCaption_96010_Content_55 = {
    Text = "Adalah ingatan berharga yang dikubur oleh makam"
  },
  AvgVideoCaption_96010_Content_56 = {
    Text = "Tuan Pikeman, jari-jari Anda yang gemetar"
  },
  AvgVideoCaption_96010_Content_57 = {
    Text = "Mengungkapkan ketakutan dan kegembiraan Anda"
  },
  AvgVideoCaption_96010_Content_58 = {
    Text = "Ayo, telan jantung ini"
  },
  AvgVideoCaption_96010_Content_59 = {
    Text = "Beritahu aku, apa yang kau lihat?"
  },
  AvgVideoCaption_96010_Content_6 = {
    Text = "Seperti kuburan inspirasi"
  },
  AvgVideoCaption_96010_Content_60 = {
    Text = "Saya melihat……"
  },
  AvgVideoCaption_96010_Content_61 = {
    Text = "Adalah kerajaan manusia, mengejar raja yang mencari keabadian……"
  },
  AvgVideoCaption_96010_Content_62 = {
    Text = "Menemukan tempat ini……"
  },
  AvgVideoCaption_96010_Content_63 = {
    Text = "Dia datang membawa pasukan manusia, memasuki kota kerajaan ini"
