  AvgVideoCaption_96010_Content_64 = {
    Text = "Darah……"
  },
  AvgVideoCaption_96010_Content_65 = {
    Text = "Anggota badan terputus……"
  },
  AvgVideoCaption_96010_Content_66 = {
    Text = "Pembunuhan massal……"
  },
  AvgVideoCaption_96010_Content_67 = {
    Text = "Adalah Anda, Tuan Dulcein……"
  },
  AvgVideoCaption_96010_Content_68 = {
    Text = "Anda memeluk mayatnya……"
  },
  AvgVideoCaption_96010_Content_69 = {
    Text = "Kalian menari di bawah sinar bulan..."
  },
  AvgVideoCaption_96010_Content_7 = {
    Text = "Saya telah melihat lukisan Anda"
  },
  AvgVideoCaption_96010_Content_70 = {
    Text = "Cahayanya seperti bulan malam ini..."
  },
  AvgVideoCaption_96010_Content_71 = {
    Text = "Para ghoul... sedang memakan pasangan mereka sendiri!"
  },
  AvgVideoCaption_96010_Content_72 = {
    Text = "Tuan yang gagah berani ini"
  },
  AvgVideoCaption_96010_Content_73 = {
    Text = "Mengambil segalanya yang dia inginkan dengan pasukannya"
  },
  AvgVideoCaption_96010_Content_74 = {
    Text = "Namun dia tetap tidak puas"
