  AvgVideoCaption_96010_Content_75 = {
    Text = "Dia ingin merebut keabadian dari kerajaan ku"
  },
  AvgVideoCaption_96010_Content_76 = {
    Text = "Namun kebodohannya tidak pernah memahaminya"
  },
  AvgVideoCaption_96010_Content_77 = {
    Text = "Keabadian ghoul adalah menyerahkan tubuh mereka sendiri ke meja makan"
  },
  AvgVideoCaption_96010_Content_78 = {
    Text = "Untuk menukar kekekalan dari ingatan"
  },
  AvgVideoCaption_96010_Content_79 = {
    Text = "Kami memotong tubuh kerabat, menggigit jiwa kerabat"
