  },
  AvgVideoCaption_96010_Content_93 = {
    Text = "Dia datang untuk keabadian, maka aku akan menganugerahkan keabadian padanya!"
  },
  AvgVideoCaption_96010_Content_94 = {
    Text = "Fosforesensi jiwa berwarna hijau keabu-abuan ini......"
  },
  AvgVideoCaption_96010_Content_95 = {
    Text = "Darah yang segar dan cerah ini......"
  },
  AvgVideoCaption_96010_Content_96 = {
    Text = "Cat warna apa yang bisa mencocokkan pemandangan yang belum pernah terjadi sebelumnya ini"
