  AvgVideoCaption_98516_Content_3 = {
    Text = "Hehe, bukankah ini justru menunjukkan bahwa kakak terkenal?"
  },
  AvgVideoCaption_98516_Content_30 = {
    Text = "Mereka masih menyebalkan"
