  AvgVideoCaption_98516_Content_33 = {
    Text = "Dengan demikian, kunjungan waktu berakhir"
  },
  AvgVideoCaption_98516_Content_34 = {
    Text = "Jumlah orangnya jauh lebih banyak， tetapi……"
  },
  AvgVideoCaption_98516_Content_35 = {
    Text = "Saya justru berminat untuk menikmati jeritan kalian!"
