  },
  AvgVideoCaption_98516_Content_59 = {
    Text = "Agar jiwa kalian selamanya hidup dalam penderitaan!"
  },
  AvgVideoCaption_98516_Content_6 = {
    Text = "Seandainya saja, saya seharusnya mengirim kamu untuk menghadapi para tuan itu"
  },
  AvgVideoCaption_98516_Content_60 = {Text = "Benarkah?"},
  AvgVideoCaption_98516_Content_61 = {
    Text = "Sangat disayangka"
  },
  AvgVideoCaption_98516_Content_62 = {
    Text = "Karena jiwa anak itu sudah kembali padaku"
  },
  AvgVideoCaption_98516_Content_63 = {
    Text = "Selain itu, dia tidak bernama Lox"
  },
  AvgVideoCaption_98516_Content_64 = {
    Text = "Saya juga tidak bernama Keli"
  },
  AvgVideoCaption_98516_Content_65 = {
    Text = "Tidak, tidak mungkin!"
  },
  AvgVideoCaption_98516_Content_66 = {
    Text = "Bagaimana kamu masih hidup!"
  },
  AvgVideoCaption_98516_Content_67 = {
    Text = "Jika Anda memiliki kekuatan seperti itu, mengapa..."
  },
  AvgVideoCaption_98516_Content_68 = {
    Text = "Tentu saja untuk memenuhi keinginan kalian"
  },
  AvgVideoCaption_98516_Content_69 = {
    Text = "Kamu tidak suka itu?"
  },
  AvgVideoCaption_98516_Content_7 = {
    Text = "Jangan, jangan, kakak"
  },
  AvgVideoCaption_98516_Content_70 = {
    Text = "Menyukai melihat wajah mangsa"
  },
  AvgVideoCaption_98516_Content_71 = {
    Text = "Tunjukkan ekspresi putus asa yang kamu miliki sekarang"
  },
  AvgVideoCaption_98516_Content_72 = {
    Text = "Aaaaaaaaaaaaaaaah!"
  },
  AvgVideoCaption_98516_Content_73 = {
    Text = "Bersyukurlah, aku merasa cukup baik sekarang"
  },
  AvgVideoCaption_98516_Content_74 = {
    Text = "Menyiksa para bajingan yang menginjak kemanusiaan seperti kalian selalu membuatku senang"
  },
  AvgVideoCaption_98516_Content_75 = {
    Text = "Sebagai imbalan, biarkan kamu menikmatinya"
  },
  AvgVideoCaption_98516_Content_76 = {
    Text = "Penuh dengan niat jahat dan keinginan!"
  },
  AvgVideoCaption_98516_Content_77 = {
    Text = "Giling semua tulang menjadi bubuk, ambil separuh dari sisa tulang dari dalam tubuh"
  },
  AvgVideoCaption_98516_Content_78 = {
    Text = "Tuangkan sisa tulang ke dalam rongga mata, menggilingnya bersama bola mata hingga struktur benar-benar rusak"
  },
  AvgVideoCaption_98516_Content_79 = {
    Text = "Robek daging, temukan saraf yang telanjang"
  },
  AvgVideoCaption_98516_Content_8 = {
    Text = "Saya hanya menghidupkan suasana"
  },
  AvgVideoCaption_98516_Content_80 = {
    Text = "Ramas dan keluarkan seluruh potongan"
  },
  AvgVideoCaption_98516_Content_81 = {
    Text = "Sekali lagi, gunakan laras peluru yang membara untuk membakar luka dan menghentikan pendarahan"
  },
  AvgVideoCaption_98516_Content_82 = {
    Text = "Pastikan terhukum tidak kehilangan terlalu banyak darah dan menjadi kering"
  },
  AvgVideoCaption_98516_Content_83 = {
    Text = "Masukkan cairan tubuh yang dikumpulkan ke saluran pernapasa"
  },
  AvgVideoCaption_98516_Content_84 = {
    Text = "Menjaga agar terpidana tetap dalam keadaan setengah tercekik"
  },
  AvgVideoCaption_98516_Content_85 = {
    Text = "Buka pikiran, terus lakukan rangsangan, untuk mencegah target pingsan"
  },
  AvgVideoCaption_98516_Content_86 = {
    Text = "Ayo lihat dari jauh..."
  },
  AvgVideoCaption_98516_Content_87 = {
    Text = "Ikatan yang baik, sangat cocok untuk orang-orang sepertimu"
  },
  AvgVideoCaption_98516_Content_88 = {
    Text = "Sampai di sini saja kali ini"
  },
  AvgVideoCaption_98516_Content_89 = {
    Text = "Saya sudah agak bosan"
  },
  AvgVideoCaption_98516_Content_9 = {
    Text = "Dan saya lebih suka kamu berkata, \"Orang-orang seperti mereka yang gelap dan busuk, secara alami menyukai tempat seperti ini\""
  },
  AvgVideoCaption_98516_Content_90 = {
    Text = "Hilanglah, kotoran yang menjijikka"
  },
  AvgVideoCaption_98516_Content_91 = {
    Text = "Selanjutnya, biarkan saya mencari, di mana benda itu berada"
  },
  AvgVideoCaption_98516_Content_92 = {
    Text = "Ditemukan, patung kekacauan tak berwajah"
  },
  AvgVideoCaption_98516_Content_93 = {
    Text = "Saya sudah bilang, tidak peduli di mana Anda bersembunyi, saya akan menemukan Anda"
  },
  AvgVideoCaption_98516_Content_94 = {
    Text = "Ucapkan selamat tinggal kepada kesadaranmu yang satu ini, oh kesenangan yang kotor!"
  },
  AvgVideoCaption_98516_Content_95 = {
    Text = "Ah, betapa indahnya hari ini"
  },
  AvgVideoCaption_98516_Content_96 = {
    Text = "Selanjutnya…… anak-anak kecil dan pemuda, tidurlah yang cukup"
  },
  AvgVideoCaption_98516_Content_97 = {
    Text = "Saatnya untuk bangkit dan bergerak, bakar semangat sepenuhnya!"
  },
  AvgVideoCaption_98516_Content_98 = {
    Text = "Hancurkan semua kejahatan ini!"
  }
})
return Text_AvgVideoCaption
